INSERT INTO `wp_e_submissions_values` VALUES (1,1,'name','Mishra'),(2,1,'email','anaya.dgtlsolution@gmail.com'),(3,1,'field_d4e86eb','Re: SEO Foundation Setup'),(4,1,'message','Hi,\r\n\r\nI noticed your website http://localhost/Khumbu/teknopremium is newly launched—congratulations on getting it live!\r\n\r\nAt this stage, setting up a strong SEO foundation is crucial so search engines can properly crawl, index, and understand your site.\r\n\r\nI help new websites with essential SEO setup including keyword structure, meta tags, technical SEO, sitemap indexing, and Google Search Console configuration.\r\n\r\nWould you like me to share a few quick recommendations to improve your website’s early visibility?\r\n\r\nBest regards,\r\nAnaya'),(5,2,'name','RobertWal'),(6,2,'email','zekisuquc419@gmail.com'),(7,2,'field_d4e86eb','Hallo i am writing about your the price'),(8,2,'message','Γεια σου, ήθελα να μάθω την τιμή σας.');
