  `action` varchar(100) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `ip` varchar(39) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `site_id` (`site_id`),
  KEY `blog_id` (`blog_id`),
  KEY `object_id` (`object_id`),
  KEY `user_id` (`user_id`),
