\\u002d\\u002dcustom\\u002d\\u002dgap\\u002d\\u002dhorizontal)))\"} -->\n<div style=\"height:calc( 0.25 * var(--wp--style--root--padding-right, var(--wp--custom--gap--horizontal)))\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"40%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:40%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"\"} -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Estamos dedicados a crear piezas atemporales que resisten la prueba del tiempo. Cada prenda y accesorio en nuestra colección es un testimonio de nuestro compromiso inquebrantable con la calidad y la artesanía. Nos enorgullece utilizar solo los mejores materiales y emplear una atención meticulosa al detalle en cada paso del proceso de creación. Desde la costura hasta los toques finales, nuestros productos están diseñados cuidadosamente para exudar durabilidad, longevidad y elegancia atemporal. Cuando compras con nosotros, puedes confiar en que estás invirtiendo en elementos que no solo son elegantes, sino que también están hechos para durar, asegurando años de disfrute y uso. Creemos en una moda que no solo se ve bien, sino que también hace el bien por el planeta y sus habitantes. Por eso estamos dedicados a reducir el impacto ambiental y social de la industria de la ropa y los accesorios. Cuando compras con nosotros, puedes sentirte seguro sabiendo que tu compra apoya un enfoque más sostenible y ético de la moda, haciendo una diferencia positiva en el mundo.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"calc( 0.25 * var(\\u002d\\u002dwp\\u002d\\u002dstyle\\u002d\\u002droot\\u002d\\u002dpadding-right, var(\\u002d\\u002dwp\\u002d\\u002dcustom\\u002d\\u002dgap\\u002d\\u002dhorizontal)))\"} -->\n<div style=\"height:calc( 0.25 * var(--wp--style--ro