,\"spacing\":{\"margin\":{\"right\":\"5px\"}}}} -->\n<p class=\"has-text-color\" style=\"color:#ffe8a4;margin-right:5px\">★</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"0.7em\"}},\"textColor\":\"foreground\"} -->\n<p class=\"has-foreground-color has-text-color\" style=\"font-size:0.7em\">\n				<strong>4.2</strong>(1.079 reseñas)\n			</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"8px\",\"padding\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"},\"margin\":{\"top\":\"2px\",\"bottom\":\"0px\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:2px;margin-bottom:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"1.2em\"}},\"textColor\":\"foreground\"} -->\n<p class=\"has-foreground-color has-text-color\" style=\"font-size:1.2em\">\n				<strong><sup><sub>$</sub></sup>37,49</strong>\n			</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"0.7em\"},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"color\":{\"text\":\"#7c0a99\"}}} -->\n<p class=\"has-text-color\" style=\"color:#7c0a99;font-size:0.7em\">Ahórrate 10 $ <s>era 47,49 $</s></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"18px\"}},\"textColor\":\"foreground\"} -->\n<p class=\"has-foreground-color has-text-color\" style=\"font-size:18px\">Diseñada pensando en tu bienestar, esta silla cuenta con un respaldo contorneado que proporciona un soporte lumbar excepcional, ayudando a reducir la tensión en tu espalda durante largas horas de sentado. Los mecanismos de altura y inclinaci