.9.2\";a:2:{s:7:\"Changed\";a:1:{s:4:\"core\";a:6:{i:0;s:85:\"Introduced a custom scissors icon and updated button title for the TinyMCE extension.\";i:1;s:50:\"Improved back-navigation styling on the edit page.\";i:2;s:78:\"Refined layout for column names and action buttons in the Cloud Snippets list.\";i:3;s:56:\"Enhanced overall styling of cloud-related UI components.\";i:4;s:76:\"Optimized cloud search with more efficient pagination and snippet retrieval.\";i:5;s:83:\"Introduced groundwork to prevent Composer dependency collisions with other plugins.\";}}s:5:\"Fixed\";a:1:{s:4:\"core\";a:2:{i:0;s:80:\"Improved sanitization and normalization across Cloud API and pagination outputs.\";i:1;s:72:\"Resolved various TinyMCE issues reported in the WordPress support forum.\";}}}}}','off'),(146905,'_transient_timeout_pa_license_info','1788751623','off'),(146906,'_transient_pa_license_info','a:2:{s:6:\"status\";s:7:\"invalid\";s:2:\"id\";s:0:\"\";}','off'),(146907,'_transient_woocommerce_webhook_ids_status_active','a:0:{}','on'),(146914,'_site_transient_timeout_woocommerce_blocks_patterns','1790848808','off'),(146915,'_site_transient_woocommerce_blocks_patterns','a:2:{s:7:\"version\";s:6:\"11.0.1\";s:8:\"patterns\";a:41:{i:0;a:11:{s:5:\"title\";s:6:\"Banner\";s:4:\"slug\";s:25:\"woocommerce-blocks/banner\";s:11:\"description\";s:0:\"\";s:13:\"viewportWidth\";s:0:\"\";s:10:\"categories\";s:29:\"WooCommerce, featured-selling\";s:8:\"keywords\";s:0:\"\";s:10:\"blockTypes\";s:0:\"\";s:8:\"inserter\";s:0:\"\";s:11:\"featureFlag\";s:0:\"\";s:13:\"templateTypes\";s:0:\"\";s:6:\"source\";s:10:\"banner.php\";}i:1;a:11:{s:5:\"title\";s:23:\"Coming Soon Entire Site\";s:4:\"slug\";s:35:\"woocommerce/coming-soon-entire-site\";s:11:\"description\";s:0:\"\";s:13:\"viewportWidth\";s:0:\"\";s:10:\"categories\";s:11:\"WooCommerce\";s:8:\"keywords\";s:0:\"\";s:10:\"blockTypes\";s:0:\"\";s:8:\"inserter\";s:5:\"false\";s:11:\"featureFlag\";s:17:\"launch-your-store\";s:13:\"templateTypes\";s:0