loads.wordpress.org/translation/core/7.0/yor.zip\";s:3:\"iso\";a:3:{i:1;s:2:\"yo\";i:2;s:3:\"yor\";i:3;s:3:\"yor\";}s:7:\"strings\";a:1:{s:8:\"continue\";s:18:\"Tẹ̀síwájú si\";}}s:5:\"zh_TW\";a:8:{s:8:\"language\";s:5:\"zh_TW\";s:7:\"version\";s:3:\"7.0\";s:7:\"updated\";s:19:\"2026-04-27 20:54:39\";s:12:\"english_name\";s:16:\"Chinese (Taiwan)\";s:11:\"native_name\";s:12:\"繁體中文\";s:7:\"package\";s:62:\"https://downloads.wordpress.org/translation/core/7.0/zh_TW.zip\";s:3:\"iso\";a:2:{i:1;s:2:\"zh\";i:2;s:3:\"zho\";}s:7:\"strings\";a:1:{s:8:\"continue\";s:6:\"繼續\";}}s:5:\"zh_HK\";a:8:{s:8:\"language\";s:5:\"zh_HK\";s:7:\"version\";s:6:\"6.2.10\";s:7:\"updated\";s:19:\"2022-07-15 15:25:03\";s:12:\"english_name\";s:19:\"Chinese (Hong Kong)\";s:11:\"native_name\";s:12:\"香港中文\";s:7:\"package\";s:65:\"https://downloads.wordpress.org/translation/core/6.2.10/zh_HK.zip\";s:3:\"iso\";a:2:{i:1;s:2:\"zh\";i:2;s:3:\"zho\";}s:7:\"strings\";a:1:{s:8:\"continue\";s:6:\"繼續\";}}s:5:\"zh_CN\";a:8:{s:8:\"language\";s:5:\"zh_CN\";s:7:\"version\";s:3:\"7.0\";s:7:\"updated\";s:19:\"2026-05-21 05:54:13\";s:12:\"english_name\";s:15:\"Chinese (China)\";s:11:\"native_name\";s:12:\"简体中文\";s:7:\"package\";s:62:\"https://downloads.wordpress.org/translation/core/7.0/zh_CN.zip\";s:3:\"iso\";a:2:{i:1;s:2:\"zh\";i:2;s:3:\"zho\";}s:7:\"strings\";a:1:{s:8:\"continue\";s:6:\"继续\";}}}','off'),(147539,'_site_transient_timeout_theme_roots','1788258538','off'),(147540,'_site_transient_theme_roots','a:4:{s:15:\"hello-elementor\";s:7:\"/themes\";s:16:\"twentytwentyfive\";s:7:\"/themes\";s:16:\"twentytwentyfour\";s:7:\"/themes\";s:17:\"twentytwentythree\";s:7:\"/themes\";}','off'),(147541,'_transient_ekit_lite_mailchimp_migrate','3.10.02','on'),(147543,'_site_transient_update_plugins','O:8:\"stdClass\":5:{s:12:\"last_checked\";i:1788257037;s:8:\"response\";a:4:{s:55:\"premium-addons-pro/premium-addons-pro-for-elementor.php\";O:8:\"stdClass\":23:{s:4:\"name\";s:18:\"Premium Addons Pro\";s:11:\"new_version\";s:6:\"2.9.64\";s:14:\"stable_version\";s:6:\"2.9.64\";s:8:\"sections\";O:8:\"stdClass\":3:{s:11:\"description\";s:4257:\"<p>This plugin is an extension to Premium Addons for Elementor Plugin that includes Pro Elementor widgets and Addons for Elementor Page Builder. Visit <a href=\"https://www.premiumaddons.com/\">Premium Addons Website</a> to check widgets and addons demos.</p>\n<p>Premium Addons PRO plugin’s widgets are cross browser compatible and also fully responsive, Your website will rock on all browsers as well as tables and mobile devices.</p>\n<p>When using Premium Addons’ widgets you will notice that it has more customization options than any other widget in other plugin.</p>\n<p>Premium Addons PRO can be used only as a complement of Elementor page builder plugin as it’s not a standalone plugin.</p>\n<h3>Features</h3>\n<ul>\n<li>Fully Customizable Elements.</li>\n<li>Options panel for enabling desired elements only for faster performance.</li>\n<li>Free Support through online forums.</li>\n</ul>\n<h3>Available Elements</h3>\n<ol>\n<li><a href=\"https://premiumaddons.com/alert-box-widget-for-elementor-page-builder/\">Premium Alert Box</a></li>\n<li><a href=\"https://premiumaddons.com/animated-section-gradients-for-elementor-page-builder/\">Premium Animated Container Gradient</a></li>\n<li><a href=\"https://premiumaddons.com/behance-feed-widget-for-elementor-page-builder/\">Premium Behance Feed</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-charts-widget/\">Premium Charts</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-content-toggle-widget/\">Premium Content Toggle</a></li>\n<li><a href=\"https://premiumaddons.com/dual-header-widget-for-elementor-page-builder/\">Premium Divider</a></li>\n<li><a href=\"https://premiumaddons.com/facebook-feed-widget-for-elementor-page-builder-2/\">Premium Facebook Feed</a></li>\n<li><a href=\"https://premiumaddons.com/facebook-reviews-widget-for-elementor-page-builder/\">Premium Facebook Reviews</a></li>\n<li><a href=\"https://premiumaddons.com/flip-box-widget-for-elementor-page-builder/\">Premium Flip Box</a></li>\n<li><a href=\"https://premiumaddons.com/google-reviews-for-elementor-page-builder/\">Premium Google Reviews</a></li>\n<li><a href=\"https://premiumaddons.com/icon-box-widget-for-elementor-page-builder/\">Premium Icon Box</a></li>\n<li><a href=\"https://premiumaddons.com/ihover-widget-for-elementor-page-builder/\">Premium iHover</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-image-accordion-widget/\">Premium Image Accordion</a></li>\n<li><a href=\"https://premiumaddons.com/image-comparison-widget-for-elementor-page-builder/\">Premium Image Comparison</a></li>\n<li><a href=\"https://premiumaddons.com/image-hotspots-widget-for-elementor-page-builder/\">Premium Image Hotspots</a></li>\n<li><a href=\"https://premiumaddons.com/image-layers-widget-for-elementor-page-builder/\">Premium Image Layers</a></li>\n<li><a href=\"https://premiumaddons.com/instagram-feed-widget-for-elementor-page-builder/\">Premium Instagram Feed</a></li>\n<li><a href=\"https://premiumaddons.com/ken-burns-section-addon-for-elementor-page-builder/\">Premium Ken Burns</a></li>\n<li><a href=\"https://premiumaddons.com/magic-section-widget-for-elementor-page-builder/\">Premium Magic Section</a></li>\n<li><a href=\"https://premiumaddons.com/multi-scroll-widget-for-elementor-page-builder/\">Premium Multi Scroll</a></li>\n<li><a href=\"https://premiumaddons.com/parallax-section-addon-for-elementor-page-builder/\">Premium Parallax</a></li>\n<li><a href=\"https://premiumaddons.com/particles-section-addon-for-elementor-page-builder/\">Premium Particles</a></li>\n<li><a href=\"https://premiumaddons.com/preview-window-widget-for-elementor-page-builder/\">Premium Preview Window</a></li>\n<li><a href=\"https://premiumaddons.com/table-widget-for-elementor-page-builder/\">Premium Tables</a></li>\n<li><a href=\"https://premiumaddons.com/twitter-feed-widget-for-elementor-page-builder/\">Premium Twitter Feed</a></li>\n<li><a href=\"https://premiumaddons.com/tabs-widget-for-elementor-page-builder-2/\">Premium Tabs</a></li>\n<li><a href=\"https://premiumaddons.com/unfold-widget-for-elementor-page-builder/\">Premium Unfold</a></li>\n<li><a href=\"https://premiumaddons.com/whatsapp-widget-for-elementor-page-builder/\">Premium WhatsApp Chat</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-yelp-reviews-widget/\">Premium Yelp Reviews</a></li>\n</ol>\";s:9:\"changelog\";s:35903:\"<h4> 2.9.64 </h4>\n<ul>\n<li>Fixed: Duplicate CSS rules applied.</li>\n</ul>\n<h4> 2.9.63 </h4>\n<ul>\n<li>Fixed: Anchoring section in a page with Horizontal Scroll not working.</li>\n<li>Fixed: Animated Gradient addon not working in some cases.</li>\n</ul>\n<h4> 2.9.62 </h4>\n<ul>\n<li>Tweak: Minor improvements in Global Badge addon for better usability.</li>\n</ul>\n<h4> 2.9.61 </h4>\n<ul>\n<li>New: Added CSS Selector option in Global Badge addon to display badges on custom elements.</li>\n<li>New: Added Display Per Item option in Global Badge addon for listing widgets.</li>\n<li>New: Added Title Vertical Alignment option in Icon Box widget.</li>\n<li>Tweak: Added Overflow option in Icon Box widget for better compatibility with Global Badge addon.</li>\n<li>Tweak: Added Border Radius option for Ribbon style badge in Global Badge addon.</li>\n<li>Tweak: Added a waiting time notice in Instagram Feed widget.</li>\n<li>Tweak: Improved content labels in Content Toggle widget.</li>\n<li>Tweak: Lowered the minimum value of the Size control in Content Toggle widget.</li>\n<li>Fixed: Badge banner top position in Global Badge addon.</li>\n<li>Fixed: Vertical offset not working on all badges in Global Badge addon.</li>\n<li>Fixed: Text decoration not inheriting text color in Global Badge addon.</li>\n<li>Fixed: \"undefined\" text shown when Image URL is empty in Global Badge addon.</li>\n<li>Fixed: Animated Gradient option applied to all child badges in Global Badge addon.</li>\n<li>Fixed: Per-item badges not working with Load More, Pagination and Load on Scroll options.</li>\n<li>Fixed: Z-index not working on custom CSS selector badges in Global Badge addon.</li>\n<li>Fixed: Conflict between Global Badge addon and Pricing Table widget Lottie icon.</li>\n<li>Fixed: Button alignment not working when position is set to outside in Unfold widget.</li>\n<li>Fixed: Magic Scroll not working with widgets inside Elementor V4 Flexbox container.</li>\n<li>Fixed: Content height not working on nested content in Content Toggle widget.</li>\n</ul>\n<h4> 2.9.60 </h4>\n<ul>\n<li>New: Content Toggle widget rebuilt - <a href=\"https://premiumaddons.com/elementor-content-toggle-widget/\">here</a>.</li>\n<li>Tweak: Code refactored for better performance and security.</li>\n</ul>\n<h4> 2.9.59 </h4>\n<ul>\n<li>Tweak: Added Box Shadow control for images in Image Accordion.</li>\n<li>Fixed: Border Radius not applied on Flipped style Tabs widget.</li>\n<li>Fixed: Default width not applied on Bookmark type badge.</li>\n</ul>\n<h4> 2.9.58 </h4>\n<ul>\n<li>Tweak: Added new presets for Global Badge addon.</li>\n<li>Tweak: Added Load More button in Instagram Feed widget.</li>\n<li>Tweak: Added Lightbox compatibility with videos in Instagram Feed widget.</li>\n<li>Tweak: Added alt text attribute for images in Instagram Feed widget.</li>\n<li>Fixed: Back icon size control not working in Icon Box widget.</li>\n<li>Fixed: Margin not applied correctly on mobile in Tabs widget.</li>\n<li>Fixed: Navigation from other pages not working in Tabs widget.</li>\n<li>Fixed: Elements styling broken in editor on first-time activation.</li>\n<li>Fixed: Icon Position control not working with SVG icons in Icon Box widget.</li>\n<li>Fixed: Duplicate initialization of Behance Feed widget.</li>\n</ul>\n<h4> 2.9.57 </h4>\n<ul>\n<li>Tweak: Added Get Reviews by Language option in Yelp Reviews widget.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n<li>Fixed: Stripe badge not showing in RTL mode.</li>\n<li>Fixed: Team Members widget not working inside Tabs widget.</li>\n</ul>\n<h4> 2.9.56 </h4>\n<ul>\n<li>Tweak: Added Container ID option in Image Accordion, Off Canvas, Alert Box and Tabs widgets to get slides from containers on the same page for better usability.</li>\n<li>Tweak: Added Hover Color and Background Color for navigation arrows in social reviews widget.</li>\n<li>Tweak: Border radius option added in Divider widget.</li>\n<li>Tweak: Added Image Fit control for icon in Icon Box widget.</li>\n<li>Tweak: Improved RTL compatibility in Smart Post Listing widget.</li>\n<li>Tweak: Improved compatibility between Unfold and Tabs widgets.</li>\n<li>Fixed: Jittering issues with Snappy effect in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.9.55 </h4>\n<ul>\n<li>New: Animated Gradient and Ken Burns addons are now applicable on widgets.</li>\n<li>Tweak: Opacity Scroll effect in Horizontal Scroll widget improved.</li>\n<li>Fixed: Blob not removed after disabling Animated Blob addon switcher.</li>\n</ul>\n<h4> 2.9.54 </h4>\n<ul>\n<li>Tweak: Improved compatibility between Dynamic Assets and Elementor Elements Cache.</li>\n<li>Fixed: Arrow position when Accordion option is enabled in Tabs widget.</li>\n</ul>\n<h4> 2.9.53 </h4>\n<ul>\n<li>Tweak: Facebook and Behance Feed widgets improved.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n</ul>\n<h4> 2.9.52 </h4>\n<ul>\n<li>Tweak: Added Suffix option in Charts widget to add text after value on hover.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n</ul>\n<h4> 2.9.51 </h4>\n<ul>\n<li>Tweak: API endpoint usage improved in Behance Feed widget.</li>\n<li>Fixed: Horizontal Scroll issues after scene ends.</li>\n</ul>\n<h4> 2.9.50 </h4>\n<ul>\n<li>New: Added Animated Gradient option to the badge text in Badge Global addon.</li>\n<li>Tweak: Improved Font Size and Color effects in Magic Scroll addon.</li>\n</ul>\n<h4> 2.9.49 </h4>\n<ul>\n<li>Tweak: Added Clipped Background option in Global Badge addon.</li>\n<li>Tweak: Added \"p\" and \"span\" options for HTML Tag control in Divider widget.</li>\n<li>Fixed: Image Layers widget not showing when Container Direction is set to row.</li>\n<li>Fixed: Text is showing in multiple lines in Divider widget.</li>\n</ul>\n<h4> 2.9.48 </h4>\n<ul>\n<li>New: Load JS libraries only when needed to improve loading speed.</li>\n</ul>\n<h4> 2.9.47 </h4>\n<ul>\n<li>Fixed: Fatal error in some widgets after v2.9.46.</li>\n</ul>\n<h4> 2.9.46 </h4>\n<ul>\n<li>Tweak: Code improvements in social reviews widgets for better performance and faster loading speed.</li>\n<li>Tweak: Improved accessibility in all widgets.</li>\n<li>Fixed: Jittering issue in Custom Mouse Cursor addon.</li>\n<li>Fixed: Console JS error when delay option is empty in Custom Mouse Cursor addon.</li>\n<li>Fixed: CSS Selector option not working in Custom Mouse Cursor addon.</li>\n</ul>\n<h4> 2.9.45 </h4>\n<ul>\n<li>Tweak: Code improvements in all widgets for better performance and faster loading speed.</li>\n<li>Fixed: RTL Mode option not working correctly in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.9.44 </h4>\n<ul>\n<li>Tweak: Code improvements in Global Badge and Custom Mouse Cursor addons for better performance and faster loading speed.</li>\n<li>Tweak: Added Videos Behavior option in Instagram Feed widget.</li>\n<li>Fixed: Multiple placeholder images are inserted in Media when a template is imported.</li>\n</ul>\n<h4> 2.9.43 </h4>\n<ul>\n<li>Tweak: Improve Background Transition option in Horizontal Scroll widget.</li>\n<li>Fixed: Horizontal Scroll widget not working correctly on RTL sites.</li>\n<li>Fixed: Console error in Tabs widget.</li>\n<li>Fixed: Rating Schema not working in Google Reviews widget.</li>\n<li>Fixed: Compatibility issues with WPML plugin.</li>\n</ul>\n<h4> 2.9.42 </h4>\n<ul>\n<li>Tweak: Added Change Color on Hover in Charts widget.</li>\n<li>Tweak: Added Liquid Glass effect option in Custom Mouse Cursor addon.</li>\n<li>Tweak: Added Moving background option in Tabs widget Style 1.</li>\n<li>Tweak: Added button to filter pre-made blocks by widget.</li>\n</ul>\n<h4> 2.9.41 </h4>\n<ul>\n<li>Tweak: Custom Mouse Cursor addon controls rearranged for better UX.</li>\n<li>Tweak: Entrance Animation improved in Image Layers widget.</li>\n<li>Tweak: Plugin size minimized for faster installation.</li>\n</ul>\n<h4> 2.9.40 </h4>\n<ul>\n<li>Tweak: Added Color option for switcher in inactive state in Content Toggle.</li>\n<li>Fixed: Entrance Animation option not working in Image Layers widget.</li>\n<li>Fixed: Arrow position issue in Image Compare widget.</li>\n</ul>\n<h4> 2.9.39 </h4>\n<ul>\n<li>Fixed: Plugin settings dashboard page not loading in some cases.</li>\n<li>Fixed: Put Sections Next to Each Other not working with Elementor Sections in Horizontal Scroll widget.</li>\n<li>Fixed: Arrow Pointer not showing when Accordion option is enabled in Tabs widget.</li>\n<li>Fixed: PHP warnings when global addons are enabled.</li>\n</ul>\n<h4> 2.9.38 </h4>\n<ul>\n<li>Tweak: Unfold widget not working correctly with Elementor Gallery widget.</li>\n<li>Fixed: Disable Horizontal Scroll on specific devices option not working.</li>\n<li>Fixed: Console error in editor page for a not found CSS file.</li>\n</ul>\n<h4> 2.9.37 </h4>\n<ul>\n<li>Tweak: Improved compatibility with RTL sites.</li>\n<li>Tweak: Plugin size decreased by improving Dynamic CSS generating.</li>\n<li>Fixed: Push/Slide effects not working on RTL in Hover Box widget.</li>\n</ul>\n<h4> 2.9.36 </h4>\n<ul>\n<li>Fixed: Fatal error in Google Reviews widget after v2.9.35.</li>\n</ul>\n<h4> 2.9.35 </h4>\n<ul>\n<li>Tweak: Improved Twitter Feed to use Bearer Token.</li>\n<li>Tweak: RTL Mode option improved in Horizontal Scroll widget.</li>\n<li>Tweak: Close Off Canvas when escape keyboard button is hit.</li>\n<li>Fixed: PHP warning in Google Reviews widget.</li>\n</ul>\n<h4> 2.9.34 </h4>\n<ul>\n<li>Tweak: Added Counting Effect in Woo Mini Cart widget.</li>\n<li>Tweak: Added Coupon Form in Woo Mini Cart widget.</li>\n<li>Tweak: Added Free Shipping progress bar in Woo Mini Cart widget.</li>\n<li>Tweak: Show date in current site language in all Social Feed/Reviews widgets.</li>\n<li>Tweak: Added Shape option for navigation dots in Multi Scroll widget.</li>\n<li>Tweak: Code improvements for better performance and loading speed.</li>\n<li>Fixed: Instagram Access Token is not automatically renewed.</li>\n<li>Fixed: Icon Position option not working correctly for body cells in Table widget.</li>\n<li>Fixed: PHP warning when Rating Schema option is enabled in Google Reviews widget.</li>\n<li>Fixed: PHP warning when background image is not set in Parallax addon.</li>\n<li>Fixed: Off Canvas content not showing correctly when set to Text Editor.</li>\n</ul>\n<h4> 2.9.33 </h4>\n<ul>\n<li>Tweak: Added Delay option in Lottie Background addon.</li>\n<li>Tweak: Code improvements for better performance.</li>\n<li>Tweak: Google Reviews widget loading speed improved.</li>\n<li>Tweak: Install free version directly without redirection to another page.</li>\n<li>Fixed: Free-hand design not working in Image Hotspots and Image Layers widgets.</li>\n<li>Fixed: Read more text not changing in Facebook Feed widget.</li>\n<li>Fixed: SVG Code option not working in Site Logo widget.</li>\n</ul>\n<h4> 2.9.32 </h4>\n<ul>\n<li>Tweak: Compatibility with Google Places API (New) in Google Reviews widget.</li>\n<li>Tweak: JS files separated for better performance.</li>\n<li>Tweak: Added Refresh Layout button in Horizontal Scroll and Image Layers.</li>\n<li>Fixed: Put Columns/Containers Next to Each Other option not working in Horizontal Scroll widget.</li>\n<li>Fixed: Content not showing when Ken Burns addon is enabled.</li>\n<li>Fixed: Blob addon is not working on inner containers while in editor.</li>\n<li>Fixed: On Page Load trigger not working in Off Canvas widget.</li>\n</ul>\n<h4> 2.9.31 </h4>\n<ul>\n<li>Tweak: Apply Icon size control on image icon in Icon Box widget.</li>\n<li>Fixed: Size control for Lottie Background addon not working on editor.</li>\n<li>Fixed: Instagram access token not generated.</li>\n</ul>\n<h4> 2.9.30 </h4>\n<ul>\n<li>Tweak: Added \"On Page Load\" trigger in Off Canvas widget.</li>\n<li>Tweak: Core improved for better editor loading.</li>\n<li>Fixed: Navigate to Multi Scroll sides using elements not working.</li>\n</ul>\n<h4> 2.9.29 </h4>\n<ul>\n<li>Fixed: Tabs widget not activating the correct tab on page load.</li>\n<li>Fixed: Hover effects not working in Smart Post Listing when featured image is disabled.</li>\n</ul>\n<h4> 2.9.28 </h4>\n<ul>\n<li>Fixed: Off-Canvas widget not working correctly after v2.9.27</li>\n<li>Fixed: Image dimensions issue in Site Logo widget.</li>\n</ul>\n<h4> 2.9.27 </h4>\n<ul>\n<li>Tweak: Improved compatibility with Optimize Markup Elementor feature.</li>\n<li>Tweak: SVG Draw Icon option improved for better loading speed.</li>\n<li>Fixed: Controls for global addons not being added in correct tabs.</li>\n</ul>\n<h4> 2.9.26 </h4>\n<ul>\n<li>Fixed: Layout issues with Fixed Content option in Multi Scroll widget.</li>\n<li>Fixed: Lottie animation icons not working correctly in Icon Box widget.</li>\n<li>Fixed: Global badge adds a spacing while in editor.</li>\n</ul>\n<h4> 2.9.25 </h4>\n<ul>\n<li>Tweak: Plugin core enhancements to improve plugin performance.</li>\n<li>Fixed: Table not showing data from CSV files.</li>\n<li>Fixed: Global Cursor SVG icon style not working.</li>\n</ul>\n<h4> 2.9.24 </h4>\n<ul>\n<li>Tweak: Plugin core enhancements to improve plugin performance.</li>\n<li>Tweak: Added No Cache option in Table widget.</li>\n<li>Fixed: Issues when Blog and Smart Post Listing widgets are added in one page.</li>\n</ul>\n<h4> 2.9.23 </h4>\n<ul>\n<li>Deprecated: Facebook Messenger Chat widget as it has been deprecated by Facebook.</li>\n</ul>\n<h4> 2.9.22 </h4>\n<ul>\n<li>Fixed: Background Transition widget is not working after Elementor 3.24.0.</li>\n</ul>\n<h4> 2.9.21 </h4>\n<ul>\n<li>Tweak: Pause videos in Tabs widget on switching tabs.</li>\n<li>Fixed: Conflict with Elementor v3.24.0.</li>\n<li>Fixed: Elementor entrance animations not working with Infinite Scroll option in Smart Post Listing widget.</li>\n</ul>\n<h4> 2.9.20 </h4>\n<ul>\n<li>Fixed: Background Transition widget not working when Scroll Up background is not set.</li>\n<li>Fixed: Scroll effects in Image Layers not working inside Horizontal Scroll widget.</li>\n<li>Fixed: Number of Columns not working on mobile devices in Smart Post Listing widget.</li>\n</ul>\n<h4> 2.9.19 </h4>\n<ul>\n<li>Tweak: Use IntersectionObserver API instead of waypoints.js to improve performance.</li>\n<li>Fixed: Scroll effects in Image Layers widget not working when added with Magic Scroll on same page.</li>\n<li>Fixed: Icon Color not working in WhatsApp Chat widget.</li>\n</ul>\n<h4> 2.9.18 </h4>\n<ul>\n<li>Fixed: Entrance animations in Image Layers widget not working within Horizontal Scroll widget.</li>\n<li>Fixed: Close icon not showing when logged out in Alert Box widget.</li>\n<li>Fixed: PHP warning in Google Reviews widget.</li>\n<li>Fixed: Instagram Feed layout broken while on editor page.</li>\n</ul>\n<h4> 2.9.17 </h4>\n<ul>\n<li>Tweak: Code improved for better performance and security.</li>\n<li>Fixed: Tabs widget not working in some cases.</li>\n<li>Fixed: PHP warnings on customizer page when Particles or Custom Mouse Cursor addons are enabled.</li>\n</ul>\n<h4> 2.9.16 </h4>\n<ul>\n<li>Tweak: Added HTML Tag option for text in Image Layers widget.</li>\n<li>Tweak: Code improved for better performance and security.</li>\n<li>Fixed: Smart Post Listing conflict with Elementor Flexbox Containers.</li>\n<li>Fixed: PHP warning in Facebook, Google and Yelp Reviews widgets.</li>\n</ul>\n<h4> 2.9.15 </h4>\n<ul>\n<li>Tweak: Code improved for better performance and security.</li>\n<li>Tweak: Added Z-index option for Custom Mouse Cursor addon.</li>\n<li>Fixed: PHP warnings in Yelp Reviews and Hover Box widgets.</li>\n<li>Fixed: Icon Color option not working correctly in some cases in WhatsApp Chat widget.</li>\n<li>Fixed: Console error thrown by Global Mouse Cursor addon.</li>\n</ul>\n<h4> 2.9.14 </h4>\n<ul>\n<li>Tweak: Code improved for better performance and security.</li>\n<li>Tweak: Improved compatibility between Horizontal and Magic Scroll elements.</li>\n<li>Fixed: Flickering issue in Magic Scroll addon.</li>\n</ul>\n<h4> 2.9.13 </h4>\n<ul>\n<li>Tweak: Code improved for better performance and security.</li>\n<li>Fixed: Off-canvas widget layout broken on RTL sites.</li>\n</ul>\n<h4> 2.9.12 </h4>\n<ul>\n<li>New: Magic Section widget rebuilt. It\'s now Off-Canvas - <a href=\"https://premiumaddons.com/elementor-off-canvas-widget\">here</a>.</li>\n<li>Tweak: Added Fixed Content Template option in Multi Scroll widget - <a href=\"https://premiumaddons.com/multi-scroll-widget-for-elementor-page-builder/\">here</a>.</li>\n<li>Fixed: Icon hover styling options not working in Icon Box widget.</li>\n</ul>\n<h4> 2.9.11 </h4>\n<ul>\n<li>New: Added new hover effects to all the buttons all over the plugin - <a href=\"https://premiumaddons.com/elementor-button-widget/\">here</a>.</li>\n<li>Tweak: Alert Box widget rebuilt - <a href=\"https://premiumaddons.com/alert-box-widget-for-elementor-page-builder/\">here</a>.</li>\n<li>Fixed: Social icons not showing in Image Hotspots widget.</li>\n</ul>\n<h4> 2.9.10 </h4>\n<ul>\n<li>Tweak: Added option to apply Particles addon on whole page through Elementor page settings.</li>\n<li>Tweak: Added responsive controls to Display option in Content Toggle widget.</li>\n<li>Fixed: Disable Snappy Effect on Touch Devices in Horizontal Scroll widget not working.</li>\n<li>Fixed: Flickering issue with Image Sequence effect in Magic Scroll addon.</li>\n</ul>\n<h4> 2.9.9 </h4>\n<ul>\n<li>Tweak: Divider widget rebuilt - <a href=\"https://premiumaddons.com/divider-widget-for-elementor-page-builder/\">here</a>.</li>\n<li>Tweak: Option to Disable Scroll on Accordion Item Click added in in Tabs widget.</li>\n</ul>\n<h4> 2.9.8 </h4>\n<ul>\n<li>Tweak: Added option to hide Horizontal Scroll widget slides on desktop devices.</li>\n<li>Fixed: Unnecessary HTML markup rendered in the table widget.</li>\n<li>Fixed: Feed is duplicated in Facebook and Behance Feed widgets.</li>\n<li>Fixed: Facebook and Behance Feed widgets not working on the frontend.</li>\n</ul>\n<h4> 2.9.7 </h4>\n<ul>\n<li>Tweak: Added SVG Code option in Site Logo widget.</li>\n<li>Tweak: Gold API error messages handled in News Ticker widget.</li>\n</ul>\n<h4> 2.9.6 </h4>\n<ul>\n<li>Tweak: Added Option to enable US numbers sorting in Table widget.</li>\n<li>Tweak: Compatibility between Hide Slide On option in Multi Scroll widget and Elementor custom breakpoints.</li>\n</ul>\n<h4> 2.9.5 </h4>\n<ul>\n<li>Fixed: Fatal error when Premium Addons Pro is activated without the free version.</li>\n<li>Fixed: Masonry effect not working correctly on editor page in Instagram Feed widget.</li>\n</ul>\n<h4> 2.9.4 </h4>\n<ul>\n<li>Tweak: Added Custom Navigation Element Selector option in Multi Scroll to be used to navigate to Multi Scroll slides.</li>\n<li>Fixed: Ratings values between .7 and .9 are rendered as half star in Social Reviews widgets.</li>\n</ul>\n<h4> 2.9.3 </h4>\n<ul>\n<li>Fixed: PHP Error when Image Accordion widget is used.</li>\n<li>Fixed: Elementor asks to run Safe Mode with Magic Scroll addon.</li>\n</ul>\n<h4> 2.9.2 </h4>\n<ul>\n<li>Tweak: Added Alternative Gold API key option in News Ticker widget.</li>\n<li>Tweak: Added Load More option in Smart Post Listing widget.</li>\n<li>Tweak: Added more styling controls in Smart Post Listing widget.</li>\n</ul>\n<h4> 2.9.1 </h4>\n<ul>\n<li>Tweak: Code improved for better performance and security.</li>\n</ul>\n<h4> 2.9.0 </h4>\n<ul>\n<li>New: Added Smart Post Listing widget - <a href=\"https://premiumaddons.com/elementor-smart-post-listing-widget/\">here</a>.</li>\n<li>Tweak: Show Alt text for the images in Ken Burns addon.</li>\n</ul>\n<h4> 2.8.27 </h4>\n<ul>\n<li>Fixed: Twitter Feed widget not working.</li>\n</ul>\n<h4> 2.8.26 </h4>\n<ul>\n<li>Tweak: Code refactored for better performance and security.</li>\n<li>Fixed: Numbers showing on hover not formatted in Charts widget.</li>\n</ul>\n<h4> 2.8.25 </h4>\n<ul>\n<li>Tweak: Removed Twitter Feed credentials section.</li>\n</ul>\n<h4> 2.8.24 </h4>\n<ul>\n<li>Tweak: Added custom position options for tooltips in Image Hotspots widget.</li>\n<li>Fixed: Multi Scroll widget not working when elements with entrance animations used in it.</li>\n<li>Fixed: Twitter Feed widget not working in some cases.</li>\n<li>Fixed: Image Comparison widget handle not working on RTL sites.</li>\n</ul>\n<h4> 2.8.23 </h4>\n<ul>\n<li>Tweak: Added caching options in Facebook and Behance Feed widgets.</li>\n<li>Tweak: Multi Scroll widget improved to trigger entrance animations on slide change.</li>\n<li>Fixed: Button showing in back side in 3D Hover Box widget.</li>\n<li>Fixed: Horizontal Scroll issues on mobile devices.</li>\n<li>Fixed: Hide Empty Reviews option not working correctly in Google Reviews widget.</li>\n</ul>\n<h4> 2.8.22 </h4>\n<ul>\n<li>Tweak: Added custom size unit for range controls in some widgets.</li>\n<li>Tweak: Load posts only if they have body text in Facebook Feed widget.</li>\n<li>Fixed: Load Chart On option not working in Charts widget.</li>\n<li>Fixed: Fatal error in Tabs widget when an image icon with empty image is added.</li>\n</ul>\n<h4> 2.8.21 </h4>\n<ul>\n<li>New: Added Magnet Effect in Custom Mouse Cursor addon - <a href=\"https://premiumaddons.com/elementor-custom-mouse-cursor-global-addon/\">here</a>.</li>\n<li>Tweak: Magic Scroll addon performance improved.</li>\n</ul>\n<h4> 2.8.20 </h4>\n<ul>\n<li>Tweak: CSS files size minimized for better performance.</li>\n<li>Fixed: Custom link attributes not working in Icon Box widget.</li>\n<li>Fixed: Console error in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.8.19 </h4>\n<ul>\n<li>Tweak: Added option to load Magic Scroll addon on page load, not when the section is reached.</li>\n<li>Fixed: Image Comparison widget not working when used inside Tabs widget.</li>\n<li>Fixed: Lock Page Scroll option in Magic Scroll addon causing a blank area while scrolling on mobile devices.</li>\n<li>Fixed: PHP warning in Parallax addon when no layers are added.</li>\n<li>Fixed: Console error with Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.8.18 </h4>\n<ul>\n<li>Tweak: Added Text Shadow and Box Shadow scroll effects in Magic Scroll addon.</li>\n<li>Tweak: Added Sort Reviews by date option in Google Reviews widget.</li>\n<li>Tweak: Show/hide images by hashtags in Instagram Feed widget.</li>\n</ul>\n<h4> 2.8.17 </h4>\n<ul>\n<li>Tweak: Sticky effect behavior improved in Magic Scroll addon.</li>\n<li>Tweak: Added option to trigger entrance animations once for Snappy scroll in Horizontal Scroll widget.</li>\n<li>Fixed: Sticky effect not working on the editor page in Magic Scroll addon.</li>\n</ul>\n<h4> 2.8.16 </h4>\n<ul>\n<li>Fixed: Draw SVG not working on the editor page with multiple SVGs in Magic Scroll addon.</li>\n<li>Fixed: Transition is added to Icon Box widget when used with Magic Scroll addon.</li>\n</ul>\n<h4> 2.8.15 </h4>\n<ul>\n<li>Fixed: Elements with entrance animation flash in Horizontal Scroll widget.</li>\n<li>Fixed: Icons not showing in some controls.</li>\n</ul>\n<h4> 2.8.14 </h4>\n<ul>\n<li>New: Added Magic Scroll addon - <a href=\"https://premiumaddons.com/elementor-magic-scroll-global-addon/\">here</a>.</li>\n</ul>\n<h4> 2.8.13 </h4>\n<ul>\n<li>Fixed: Compatibility issues with Elementor v3.8.0</li>\n<li>Fixed: Ken Burns container addon not working with recent Elementor versions.</li>\n</ul>\n<h4> 2.8.12 </h4>\n<ul>\n<li>New: Added Site Logo widget - <a href=\"https://premiumaddons.com/elementor-site-logo-widget/\">here</a>.</li>\n</ul>\n<h4> 2.8.11 </h4>\n<ul>\n<li>Tweak: Added caching option in Instagram Feed widget to improve the feed performance and loading speed.</li>\n<li>Tweak: Added Close On Click Outside option in Magic Section widget.</li>\n<li>Fixed: Icon styling not applied properly on SVG icons in Divider widget.</li>\n<li>Fixed: Mouse tilt option not working since Premium Addons for Elementor v4.9.35.</li>\n<li>Fixed: Feed is not showing if Posts/Account option value is larger than the posts returned by Facebook.</li>\n<li>Fixed: Alignment option not working properly for multi-line values in Table widget.</li>\n</ul>\n<h4> 2.8.10 </h4>\n<ul>\n<li>New: Added Random Badges option in Mega Menu widget - <a href=\"https://premiumaddons.com/elementor-mega-menu-widget/\">here</a>.</li>\n<li>Fixed: PHP warnings in Google Reviews widget.</li>\n</ul>\n<h4> 2.8.9 </h4>\n<ul>\n<li>Fixed: Console error when SVG Draw option is disabled for Parallax addon.</li>\n<li>Fixed: SVG Draw option not working for Font Awesome icons in Icon Box widget.</li>\n<li>Fixed: Applying global background colors not working in Magic Section widget.</li>\n<li>Fixed: Icon color applied on Lottie animation in Hover Box widget.</li>\n</ul>\n<h4> 2.8.8 </h4>\n<ul>\n<li>Tweak: Behance Feed widget now loads feed on scroll, not on page load.</li>\n<li>Fixed: PHP warning after v2.8.7.</li>\n</ul>\n<h4> 2.8.7 </h4>\n<ul>\n<li>Tweak: Make sure Custom Mouse Cursor addon JS files are loaded only if the addon is used on a page.</li>\n<li>Fixed: Navigation Arrows/Dots not working properly on touch devices in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.8.6 </h4>\n<ul>\n<li>Fixed: Fatal error due to Image Accordion widget since v2.8.4.</li>\n</ul>\n<h4> 2.8.5 </h4>\n<ul>\n<li>Fixed: Icons in Icon Box widget always disappear if Draw SVG option is disabled.</li>\n</ul>\n<h4> 2.8.4 </h4>\n<ul>\n<li>New: Added Draw Icon option in all widgets that has Icon option in them.</li>\n<li>Tweak: Added Horizontal/Vertical Alignment options for multi-layers in Parallax addon.</li>\n<li>Fixed: Conflict between Custom Mouse Cursor addon and WP Rocket Defer JS files option.</li>\n</ul>\n<h4> 2.8.3 </h4>\n<ul>\n<li>Fixed: Compatibility issues with Elementor v3.7.0.</li>\n<li>Fixed: Freehand Positioning feature not working when the device mode is changed in the editor page.</li>\n</ul>\n<h4> 2.8.2 </h4>\n<ul>\n<li>Tweak: Facebook Feed widget styling improved for RTL sites.</li>\n<li>Fixed: Conflict with Elementor Pro templates.</li>\n<li>Fixed: Even layout not working with Carousel Infinite Autoplay in social reviews widgets.</li>\n<li>Fixed: Carousel Navigation Arrows color/size controls not working in Instagram Feed widget.</li>\n</ul>\n<h4> 2.8.1 </h4>\n<ul>\n<li>Fixed: PHP warning since v2.8.0</li>\n</ul>\n<h4> 2.8.0 </h4>\n<ul>\n<li>Tweak: Apply Custom Mouse Cursor on full page or the entire website - <a href=\"https://premiumaddons.com/elementor-custom-mouse-cursor-global-addon/\">here</a>.</li>\n<li>Tweak: Added responsive controls to Number of Columns option in Behance Feed widget.</li>\n<li>Fixed: Carousel Tabs option applied on nested tabs.</li>\n<li>Fixed: Unnecessary Elementor placeholder images added to the Media Library after importing templates.</li>\n<li>Fixed: Multi Scroll widget not working with Elementor custom breakpoints.</li>\n<li>Fixed: Ken Burns addon not showing images properly on small screens.</li>\n<li>Fixed: Hover Box widget not working properly on iOS devices.</li>\n</ul>\n<h4> 2.7.9 </h4>\n<ul>\n<li>Tweak: Add responsive controls for image control in Ken Burns container addon.</li>\n<li>Fixed: Horizontal/Vertical Offset option not working for social icon in all Social Reviews widgets.</li>\n<li>Fixed: Horizontal Offset and z-index options not working for Fixed Content template in Horizontal Scroll widget.</li>\n<li>Fixed: Console error in Charts widget.</li>\n</ul>\n<h4> 2.7.8 </h4>\n<ul>\n<li>Tweak: Code improvements for better performance and loading speed.</li>\n</ul>\n<h4> 2.7.7 </h4>\n<ul>\n<li>Tweak: Load Custom Mouse Cursor addon when the element is visible on viewport to improve performance and page loading speed.</li>\n<li>Tweak: Added Cover Image size option in Behance Feed widget.</li>\n</ul>\n<h4> 2.7.6 </h4>\n<ul>\n<li>Tweak: Add Mask Image option in Image Layers widget.</li>\n<li>Tweak: Add Render As SVG/Canvas option for Lottie Animation icons in Hover Box widget.</li>\n<li>Tweak: HTML markup optimized for Image Hotspots and Twitter Feed widgets for better performance.</li>\n<li>Fixed: Accordion Tabs option not working in Tabs widget.</li>\n</ul>\n<h4> 2.7.5 </h4>\n<ul>\n<li>New: Added URL String, Shortcode and WooCommerce Products in Cart options in Display Conditions.</li>\n<li>Tweak: HTML markup optimized for Hover Box, Image Accordion, Instagram Feed, Tabs, Unfold widgets for better performance.</li>\n<li>Tweak: Added Disable Floating Effects on Safari option in widgets have floating effects.</li>\n<li>Tweak: Trigger Particles and Badge addons JS code when visible on viewport to improve page loading speed.</li>\n<li>Tweak: Added compatibility Charts and Horizontal Scroll widgets.</li>\n<li>Fixed: Change Colors As Gradient option not working in Background Transition widget.</li>\n<li>Fixed: Profile Header image not showing properly on small devices in Twitter Feed widget.</li>\n<li>Fixed: Right Side Template option not showing in Multi Scroll widget.</li>\n</ul>\n<h4> 2.7.4 </h4>\n<ul>\n<li>Tweak: Added compatibility between Badge Global Addon and Elementor Container element - <a href=\"https://elementor.com/help/container-element/\">here</a>.</li>\n<li>Fixed: Horizontal Scroll jittering issue on touch devices.</li>\n</ul>\n<h4> 2.7.3 </h4>\n<ul>\n<li>New: Added Create/Edit Live Templates feature in all widgets that support Elementor Templates.</li>\n</ul>\n<h4> 2.7.2 </h4>\n<ul>\n<li>Tweak: Added support for future features compatibility</li>\n<li>Fixed: Button Trigger Size option not working on frontend in Magic Section widget.</li>\n<li>Fixed: Alignment issue in Icon Box widget when description is short.</li>\n<li>Fixed: Invalid CSS added in the editor when Badge Addon is enabled.</li>\n</ul>\n<h4> 2.7.1 </h4>\n<ul>\n<li>Fixed: Fatal error with some PHP versions after v2.7.0</li>\n</ul>\n<h4> 2.7.0 </h4>\n<ul>\n<li>New: Added Premium Badge global addon - <a href=\"https://premiumaddons.com/elementor-badge-global-addon/\">here</a>.</li>\n</ul>\n<h4> 2.6.9 </h4>\n<ul>\n<li>Tweak: HTML markup optimized for Table widget for better performance.</li>\n<li>Tweak: Added Icon Color and Text Color/Typography options for each repeater cell in Table widget.</li>\n<li>Fixed: Hover Color and Padding options not working for Read More link in Icon Box widget.</li>\n</ul>\n<h4> 2.6.8 </h4>\n<ul>\n<li>New: Added five new skins in Elementor WooCommerce Products Listing widget - <a href=\"https://premiumaddons.com/elementor-woocommerce-products/\">here</a>.</li>\n<li>Tweak: Added compatibility between section/column addons and Elementor Container element - <a href=\"https://elementor.com/help/container-element/\">here</a>.</li>\n<li>Tweak: Widgets code refactored to improve performance and loading speed.</li>\n<li>Tweak: Added Hover Box Shadow option in Lottie Animation container addon.</li>\n<li>Fixed: PHP warning when Follow Delay option value is not set in Custom Mouse Cursor addon.</li>\n<li>Fixed: Image with Size option set to custom not rendered in Image Layers and Icon Box widgets.</li>\n</ul>\n<h4> 2.6.7 </h4>\n<ul>\n<li>New: Added Custom Mouse Cursor global addon - <a href=\"https://premiumaddons.com/elementor-custom-mouse-cursor-global-addon\">here</a>.</li>\n<li>Tweak: Added Auto Change Tabs option in Tabs widget.</li>\n<li>Tweak: HTML markup for images in Icon Box widget.</li>\n<li>Tweak: Make sure images in Image Layers and Tabs widgets are lazyloaded to improve loading speed.</li>\n<li>Fixed: Container addons not working on editor when used inside widgets using Elementor templates.</li>\n</ul>\n<h4> 2.6.6 </h4>\n<ul>\n<li>Fixed: Box shadow and Background Color options overridden by default values in CSS in Preview Window widget.</li>\n<li>Fixed: Charts widget not working in some cases inside Tabs widget.</li>\n<li>Fixed: Animated Gradient and Blob Generator addons not working in Tabs widget.</li>\n<li>Fixed: Ken Burns addon Infinite option always disabled when the editor page is reloaded.</li>\n</ul>\n<h4> 2.6.5 </h4>\n<ul>\n<li>Tweak: Load the main CSS file only when required.</li>\n<li>Fixed: Tabs widget not working properly with some themes.</li>\n<li>Fixed: Compatibility between Carousel option in Social Reviews widgets and RTL sites.</li>\n<li>Fixed: Keyboard Scrolling still works even when the control is disabled in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.6.4 </h4>\n<ul>\n<li>Fixed: Compatibility issues with Elementor v3.5.0.</li>\n</ul>\n<h4> 2.6.3 </h4>\n<ul>\n<li>Tweak: Added options to control Scroll Offset for each section individually in Color Transition widget.</li>\n<li>Tweak: Javascript loading method improved for Animated Gradient, Particles container addons for better performance.</li>\n<li>Fixed: Styling options not working for SVG icons in Magic Section widget.</li>\n</ul>\n<h4> 2.6.2 </h4>\n<ul>\n<li>Tweak: Added WooCommerce Total Amount In Cart and Current Product Stock options in Display Conditions feature.</li>\n<li>Fixed: Console error when videos are inserted in Tabs widget.</li>\n</ul>\n<h4> 2.6.1 </h4>\n<ul>\n<li>Fixed: Undefined variable $dir_class in Image Layers widget when Text option is used.</li>\n<li>Fixed: Button Size option not working in WhatsApp Chat widget.</li>\n</ul>\n<h4> 2.6.0 </h4>\n<ul>\n<li>New: Added Animated Blob Generator container addon - <a href=\"https://premiumaddons.com/elementor-animated-blob-generator/\">here</a>.</li>\n<li>Tweak: Added Radar Style option in Image Hotspots widget.</li>\n<li>Tweak: Added div, p and span HTML tag options for heading in Hover Box widget.</li>\n<li>Fixed: Default icon size changed in Hover Box widget.</li>\n<li>Fixed: Background Color not changing when multiple Background Transition widgets are used on the same page.</li>\n</ul>\n<h4> 2.5.5 </h4>\n<ul>\n<li>Fixed: Background is not changed on scroll up in Background Transition widget.</li>\n<li>Fixed: Nested tabs styling overwrite issue in Tabs widget.</li>\n</ul>\n<h4> 2.5.4 </h4>\n<ul>\n<li>Tweak: Tabs widget rebuilt for better usability and editing experience.</li>\n<li>Tweak: Control number of carousel slides to show in Instagram Feed widget.</li>\n<li>Tweak: Prevent Background Transition widget from changing color when up/down backgrounds are the same.</li>\n<li>Fixed: Line height not working for Business/Place Name, Reviewer Name and Review Text in Social Reviews widgets.</li>\n<li>Fixed: Entrance Animations not working on for the first in Horizontal Scroll widget.</li>\n<li>Fixed: Premium Parallax not working for Elementor columns.</li>\n<li>Fixed: Tabs widget not working when shortcodes are used in tabs content.</li>\n</ul>\n<h4> 2.5.3 </h4>\n<ul>\n<li>Tweak: Added Heroes Flying-Left effect in iHover widget.</li>\n<li>Tweak: Remove any duplicate content when Accordion Tabs option is enabled in Tabs widget.</li>\n<li>Tweak: Added Tab ID option in Tabs widget.</li>\n<li>Fixed: Animation issues for Flash Rotation, Flip Door, and Magic Door effects in iHover widget.</li>\n<li>Fixed: Charts not working on the editor page on Chrome browser.</li>\n<li>Fixed: Color option not applied on links in Table widget when CSV file is used.</li>\n</ul>\n<h4> 2.5.2 </h4>\n<ul>\n<li>Tweak: Save all the plugin settings on change without need to click \"Save Settings\" button.</li>\n<li>Tweak: Compatibility with Elementor v3.4.4.</li>\n<li>Fixed: Snappy scroll stability issues in Horizontal Scroll issues.</li>\n<li>Fixed: Compatibility issues between Elementor custom breakpoints and Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.5.1 </h4>\n<ul>\n<li>Tweak: iHover widget code refactored for faster editing speed..</li>\n<li>Tweak: Added Image Hover Effect in Image Layers widget.</li>\n<li>Tweak: Added compatibility between Multiscroll widget and sticky headers.</li>\n<li>Fixed: Premium Parallax not working for Elementor columns.</li>\n<li>Fixed: Premium Particles not working on some devices in editor page.</li>\n<li>Fixed: Premium Parallax not working for Elementor columns.</li>\n<li>Fixed: Content is not fully rendered issue in Unfold widget.</li>\n<li>Fixed: Removed Unnecessary requests made in Instagram Feed widget.</li>\n<li>Fixed: Hide Slide On and Disable Horizontal Scroll On options not working together in Horizontal Scroll widget.</li>\n<li>Fixed: Carousel not working in Facebook Feed widget when <code>Only Show Admin Posts</code> option is enabled.</li>\n<li>Fixed: Fold Height option not working when set to <code>0</code> in Unfold widget.</li>\n<li>Fixed: Console error in Multi Scroll widget.</li>\n<li>Fixed: Admin notices not showing when Premium Addons for Elementor is not installed.</li>\n</ul>\n<h4> 2.5.0 </h4>\n<ul>\n<li>Tweak: JS code refactored for better performance and faster editing speed.</li>\n<li>Tweak: Compatibility with Elementor v3.4.2.\n&hellip;</li>\n</ul>\";s:12:\"installation\";s:504:\"<ul>\n<li>First make sure that Elementor Page Builder and Premium Addons for Elementor are installed, As this plugin works only with both of them.</li>\n<li>Download the plugin then Upload it to the plugin folder: /wp-content/plugins/ or install it through the WordPress plugins screen directly.</li>\n<li>Activate the plugin through the ‘Plugins’ screen in WordPress</li>\n<li>You can find Premium Addons Elements under the category “Premium Addons” on your Elementor element/widget list.</li>\n</ul>\";}s:13:\"license_check\";s:0:\"\";s:3:\"msg\";s:47:\"License key is not valid for Premium Addons Pro\";s:8:\"homepage\";s:25:\"https://premiumaddons.com\";s:7:\"package\";s:206:\"https://my.leap13.com/edd-sl/package_download/MTc4ODM1MTgwODpHRkpXVThVV0hTTFRFNTVKUTlWSkI1NTZCM1RDVVJVUTozNjE6NTE1ZDRlYmE1OTlmMGJhMzQ1NDZiOGFiNDI0YjlhYTg6aHR0cEAvL2xvY2FsaG9zdC9LaHVtYnUvdGVrbm9wcmVtaXVtOjA=\";s:5:\"icons\";a:2:{s:2:\"1x\";s:80:\"https://my.leap13.com/wp-content/uploads/2024/12/premium-addons-logo-128x128.png\";s:2:\"2x\";s:80:\"https://my.leap13.com/wp-content/uploads/2024/12/premium-addons-logo-256x256.png\";}s:7:\"banners\";O:8:\"stdClass\":2:{s:4:\"high\";s:92:\"https://my.leap13.com/wp-content/uploads/edd/2018/10/premium-addons-pro-plugin-banner-hd.jpg\";s:3:\"low\";s:92:\"https://my.leap13.com/wp-content/uploads/edd/2018/10/premium-addons-pro-plugin-banner-ld.jpg\";}s:4:\"slug\";s:32:\"premium-addons-pro-for-elementor\";s:3:\"url\";s:77:\"https://my.leap13.com/downloads/premium-addons-pro-for-elementor/?changelog=1\";s:12:\"last_updated\";s:19:\"2026-08-09 07:47:49\";s:13:\"download_link\";s:206:\"https://my.leap13.com/edd-sl/package_download/MTc4ODM1MTgwODpHRkpXVThVV0hTTFRFNTVKUTlWSkI1NTZCM1RDVVJVUTozNjE6NTE1ZDRlYmE1OTlmMGJhMzQ1NDZiOGFiNDI0YjlhYTg6aHR0cEAvL2xvY2FsaG9zdC9LaHVtYnUvdGVrbm9wcmVtaXVtOjA=\";s:14:\"upgrade_notice\";s:0:\"\";s:10:\"stable_tag\";s:6:\"2.9.64\";s:7:\"license\";s:8:\"GPL v3.0\";s:6:\"tested\";s:3:\"7.0\";s:11:\"description\";a:1:{i:0;s:4257:\"<p>This plugin is an extension to Premium Addons for Elementor Plugin that includes Pro Elementor widgets and Addons for Elementor Page Builder. Visit <a href=\"https://www.premiumaddons.com/\">Premium Addons Website</a> to check widgets and addons demos.</p>\n<p>Premium Addons PRO plugin’s widgets are cross browser compatible and also fully responsive, Your website will rock on all browsers as well as tables and mobile devices.</p>\n<p>When using Premium Addons’ widgets you will notice that it has more customization options than any other widget in other plugin.</p>\n<p>Premium Addons PRO can be used only as a complement of Elementor page builder plugin as it’s not a standalone plugin.</p>\n<h3>Features</h3>\n<ul>\n<li>Fully Customizable Elements.</li>\n<li>Options panel for enabling desired elements only for faster performance.</li>\n<li>Free Support through online forums.</li>\n</ul>\n<h3>Available Elements</h3>\n<ol>\n<li><a href=\"https://premiumaddons.com/alert-box-widget-for-elementor-page-builder/\">Premium Alert Box</a></li>\n<li><a href=\"https://premiumaddons.com/animated-section-gradients-for-elementor-page-builder/\">Premium Animated Container Gradient</a></li>\n<li><a href=\"https://premiumaddons.com/behance-feed-widget-for-elementor-page-builder/\">Premium Behance Feed</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-charts-widget/\">Premium Charts</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-content-toggle-widget/\">Premium Content Toggle</a></li>\n<li><a href=\"https://premiumaddons.com/dual-header-widget-for-elementor-page-builder/\">Premium Divider</a></li>\n<li><a href=\"https://premiumaddons.com/facebook-feed-widget-for-elementor-page-builder-2/\">Premium Facebook Feed</a></li>\n<li><a href=\"https://premiumaddons.com/facebook-reviews-widget-for-elementor-page-builder/\">Premium Facebook Reviews</a></li>\n<li><a href=\"https://premiumaddons.com/flip-box-widget-for-elementor-page-builder/\">Premium Flip Box</a></li>\n<li><a href=\"https://premiumaddons.com/google-reviews-for-elementor-page-builder/\">Premium Google Reviews</a></li>\n<li><a href=\"https://premiumaddons.com/icon-box-widget-for-elementor-page-builder/\">Premium Icon Box</a></li>\n<li><a href=\"https://premiumaddons.com/ihover-widget-for-elementor-page-builder/\">Premium iHover</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-image-accordion-widget/\">Premium Image Accordion</a></li>\n<li><a href=\"https://premiumaddons.com/image-comparison-widget-for-elementor-page-builder/\">Premium Image Comparison</a></li>\n<li><a href=\"https://premiumaddons.com/image-hotspots-widget-for-elementor-page-builder/\">Premium Image Hotspots</a></li>\n<li><a href=\"https://premiumaddons.com/image-layers-widget-for-elementor-page-builder/\">Premium Image Layers</a></li>\n<li><a href=\"https://premiumaddons.com/instagram-feed-widget-for-elementor-page-builder/\">Premium Instagram Feed</a></li>\n<li><a href=\"https://premiumaddons.com/ken-burns-section-addon-for-elementor-page-builder/\">Premium Ken Burns</a></li>\n<li><a href=\"https://premiumaddons.com/magic-section-widget-for-elementor-page-builder/\">Premium Magic Section</a></li>\n<li><a href=\"https://premiumaddons.com/multi-scroll-widget-for-elementor-page-builder/\">Premium Multi Scroll</a></li>\n<li><a href=\"https://premiumaddons.com/parallax-section-addon-for-elementor-page-builder/\">Premium Parallax</a></li>\n<li><a href=\"https://premiumaddons.com/particles-section-addon-for-elementor-page-builder/\">Premium Particles</a></li>\n<li><a href=\"https://premiumaddons.com/preview-window-widget-for-elementor-page-builder/\">Premium Preview Window</a></li>\n<li><a href=\"https://premiumaddons.com/table-widget-for-elementor-page-builder/\">Premium Tables</a></li>\n<li><a href=\"https://premiumaddons.com/twitter-feed-widget-for-elementor-page-builder/\">Premium Twitter Feed</a></li>\n<li><a href=\"https://premiumaddons.com/tabs-widget-for-elementor-page-builder-2/\">Premium Tabs</a></li>\n<li><a href=\"https://premiumaddons.com/unfold-widget-for-elementor-page-builder/\">Premium Unfold</a></li>\n<li><a href=\"https://premiumaddons.com/whatsapp-widget-for-elementor-page-builder/\">Premium WhatsApp Chat</a></li>\n<li><a href=\"https://premiumaddons.com/elementor-yelp-reviews-widget/\">Premium Yelp Reviews</a></li>\n</ol>\";}s:9:\"changelog\";a:1:{i:0;s:35903:\"<h4> 2.9.64 </h4>\n<ul>\n<li>Fixed: Duplicate CSS rules applied.</li>\n</ul>\n<h4> 2.9.63 </h4>\n<ul>\n<li>Fixed: Anchoring section in a page with Horizontal Scroll not working.</li>\n<li>Fixed: Animated Gradient addon not working in some cases.</li>\n</ul>\n<h4> 2.9.62 </h4>\n<ul>\n<li>Tweak: Minor improvements in Global Badge addon for better usability.</li>\n</ul>\n<h4> 2.9.61 </h4>\n<ul>\n<li>New: Added CSS Selector option in Global Badge addon to display badges on custom elements.</li>\n<li>New: Added Display Per Item option in Global Badge addon for listing widgets.</li>\n<li>New: Added Title Vertical Alignment option in Icon Box widget.</li>\n<li>Tweak: Added Overflow option in Icon Box widget for better compatibility with Global Badge addon.</li>\n<li>Tweak: Added Border Radius option for Ribbon style badge in Global Badge addon.</li>\n<li>Tweak: Added a waiting time notice in Instagram Feed widget.</li>\n<li>Tweak: Improved content labels in Content Toggle widget.</li>\n<li>Tweak: Lowered the minimum value of the Size control in Content Toggle widget.</li>\n<li>Fixed: Badge banner top position in Global Badge addon.</li>\n<li>Fixed: Vertical offset not working on all badges in Global Badge addon.</li>\n<li>Fixed: Text decoration not inheriting text color in Global Badge addon.</li>\n<li>Fixed: \"undefined\" text shown when Image URL is empty in Global Badge addon.</li>\n<li>Fixed: Animated Gradient option applied to all child badges in Global Badge addon.</li>\n<li>Fixed: Per-item badges not working with Load More, Pagination and Load on Scroll options.</li>\n<li>Fixed: Z-index not working on custom CSS selector badges in Global Badge addon.</li>\n<li>Fixed: Conflict between Global Badge addon and Pricing Table widget Lottie icon.</li>\n<li>Fixed: Button alignment not working when position is set to outside in Unfold widget.</li>\n<li>Fixed: Magic Scroll not working with widgets inside Elementor V4 Flexbox container.</li>\n<li>Fixed: Content height not working on nested content in Content Toggle widget.</li>\n</ul>\n<h4> 2.9.60 </h4>\n<ul>\n<li>New: Content Toggle widget rebuilt - <a href=\"https://premiumaddons.com/elementor-content-toggle-widget/\">here</a>.</li>\n<li>Tweak: Code refactored for better performance and security.</li>\n</ul>\n<h4> 2.9.59 </h4>\n<ul>\n<li>Tweak: Added Box Shadow control for images in Image Accordion.</li>\n<li>Fixed: Border Radius not applied on Flipped style Tabs widget.</li>\n<li>Fixed: Default width not applied on Bookmark type badge.</li>\n</ul>\n<h4> 2.9.58 </h4>\n<ul>\n<li>Tweak: Added new presets for Global Badge addon.</li>\n<li>Tweak: Added Load More button in Instagram Feed widget.</li>\n<li>Tweak: Added Lightbox compatibility with videos in Instagram Feed widget.</li>\n<li>Tweak: Added alt text attribute for images in Instagram Feed widget.</li>\n<li>Fixed: Back icon size control not working in Icon Box widget.</li>\n<li>Fixed: Margin not applied correctly on mobile in Tabs widget.</li>\n<li>Fixed: Navigation from other pages not working in Tabs widget.</li>\n<li>Fixed: Elements styling broken in editor on first-time activation.</li>\n<li>Fixed: Icon Position control not working with SVG icons in Icon Box widget.</li>\n<li>Fixed: Duplicate initialization of Behance Feed widget.</li>\n</ul>\n<h4> 2.9.57 </h4>\n<ul>\n<li>Tweak: Added Get Reviews by Language option in Yelp Reviews widget.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n<li>Fixed: Stripe badge not showing in RTL mode.</li>\n<li>Fixed: Team Members widget not working inside Tabs widget.</li>\n</ul>\n<h4> 2.9.56 </h4>\n<ul>\n<li>Tweak: Added Container ID option in Image Accordion, Off Canvas, Alert Box and Tabs widgets to get slides from containers on the same page for better usability.</li>\n<li>Tweak: Added Hover Color and Background Color for navigation arrows in social reviews widget.</li>\n<li>Tweak: Border radius option added in Divider widget.</li>\n<li>Tweak: Added Image Fit control for icon in Icon Box widget.</li>\n<li>Tweak: Improved RTL compatibility in Smart Post Listing widget.</li>\n<li>Tweak: Improved compatibility between Unfold and Tabs widgets.</li>\n<li>Fixed: Jittering issues with Snappy effect in Horizontal Scroll widget.</li>\n</ul>\n<h4> 2.9.55 </h4>\n<ul>\n<li>New: Animated Gradient and Ken Burns addons are now applicable on widgets.</li>\n<li>Tweak: Opacity Scroll effect in Horizontal Scroll widget improved.</li>\n<li>Fixed: Blob not removed after disabling Animated Blob addon switcher.</li>\n</ul>\n<h4> 2.9.54 </h4>\n<ul>\n<li>Tweak: Improved compatibility between Dynamic Assets and Elementor Elements Cache.</li>\n<li>Fixed: Arrow position when Accordion option is enabled in Tabs widget.</li>\n</ul>\n<h4> 2.9.53 </h4>\n<ul>\n<li>Tweak: Facebook and Behance Feed widgets improved.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n</ul>\n<h4> 2.9.52 </h4>\n<ul>\n<li>Tweak: Added Suffix option in Charts widget to add text after value on hover.</li>\n<li>Tweak: Core improved for better performance and loading speed.</li>\n</ul>\n<h4> 2.9.51 </h4>\n<ul>\n<li>Tweak: API endpoint usage improved in Behance Feed widget.</li>\n<li>Fixed: Horizontal Scroll issues after scene ends.</li>\n</ul>\n<h4> 2.9.50 </h4>\n<ul>\n<li>New: Added Animated Gradient option to the badge text in Badge Global addon.</li>\n<li>Tweak: Improved Font Size and Color effects in Magic Scroll addon.</li>\n</ul>\n<h4> 2.9.49 </h4>\n<ul>\n<li>Tweak: Added Clipped Background option in Global Badge addon.</li>\n<li>Tweak: Added \"p\" and \"span\" options for HTML Tag control in Divider widget.</li>\n<li>Fixed: Image Layers widget not showing when Container Direction is set to row.</li>\n<li>Fixed: Text is showing in multiple lines in Divider widget.</li>\n</ul>\n<h4> 2.9.48 </h4>\n<ul>\n<li>New: Load JS libraries only when needed to improve loading speed.</li>\n</ul>\n<h4> 2.9.47 </h4>\n<ul>\n<li>Fixed: Fatal error in some widgets after v2.9.46.</li>\n</ul>\n<h4> 2.9.46 </h4>\n<ul>\n<li>Tweak: Code improvements in social reviews widgets for better performance and faster loading speed.</li>\n<li>Tweak: Improved accessibility in all widgets.</li>\n<li>Fixed: Jittering issue in Custom Mouse Cursor addon.</li>\n<li>Fixed: Console JS error when delay option is empty in Custom Mouse Cursor addon.</li>\n<li>Fixed: