_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://es.wordpress.org/?p=1266957\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:333:\"Cada versión de WordPress rinde homenaje a un artista que ha dejado una huella imborrable en el mundo de la música. WordPress 7.1 , cuyo nombre en clave es «Mary Lou», honra a la pionera pianista, arreglista y compositora de jazz Mary Lou Williams. Niña prodigio que comenzó a tocar en público a los seis años, su [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Fernando Tellado\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:97211:\"\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1.jpg\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"535\" src=\"https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1024x535.jpg\" alt=\"\" class=\"wp-image-1266958\" srcset=\"https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1024x535.jpg 1024w, https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-300x157.jpg 300w, https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-768x401.jpg 768w, https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1-1536x802.jpg 1536w, https://es.wordpress.org/files/2026/08/release-edition-featured-image-7-1-scaled-1.jpg 1920w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Cada versión de WordPress rinde homenaje a un artista que ha dejado una huella imborrable en el mundo de la música. <a href=\"https://wordpress.org/download/releases/7-1/\" target=\"_blank\" rel=\"noopener\">WordPress 7.1</a> , cuyo nombre en clave es «Mary Lou», honra a la pionera pianista, arreglista y compositora de jazz Mary Lou Williams.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Niña prodigio que comenzó a tocar en público a los seis años, su influencia y obra abarcan casi todas las épocas importantes del jazz, desde el swing y el bebop hasta el jazz sacro. A lo largo de todo este tiempo, reinventó constantemente su propio sonido. </p>\n\n\n\n<p class=\"wp-block-paragraph\">En la década de 1940 convirtió su apartamento en Harlem en un taller nocturno donde Thelonious Monk, Dizzy Gillespie y Bud Powell se reunían para intercambiar ideas y dar forma al bebop. Esa combinación de reinvención y colaboración inspiró WordPress 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Deja que la variada <a href=\"https://www.youtube.com/channel/UCha4zVvYM9Tv8Hx0Q9lN_jQ\" target=\"_blank\" rel=\"noopener nofollow\">música de Mary Lou</a> te acompañe a través de todo lo que ofrece WordPress 7.1.</p>\n\n\n\n<h2 class=\"wp-block-heading\">¡Te damos la bienvenida a WordPress 7.1!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 está diseñado pensando en tu forma de trabajar, navegar por el panel de administración, controlar tus diseños, colaborar con otros y crear lo que quieras. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>La barra de administración</strong> ahora te acompaña durante toda la experiencia, poniendo las herramientas que necesitas al alcance de tu mano, tanto si escribes una entrada como si editas el diseño de tu sitio. </p>\n\n\n\n<p class=\"wp-block-paragraph\">El <strong>estilo adaptable integrado</strong>, añadido a las opciones actuales de mostrar/ocultar bloques, te permite asegurarte de que tu sitio se vea exactamente como quieres en todos los tamaños de pantalla, sin CSS personalizado. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Un <strong>nuevo editor de medios</strong> mantiene la habitual vía de entrada del botón de recortar, y ahorra incorpora recorte en formato libre y de relación de aspecto, volteo horizontal y vertical, rotación precisa y rápida, y edición de metadatos en un flujo de trabajo específico. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Deja notas</strong> en cualquier parte de tu contenido, ya sin tener que limitarte a un bloque. La compatibilidad con texto enriquecido y las menciones (@) facilitan la colaboración con otros mientras escribes. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Dos nuevos bloques</strong>, lista de reproducción y pestañas, así como una nueva API para registrar tu propio conjunto de iconos para el bloque de iconos, te ofrecen aún más flexibilidad para crear lo que quieras sin plugins adicionales. </p>\n\n\n\n<p class=\"wp-block-paragraph\">¡Estos son solo algunos de los aspectos más destacados! Sigue leyendo para descubrir todo lo que WordPress 7.1 tiene para ofrecer.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://es.wordpress.org/latest-es_ES.zip\">Descarga WordPress 7.1</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">¿Qué hay ahí dentro?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 incluye numerosas novedades, como nuevas herramientas de estilo, flujos de medios actualizados, la nueva característica de notas y mucho más. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Algunos cambios incorporan nuevas capacidades, mientras que otros perfeccionan las herramientas y los flujos de trabajo existentes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Aquí te mostramos con más detalle las novedades de esta versión, empezando con el video de lanzamiento:</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n<iframe class=\"youtube-player\" width=\"640\" height=\"360\" src=\"https://www.youtube.com/embed/dO751c8jkn0?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=es-ES&#038;autohide=2&#038;wmode=transparent\" allowfullscreen=\"true\" style=\"border:0;\" sandbox=\"allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox\"></iframe>\n</div></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Aplica estilos adaptables</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Dale tu estilo al contenido, en todas las pantallas.</strong><br>WordPress 7.1 da un paso importante hacia el diseño adaptable integrado. Puedes establecer cómo se ve un bloque en diferentes tamaños de pantalla directamente en el editor, tanto para los estilos globales como para los bloques individuales, todo sin necesidad de escribir CSS personalizado.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1.jpg\"><img decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266961\" srcset=\"https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Apply-responsive-styles-scaled-1.jpg 1536w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Barra de administración, ahora en todos los editores</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Navegación coherente, del Escritorio al editor.</strong><br>La barra de administración ahora te acompaña en todos los editores, para que siempre sepas dónde estás. Además, la barra de administración recibe un pequeño lavado de cara visual.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266962\" srcset=\"https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Admin-bar-now-in-every-editor-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Una nueva forma de recortar</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Un flujo de trabajo dedicado a editar tus imágenes.</strong><br>Un nuevo emergente de editor de medios reemplaza la antigua herramienta de recorte en línea, y reúne el recorte de forma libre y por relación de aspecto, el volteo, la rotación precisa y la edición de metadatos en un único flujo de trabajo optimizado. </p>\n\n\n\n<p class=\"wp-block-paragraph\">El ya conocido botón de recortar sigue llevándote allí, y ahora abre un espacio dedicado para recortar, rotar y ajustar las imágenes antes de publicarlas.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266963\" srcset=\"https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/A-new-way-to-crop-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Notas integradas, con menciones y texto enriquecido</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Más formas para enviar comentarios.</strong><br>Las notas ahora admiten texto enriquecido y menciones con <code>@</code>. Añade negritas, cursivas, código y enlaces para que los comentarios se lean con claridad. Escribe «<code>@</code>» para que aparezca una lista de colaboradores y así etiquetar directamente a la persona adecuada, con avisos por correo electrónico integrados. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Deja una nota en una selección de texto específica en lugar de en todo un bloque. Inicia más de una conversación en el mismo bloque. Pliega las notas largas para mantener todo ordenado.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266964\" srcset=\"https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Inline-notes-with-mentions-and-rich-text-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Gestión de medios mejorada</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Procesamiento de imágenes más rápido y flexible.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">La compresión, el redimensionamiento y la generación de miniaturas de imágenes ahora se realizan en el navegador, lo que reduce la carga del servidor y produce archivos más pequeños, sin alcanzar los límites de memoria de PHP ni los tiempos de espera de carga.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La gestión de medios en la versión 7.1 también incluye compatibilidad nativa con AVIF, HEIC y mapas de ganancia HDR, lo que añade compatibilidad nativa con los formatos de imagen que ya producen las cámaras y los teléfonos modernos.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266965\" srcset=\"https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/More-image-formats-with-faster-uploads-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Detalles mejorados y nuevos bloques</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 también añade dos nuevos bloques, junto con más formas de personalizar el aspecto y el comportamiento del contenido.</p>\n\n\n\n<h4 class=\"wp-block-heading\">Crea listas de reproducción</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Reúne varias pistas de audio en una sola lista de reproducción, con una forma de onda opcional que ofrece a los oyentes una representación visual de cada pista mientras se reproduce.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266966\" srcset=\"https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Create-playlists-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Personaliza los puntos de interrupción adaptables</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Ahora, los temas de bloques pueden definir sus propios puntos de interrupción para móviles y tabletas en <code>theme.json</code>, sobrescribiendo los ajustes para los estilos adaptables y la visibilidad de los bloques.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266967\" srcset=\"https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Customize-responsive-breakpoints-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Organízalo con pestañas</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Organiza el contenido en paneles con pestañas en lugar de mostrarlo todo a la vez, una forma más limpia de presentar información relacionada sin saturar el contenido.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266968\" srcset=\"https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Organize-with-tabs-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Añade iconos personalizados</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Los desarrolladores pueden ampliar la biblioteca de iconos de WordPress con sus propias colecciones, lo que permite que los iconos personalizados estén disponibles en todo el editor junto con la biblioteca integrada.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266969\" srcset=\"https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Add-custom-icons-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Define estilos interactivos</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Personaliza los estilos de los botones para los estados de desplazamiento, enfoque y activo directamente en los controles de estilo del editor. Configura los estilos para un solo botón o para todos.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1.jpg\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"633\" src=\"https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-1024x633.jpg\" alt=\"\" class=\"wp-image-1266970\" srcset=\"https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-1024x633.jpg 1024w, https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-300x185.jpg 300w, https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1-767x474.jpg 767w, https://es.wordpress.org/files/2026/08/Set-interactive-styles-scaled-1.jpg 1536w\" sizes=\"auto, (max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Una experiencia de edición más consistente</h3>\n\n\n\n<p class=\"wp-block-paragraph\">El editor de entradas ahora está completamente integrado en un <code>iframe</code> para todos los temas, al igual que el editor del sitio.</p>\n\n\n\n<p class=\"wp-block-paragraph\">El lienzo de edición se ejecuta de forma independiente de la interfaz de administración de WordPress, por lo que los estilos de administración no interfieren con el contenido. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Las unidades relativas a la ventana gráfica y las consultas de medios ahora se aplican directamente al lienzo de edición, lo que permite que los diseños adaptables se comporten de forma más predecible durante el proceso de creación. </p>\n\n\n\n<p class=\"wp-block-paragraph\">El cambio es prácticamente imperceptible, pero el resultado es un editor más fiable y consistente.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Caja de herramientas para desarrolladores</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Herramientas avanzadas para construir a tu manera.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 amplía varias de las API y herramientas que los desarrolladores utilizan para crear aplicaciones en WordPress, con nuevas opciones para iconos, automatización, interfaces de administración y estilos adaptables.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La API de iconos SVG ahora es una API pública, lo que permite a los desarrolladores registrar sus propias colecciones de iconos e iconos y utilizarlos en todo el editor con funciones como <code>wp_register_icon_collection(), wp_register_icon(),</code> y <code> wp_get_icon().</code></p>\n\n\n\n<p class=\"wp-block-paragraph\">La API de capacidades se basa en la infraestructura introducida en WordPress 6.9 con un ciclo de ejecución filtrable, validación personalizada y descubrimiento compartido. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Estas mejoras facilitan la creación de integraciones y automatización sobre WordPress, incluyendo herramientas con inteligencia artificial.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Un nuevo sistema de diseño proporciona soporte base para la personalización de las interfaces de administración de WordPress, incluyendo colores, redondeo y estilos de cursor. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Los desarrolladores pueden usar tokens de diseño semántico y el componente React <code>ThemeProvider</code> para lograr mayor coherencia en las interfaces de administración personalizadas, sin dejar de sentirse cómodos en WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Los autores de temas también obtienen estilos adaptables y estilos de pseudo-estado para los estados de desplazamiento, enfoque, enfoque visible y activo a través de <code>theme.json</code>, junto con nuevos filtros para configurar las <code>DataViews</code> y <code>DataForm</code> para pantallas que muestren las páginas, plantillas, partes y patrones en el editor del sitio.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Accesibilidad</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 continúa mejorando la accesibilidad en todo el núcleo de WordPress y el editor. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Las nuevas funciones <code>wp_get_tooltip()</code> y <code>wp_get_toggletip()</code> incorporan información sobre herramientas accesible en más áreas del panel de administración de WordPress, incluyendo los cuadros de metadatos de las publicaciones y la pantalla de acceso.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La compatibilidad con lectores de pantalla también mejora en las interfaces de administración, con etiquetas más claras y una navegación más predecible en las tablas de listas de publicaciones. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Los nuevos bloques de pestañas y listas de reproducción, junto con las mejoras en la navegación e interacción del editor, se suman al trabajo de accesibilidad general incluido en esta versión.</p>\n\n\n\n<p class=\"wp-block-paragraph\">En conjunto, estos cambios siguen haciendo que WordPress sea más fácil de navegar y usar para más personas.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Mejoras de rendimiento</h2>\n\n\n\n<p class=\"wp-block-paragraph\">La compresión, el redimensionado y generación de miniaturas de imágenes ahora se ejecutan en el navegador (a través de una compilación WebAssembly de <code>libvips</code>), lo que reduce la carga de procesamiento en su servidor y ayuda a evitar límites de memoria y tiempos de espera con cargas de archivos más grandes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La conversión opcional de GIF a vídeo suele generar archivos más pequeños, mientras que los indicadores de progreso de la carga y los reintentos automáticos hacen que las cargas sean más resistentes cuando se pierde la conexión.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La biblioteca de medios ahora utiliza el desplazamiento infinito por defecto, con una opción por usuario para volver a la paginación. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Ahora también se pueden configurar los valores por defecto de carga especulativa mediante variables de entorno o constantes, de modo que los administradores y propietarios de sitios pueden configurar cómo WordPress precarga las páginas sin necesidad de crear un plugin para ello.</p>\n\n\n\n<h2 class=\"wp-block-heading\">¡Y mucho más!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para obtener una descripción general completa de todas las novedades y mejoras de WordPress 7.1, visita el sitio de muestra de características.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/download/releases/7-1/\" target=\"_blank\" rel=\"noopener nofollow\">Descubre las novedades de WordPress 7.1</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Más información sobre WordPress 7.1.</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://learn.wordpress.org/\">Aprende WordPress</a> es un recurso gratuito para usuarios de WordPress, tanto principiantes como experimentados. Te ofrece vídeos tutoriales sobre el uso de diversas funciones de WordPress, <a href=\"https://learn.wordpress.org/social-learning/\">talleres interactivos</a> para explorar temas en profundidad y planes de lecciones para profundizar en áreas específicas de WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Consulta las&nbsp;<a href=\"https://wordpress.org/documentation/wordpress-version/version-7.1/\">notas de la versión 7.1 de WordPress</a>&nbsp;para obtener información sobre la instalación, las mejoras, los problemas solucionados, los colaboradores de la versión, los recursos de aprendizaje y la lista de cambios en los archivos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Explora la <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">guía de campo de WordPress 7.1</a> . Descubre los cambios de esta versión con notas detalladas para desarrolladores que te ayudarán a crear aplicaciones con WordPress.</p>\n\n\n\n<h2 class=\"wp-block-heading\">El equipo de lanzamiento de la versión 7.1</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Cada lanzamiento es fruto del trabajo de un equipo dedicado de colaboradores entusiastas que se aseguran de que todo funcione correctamente y sin contratiempos. </p>\n\n\n\n<p class=\"wp-block-paragraph\">El equipo que lideró el desarrollo de la versión 7.1 es un grupo multidisciplinar de colaboradores siempre dispuestos a impulsar ideas, eliminar obstáculos y resolver problemas.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Responsable de la versión: <a href=\"https://profiles.wordpress.org/annezazu/\">Anne McCarthy</a></li>\n\n\n\n<li>Coordinación de la publicación: <a href=\"https://profiles.wordpress.org/benjamin_zekavica/\">Benjamin Zekavica</a> , <a href=\"https://profiles.wordpress.org/krupajnanda/\">Krupa Nanda</a></li>\n\n\n\n<li>Líderes técnicos: <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> , <a href=\"https://profiles.wordpress.org/joedolson/\">Joe Dolson</a></li>\n\n\n\n<li>Responsables de triaje: <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a> , <a href=\"https://profiles.wordpress.org/sajjad67/\">Sajjad Hossain Sagor</a> , <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a></li>\n\n\n\n<li>Líderes de las pruebas: <a href=\"https://profiles.wordpress.org/huzaifaalmesbah/\">Huzaifa Al Mesbah</a> , <a href=\"https://profiles.wordpress.org/nikunj8866/\">Nikunj Hatkar</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Gracias a los colaboradores.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">La misión de WordPress es&nbsp;<a href=\"https://wordpress.org/about/\">democratizar</a>&nbsp;la publicación y&nbsp;<a href=\"https://opensource.org/osd-annotated\">encarnar las libertades que ofrece el código abierto</a>&nbsp;. Una comunidad global y diversa de personas que colaboran para fortalecer el software respalda este esfuerzo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 refleja el incansable esfuerzo y la pasión de <strong>más de 800 colaboradores de todo el mundo</strong>. ¡Esta versión también dio la bienvenida a <strong>más de 170 colaboradores nuevos</strong>! </p>\n\n\n\n<p class=\"wp-block-paragraph\">En conjunto, su trabajo aportó <strong>más de 1500 mejoras y correcciones</strong>, lo que contribuyó a que WordPress 7.1 fuera una versión estable y pulida para todos. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Es otro gran ejemplo de lo que la comunidad de código abierto de WordPress puede lograr cuando las personas se unen para construir, probar y mejorar el software.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/ishihara-takashi/\">1shiharaT</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/aagam94/\">Aagam Shah</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/aakashverma1/\">Aakash Verma</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/aaroncampbell/\">Aaron D. Campbell</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/abdalsalaam/\">Abdalsalaam Halawa</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/abdullahramzan/\">Abdullah Ramzan</a>&nbsp;·&nbsp;<a h