s.org/vanonsopensource/\">Van Ons Open Source</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/twvania/\">Vania</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vascobaiao/\">Vasco Daniel Baixo</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/supernovia/\">Velda</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vgnavada/\">vgnavada</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vietcgi/\">vietcgi</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/szepeviktor/\">Viktor Szúpe</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vincentbreton/\">Vincent Breton</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vipulgupta003/\">Vipul Gupta</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vishalkakadiya/\">Vishal Kakadiya</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vishitshah/\">Vishit Shah</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vishnuprajapat/\">vishnu prajapat</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/vrishabhsk/\">Vrishabh Jasani</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/george9/\">webtasky</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/gauri87/\">WebTechee</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wfmattr/\">WFMattR</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/skorasaurus/\">Will Skora</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wiuempe/\">wiuempe</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wongjn/\">wongjn</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wpexplorer/\">wpexplorer</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wpsoul/\">wpsoul</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/wraithkenny/\">WraithKenny</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/xate/\">xate</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/xavilc/\">xavilc</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/xwolf/\">xwolf</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/yagniksangani/\">Yagnik Sangani</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/yguyon/\">Yannis Guyon</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/getsyash/\">Yash B</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/yashjawale/\">Yash Jawale</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/yogeshbhutkar/\">Yogesh Bhutkar</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/yusufmudagal/\">Yusuf Mudagal</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/zoe20/\">zoe20</a>&nbsp;·&nbsp;<a href=\"https://profiles.wordpress.org/lstraczynski/\">Łukasz Strączyński</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Más de <a href=\"https://translate.wordpress.org/stats/\">70 países y regiones han traducido</a> WordPress 7.0 a su lengua, pues los traductores de la comunidad trabajan arduamente para que pronto haya más traducciones disponibles. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Gracias a todos los que contribuyen a que WordPress esté <strong>disponible en más de 200 idiomas</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Gracias también a los <a href=\"https://make.wordpress.org/hosting/test-results/\">más de 21 proveedores de alojamiento web</a> que han probado las versiones preliminares de WordPress 7.0, lo que ha ayudado a garantizar que WordPress y las plataformas de alojamiento sean totalmente compatibles, estén libres de errores y optimizadas para ofrecer la mejor experiencia de usuario posible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Por último, pero no por ello menos importante, gracias a los voluntarios que contribuyen a los <a href=\"https://es.wordpress.org/support/forums/\" target=\"_blank\" rel=\"noopener\">foros de soporte</a> respondiendo a las preguntas de los usuarios de WordPress de todo el mundo.</p>\n\n\n\n<h2 class=\"wp-block-heading\">¡Implícate!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Participar en WordPress va mucho más allá de la programación. Aprender más e involucrarse es muy fácil. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Descubre los equipos que se unen para <a href=\"https://make.wordpress.org/\">crear WordPress</a> y usa <a href=\"https://make.wordpress.org/contribute/\">esta herramienta interactiva</a> para ayudarte a decidir cuál es el adecuado para ti.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://es.wordpress.org/download/\">Descarga ya WordPress 7.0</a></div>\n</div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://es.wordpress.org/2026/05/20/wordpress-7-0-amstrong/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"1253489\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:30:\"https://es.wordpress.org/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\"