n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"Open Channels FM: Navigating Open Source Collaboration in the Age of AI\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560027\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/navigating-open-source-collaboration-in-the-age-of-ai/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:232:\"The rise of AI in open source software has expanded contributor diversity, necessitating improved communication and documentation to guide participants effectively while ensuring sustainable collaboration and high-quality resources.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 01 Sep 2026 09:20:12 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"Gutenberg Times: Building blocks without JavaScript, Accessibility Lab, AI plugin showdown and more —Weekend Edition 375\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46992\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"https://gutenbergtimes.com/building-blocks-without-javascript-accessibility-lab-ai-plugin-showdown-and-more-weekend-edition-375/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:21357:\"<p class=\"wp-block-paragraph\">Hi, </p>\n\n\n\n<p class=\"wp-block-paragraph\">There is good news for me and good news for you. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The good news for me: with my five-year anniversary at Automattic, I get to go on a 3-month sabbatical, starting this week. It also means not only a break from Automattic but also from the WordPress community, a place that kept me engaged for the last 17 years. So that&#8217;s going to be a little weird for me. When I get back, I&#8217;ll let you know how it went. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The good news for you: my colleague <strong>Justin Tadlock</strong> will keep publishing Weekend Editions on Gutenberg Times while I am away. If you&#8217;ve read <a href=\"https://developer.wordpress.org/news/?author=20482\">his tutorials</a> on the WordPress Developer Blog or <a href=\"https://gutenbergtimes.com/author/jtadlock/\">his earlier posts here</a> on the Gutenberg Times, you know you&#8217;re in excellent hands. Not every week, but enough to tide you over during my pause.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, just to give serendipity a chance, I will be at <a href=\"https://athens.wordcamp.org/2026/en/\">WordCamp Athens</a> in December. Until then, all the best to you, your business and your family. I&#8217;ll be back. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#wordpress-and-ai\">WordPress and AI</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Karol Król</strong>&#8216;s first look walks you through <a href=\"https://www.youtube.com/watch?v=KUc0fGRuahA\">six features of WordPress 7.1</a> worth your attention: responsive styles, the new Tabs block, the Media Editor, the admin bar&#8217;s wider reach, hover and focus pseudo states, and the latest Notes updates. A useful orientation if you&#8217;ve been meaning to sit down with the release but haven&#8217;t had a chance to click around in the editor yet.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-972a13da wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/\">Gutenberg Changelog #134 – Gutenberg 23.7, 23.8, WordPress 7.1 and more</a> with special guest <strong>Jessica Lyschik</strong>, Greyd. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46955\" height=\"367\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-08-22-at-17.29.52.png?resize=1279%2C367&#038;ssl=1\" width=\"1279\" /></figure>\n\n\n\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n</div>\n\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Change one header and it changes everywhere — that&#8217;s the part templates make easy and the part that trips people up. <strong>Wes Theron&#8217;</strong>s seven-minute walkthrough on <a href=\"https://www.youtube.com/watch?v=vuMPGulNw8g\"><strong>editing WordPress templates</strong></a> covers the difference between editing a page and editing its template, how to tell which template a page uses, and how to work through List View. Along the way you&#8217;ll remove titles across pages, add a site-wide banner, drop featured images from all posts, and reset a template when you&#8217;ve gone too far.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Your wp-admin, but as a desktop: <strong>OpenStation</strong> opens admin screens as <a href=\"https://github.com/WordPress/openstation\">draggable, resizable windows with a dock built from the admin menu</a>, plus virtual desktops, snap-to-grid, wallpapers, and a Cmd+K palette. It&#8217;s opt-in per user, patches nothing in core, and reverts completely on deactivation — the classic admin stays untouched for everyone else. Bundled extensions add a Monaco code editor, a cron manager, and an RSS reader. Available on the plugin directory as Desktop Mode, or try it in Playground. The plugin also inspired contributors to create three additional features for the Desktop mode: </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=odd-outlandish-desktop-decorator&amp;TB_iframe=true&amp;width=772&amp;height=849\">ODD — Apps for OpenStation</a> by Nick Hamze</li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=allterrain-photo-editor&amp;TB_iframe=true&amp;width=772&amp;height=849\">AllTerrain Photo Editor for OpenStation</a> by Daniel Lopez Sanchez</li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wp-admin/plugin-install.php?tab=plugin-information&amp;plugin=deskbeat-for-desktop-mode&amp;TB_iframe=true&amp;width=772&amp;height=849\">Deskbeat for OpenStation</a> by <a href=\"https://profiles.wordpress.org/alexismp/\">alexismp</a></li>\n</ul>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-47039\" height=\"591\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/sOpenStation.png?resize=1024%2C591&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Built at WordCamp US Contributor Day, the <a href=\"https://github.com/topher1kenobe/WP-Photo-Directory-Importer\"><strong>Photo Directory Importer</strong></a> lets you search wordpress.org/photos from inside wp-admin and pull CC0 images into your Media Library. No API key, no account, and imports are deduplicated. In the block editor it&#8217;s a tab inside the Media Library modal rather than an entry next to Openverse and Pexels — so look one level deeper. Topher DeRosia and six co-contributors want testing before it goes to the .org repo.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The admin bar takes up viewport space and makes every page you view slightly not the page your visitors see. The <a href=\"https://wordpress.org/news/2026/08/browser-extension/\"><strong>official WordPress browser extension</strong></a> hides it while keeping the shortcuts in your browser toolbar, and adds block outlines, a phone-sized preview, cache-busted reloads, and cookie clearing. <strong>Jake Goldman</strong> of HumanMade writes that nothing leaves your device. Chrome and Safari now, Firefox next. <strong>Ray Morey </strong>of The Repository <a href=\"https://www.therepository.email/official-wordpress-browser-extension-now-available-in-the-chrome-web-store-and-mac-app-store\">has more on its origins</a> as Goldman&#8217;s WP Detective side project.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong>&#8216;s <a href=\"https://www.therepository.email/new-accessibility-lab-plugin-prototype-lays-groundwork-for-accessibility-teams-first-canonical-plugin\"><strong>Accessibility Lab plugin prototype</strong></a> arrives with the Accessibility Team&#8217;s buy-in and a clear boundary: it&#8217;s a testing ground for features headed to core, not a substitute for fixing core. Three modules so far — Media Library view controls, real-time heading-order validation, and Troy Chaplin&#8217;s Block Accessibility Checks. <strong>Rae Morey</strong> traces how the idea won conditional support after 2025&#8217;s pushback, and where you can contribute.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Mitch Canter</strong>&#8216;s field guide to <a href=\"https://mitchcanter.me/wordpress-responsive-block-styles/\"><strong>responsive block styles in WordPress 7.1</strong></a> gets into the details the announcement posts skipped: the theme.json syntax, the two default viewports (@mobile at 480px and @tablet at 782px), and how to set your own breakpoints. You&#8217;ll also see <code>:hover</code> and <code>:focus</code> states — official only on Button and Navigation Link blocks so far — how the feature coexists with fluid typography and <code>clamp()</code> tokens, and a quick-reference table worth bookmarking.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-10c06961e259e9b6 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8220;This block contains unexpected or invalid content</em>&#8220;; if you maintain custom blocks, you&#8217;ve met that message. <strong>Paulo Carvajal</strong> collected <a href=\"https://gist.github.com/paulo-carvajal/2dbb789a95014245c420491eec517acd\"><strong>five WordPress block deprecation patterns</strong></a> in a GitHub Gist that cover most real cases: markup-only changes, attribute renames paired with <code>isEligible()</code> and <code>migrate()</code>, source changes, InnerBlocks restructuring, and stacked deprecations ordered newest-first. Each comes with copy-ready code, plus a reminder to test against real database content and keep old <code>save()</code> functions intact.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">You might have heard that building a custom block no longer requires React or a build pipeline. <strong>Fränk Klein</strong> tests <a href=\"https://css-tricks.com/wordpress-php-block-registration/\"><strong>PHP-only block registration in WordPress</strong></a> on CSS-Tricks: an <code>autoRegister</code> flag generates the editor JavaScript and sidebar controls for you, straight from the PHP registration. He&#8217;s honest about the limits (no in-preview editing, no live post data, three attribute types) and argues the real win is porting legacy widgets, shortcodes, and template parts into block themes with PHP skills you already have.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"wordpress-and-ai\">WordPress and AI</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Ask ten agencies whether they use AI and you&#8217;ll get ten yeses, <strong>Brad Williams</strong>, Co-Founder of WebDevStudios, notes in explaining <strong><a href=\"https://webdevstudios.com/2026/08/26/agentic-ai-development-wordpress/\">what agentic AI development means for your WordPress project</a>.</strong> Building on <strong>Alfredo Navas</strong>&#8216;s WordCamp US talk, &#8220;the model knows WordPress, it doesn&#8217;t know your WordPress&#8221;, William&#8217;s the post lays out three prerequisites: written project rules, documented processes, and scoped tool access, with a human reviewing everything. You also get five questions to ask any agency, including where your project&#8217;s knowledge lives when people leave.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jonathan Bossenger</strong>&#8216;s latest live stream puts three viewer-suggested plugins through <strong><a href=\"https://www.youtube.com/watch?v=IC_0ZMlHFjI\">a WordPress AI plugin showdown</a>: </strong>Cross AI MCP Manager, Albert, and WP Vibe, judged on whether you can set each up without reading docs, connect it to a local site, and tell what data it sends home. WP Vibe routes everything through a third-party server, Albert won&#8217;t connect locally at all, and Cross AI — after real troubleshooting of its separate abilities and tools — is the only one working end to end.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-20a3181b538fe1e9 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-22f4025e9c433230 wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 29 Aug 2026 03:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"Open Channels FM: OCN Week in Review #3\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560387\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:110:\"https://openchannels.fm/signal-caring-in-creation-partnerships-and-trust-autonomy-acceleration-responsibility/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:261:\"This week\'s Open Channels News discusses the Linux Foundation\'s AI license proposal, Debian\'s debate on AI code, Bitcoin\'s security challenges, and the impacts of AI on employment and cybersecurity, emphasizing the balance between efficiency and accountability.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 16:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"Open Channels FM: A Look at WordCamp US Including Events, Sessions, and Community Highlights\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560289\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://openchannels.fm/inside-wordcamp-us-hackathon-successes-and-conference-networking-moments/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:129:\"An informal look at WordCamp US featuring hackathon day, community feedback, networking, and thoughts on the new event structure.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 13:21:28 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Open Channels FM: Still Moving the Needle on Open Source\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560339\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"https://openchannels.fm/still-moving-the-needle-on-open-source/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"Bob Dunn discusses the move from highlighting builders to engaging with open source’s wider future.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 11:53:21 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"WordPress.org blog: WordPress Signs the Open Weights and American AI Leadership Letter\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21341\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"https://wordpress.org/news/2026/08/open-weight/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3255:\"<p class=\"wp-block-paragraph\">We’re proud to announce that WordPress has signed <a href=\"https://www.microsoft.com/en-us/corporate-responsibility/topics/open-weight/\">Open Weights and American AI Leadership</a>, an open letter asking US policymakers to not place early restrictions on open weight AI models. These are artificial intelligence models that anyone can download, inspect, modify, and run on their own infrastructure. The letter was published on July 24, 2026, and more than 270 companies and organizations have added their names. Its argument will be familiar to anyone who works in open source: technology gets better and safer when more people can study it and build on it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That belief is the foundation WordPress is built on. Anyone can run the software, look at how it works, change it to suit their needs, and share what they make. Those freedoms are why WordPress has become a foundational part of the open web and why people trust it with their work. Open weight models bring that same kind of access to AI. A model that anyone can download and adapt becomes something people can shape around their own work and improve for everyone who comes after them.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">The next generation of innovation won&#8217;t come from models alone. It will come from millions of people building with them. Open weights help make that possible. WordPress is proud to support the Open Weights and American AI Leadership letter.<br /><br /><em>&#8211; WordPress Executive Director, Mary Hubbard</em></p>\n</blockquote>\n\n\n\n<h2 class=\"wp-block-heading\">Requests to US Policymakers</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The requests in the letter are practical ones. As signatories, we ask policymakers to expand access to computing power for startups and researchers, to invest in shared resources like public datasets and evaluation tools, and to keep more than one kind of model available rather than narrowing the field to a handful of closed systems. We also ask that common development practices, such as using one model&#8217;s output to improve another, not be treated as theft by default. Each of these requests follows the pattern that has made open source software dependable for decades, where many people test, improve, and secure the same technology in public view.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more than 20 years, WordPress has run on the idea that the people using a technology should be free to shape it. AI is becoming part of how people publish, and open weight models are one way that freedom carries forward. Keeping them available gives the next generation of builders, the people <a href=\"https://wordpress.org/education/\">now learning WordPress</a>, the same starting point that open source gave everyone before them.</p>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-left is-layout-flex wp-container-core-buttons-is-layout-b192c3d7 wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://www.microsoft.com/en-us/corporate-responsibility/topics/open-weight/\">Read the Letter</a></div>\n</div>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Aug 2026 17:00:32 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Mary Hubbard\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"Open Channels FM: X vs Nitter and XCancel, AI Middleware, and Accelerated Online College Degrees\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560267\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"https://openchannels.fm/x-vs-nitter-and-xcancel-ai-middleware-and-accelerated-online-college-degrees/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:120:\"Hear about X and Nitter, how AI changes human roles with meat proxies, and the shift toward rapid online degree programs\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Aug 2026 11:05:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"WPTavern: #231 – Damon Cook on How WP Trend Watcher Keeps Him Up to Date With WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=207377\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:103:\"https://wptavern.com/podcast/231-damon-cook-on-how-wp-trend-watcher-keeps-him-up-to-date-with-wordpress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:41984:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress, the people, the events, the plugins, the blocks, the themes, and in this case a new way to keep up with WordPress news and updates.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today, we have Damon Cook. Damon has been a developer in the WordPress ecosystem for over a decade, working with WordPress centric agencies, and more recently running his own freelance business, Noma Digital. He&#8217;s a longtime community member, contributor, and someone who remains keenly engaged with the latest WordPress developments from releases like 7.1, to shifts in plugins, themes, and the broader WordPress landscape.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Damon joins us today to discuss WP Trend Watcher, an open source tool he&#8217;s created to help WordPress professionals keep up with the ever increasing deluge of news, community updates and feature releases. As the WordPress space grows more dynamic, and let&#8217;s be honest, sometimes a bit overwhelming, WP Trend Watcher is designed to sift through a fire hose of RSS feeds, summarise the trends, and inject some much needed human curation into AI generated content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Damon talks about the importance of staying ahead in the WordPress ecosystem, especially for freelancers, agency owners, and developers who want to anticipate changes and support their clients.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He gets into the technical nuts and bolts, breaking down how the tool gathers, and summarises, news. The models and local AI setup he&#8217;s experimented with, and the balance between automation and critical human review.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re someone who struggles to keep up with the relentless pace of WordPress news, and wants a smarter way to separate the worthwhile updates from the dross, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Damon Cook.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Damon Cook. Hello, Damon.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:04] <strong>Damon Cook:</strong> Hi, Nathan. Good to see you again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:05] <strong>Nathan Wrigley:</strong> Yeah, thank you. Damon and I had a chat at WordCamp US. I think you said a little while ago that it was in 2024. So it&#8217;s been a few years since we&#8217;ve had a chat, and there&#8217;s been a few pivots in your life. At the time you were working for a hosting company, which I don&#8217;t think you are doing anymore. But we&#8217;re going to have a chat today about something which caught my attention probably on social media, I imagine, I saw it there. It&#8217;s called WP Trend Watcher.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I would just say at the beginning before we get stuck into the topic, if you go to the WP Tavern website, I will bury all of the links in the show notes. So anything that we discover today, go and click on the links over there. And actually given the nature of the topic, it might be wise, dear listener, to go and do that before you get into this podcast, because it&#8217;ll be fun to have a poke around and be forewarned as to what is it that we&#8217;re going to be looking at.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So anyway, Damon, thank you for joining us again. Just before we begin, I mentioned that you have changed roles in the last 24 months or so. Do you just want to tell us a little bit about you and your roles in WordPress over these many years?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:07] <strong>Damon Cook:</strong> Sure, yeah. Yeah, been a developer in WordPress ecosystem for over a decade. And always been with WordPress-centric agencies. And yeah, as of the past year about, I&#8217;ve just been running my own freelance, Noma Digital, then also doing some contract work. And yeah, and still keeping up on all the latest WordPress news and features coming out. 7.1, what is coming out in, well yeah, in like a week, I think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:37] <strong>Nathan Wrigley:</strong> Yes. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:38] <strong>Damon Cook:</strong> Lots of cool stuff there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:39] <strong>Nathan Wrigley:</strong> Yeah, there really is a lot happening. Genuinely, there is a lot happening in the WordPress space. And, it may be that you&#8217;re a developer, and so that side of things captures your attention. But from my perspective, I am not really a developer, but I am curious about all the things that are going on, because I&#8217;m fascinated by Core and plugins and themes and blocks and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But equally, the community side and all of that. There&#8217;s a whole load going on, and events and marketing and loads going on. But that deluge of information, that sort of fire hose is very hard to keep a track of. Some websites that were publishing for many years die out and other ones replace them, and things come at you from different angles.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so you have built a tool, WP Trend Watcher, which you&#8217;re able to put on your local machine. I believe that&#8217;s right at the moment. It&#8217;s a sort of local install, and we can talk about the technicalities of that in a moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But this tool, the way that you&#8217;ve built it is primarily pre-built, if you like, to go out and inspect the WordPress space so that you can summarise the zeitgeist, of what&#8217;s going on in the WordPress world. You can keep up without having to do that manual slog of going out, reading everything, spending hours every day kind of wasting time, and I&#8217;m doing air quotes there, if you know what I mean.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so my first question is revolving around the why of this. What was the importance here that you felt that you wanted a tool that did this for you? And really what I&#8217;m trying to get there is why did you feel it was important to keep up with the WordPress space? Is it&#8230; if you&#8217;re a client, if you&#8217;ve got relationships with clients and you&#8217;re building client websites, is it not enough in your scenario just to know that WordPress drops, they do a version change every now and again, we get a release, I&#8217;ve got a suite of plugins, I probably need to keep up to date with those. Why? Why are you interested in the broader landscape?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:34] <strong>Damon Cook:</strong> Sure, yeah. I&#8217;ve been a, I was pretty active contributor for a while to the project, not so much lately. But, when I was a contributor there was, I mean, there&#8217;s always been a lot of news to keep up with, between Slack and Trac and WordPress.org stuff. But I started to see some of what were the reliable sources in that area. And as I work with WordPress daily, I still need to keep up with what is coming down the pipeline.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so yeah, I just wanted to take that, it was very a selfish starting point. I needed to take all these RSS feeds, get them summarised, but then also verify that, what&#8217;s being summarised with AI isn&#8217;t just hallucinations or some kind of, you know, mistrust was there, because that&#8217;s a critical component to this project was the human layer. It&#8217;s just pulling in a bunch of RSS feeds, summarizing it, and then I go through and make sure the summaries and click through it, like a lot of the stuff, and read it, and it&#8217;s helpful for me to process and see what&#8217;s actually going on and then provide my own judgment on it, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:47] <strong>Nathan Wrigley:</strong> The sort of curious bit there then I suppose is that you, it feels like you always want to be one step ahead of what&#8217;s happening in the WordPress space. And I suppose if you&#8217;re being a freelancer, having that knowledge of what&#8217;s coming up, particularly in WordPress and WordPress Core, because I&#8217;ve noticed that a lot of RSS feeds, for want of a better word, and we&#8217;ll get into that in a moment, are Core related.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that then sort of tells me that you want to be ahead of what&#8217;s coming in the next feature set so that you can, I don&#8217;t know, forewarn your clients, or practice things that you know are going to suddenly drop on a particular day of the year, and so that when the inevitable call comes, &#8220;Why is this there now?&#8221; And, &#8220;How does this new feature work?&#8221; You&#8217;re ahead of it all. Does that kind of summarise your interest in it, or is it more eclectic than that? You&#8217;re just curious about it because it&#8217;s curious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:39] <strong>Damon Cook:</strong> Yeah, I mean there&#8217;s certainly the curiosity is there, but yes, I do like to be at the bleeding edge of what is coming down in the new, like for example, the 7.1 release coming out. Just seeing what&#8217;s being worked on, what might have gotten dropped from proposals. Yeah and just I guess being in the ecosystem, I&#8217;ve seen how a lot of the community has come and gone, and what has been critically talked about is, what is a critical feature, and why might something not be worked on and all that stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, it&#8217;s just a selfish way to keep up on the latest, developer news and, yeah, and share it out and summarise it and get some human judgment behind it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:22] <strong>Nathan Wrigley:</strong> A curious thing which is not related to this podcast, but most Mondays I do like a live show in which we have three or four panelists, and we bat around the WordPress news from the previous seven days. And I&#8217;ve been doing that show for, oh, I don&#8217;t know, maybe seven or eight years or something like that. And in the sort of the week preceding, I go around the internet, I look at social networks, I read the blogs that I&#8217;m familiar with. I&#8217;ve got a giant list of RSS URLs in a feed reader, and I go through, and I read them, and I look at them all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it, genuinely is incredibly time inefficient. That is to say that I open things, get halfway through, realise there&#8217;s nothing really for me to talk about here with my guests, and there&#8217;s probably nothing for the the listeners to engage with. And so I lose a lot of time, doing that exercise, and it strikes me that in the era of AI, that would be, the intention here is to cut out that. Cut through the dross, sift out the bits and pieces that are of interest, and make the bits that finally reach your eyeballs worthy of attention.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How have you orchestrated that to happen? Because with the best will in the world, I think we all know that AI can go off the rails a little bit. It may be that it doesn&#8217;t quite match the intentions that you would wish it to have. How are you corralling it to be what it is that you want?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:47] <strong>Damon Cook:</strong> Sure. Like I alluded to, it just stemmed from a selfish kind of interest in keeping up on these news sources, and I knew a lot of them all had RSS feeds. I think that even I, you know, I have a fascination, an obsession almost, with AI these days and I&#8217;m always trying some cutting, more cutting edge stuff and tinkering.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I think even myself, and I think I see a lot of people confuse AI with automation. And so it&#8217;s interesting to see, when I, this project, I didn&#8217;t want to automate the whole thing, like just go get RSS feeds, AI summarises, AI publishes, just do it, right? Which I can, we could potentially do with the project, but I limited it to that contract of, go get these RSS feeds, the latest news, come back, summarise them, and then show them to me so I can audit them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A lot of them, I just open up like yourself. It seems counterproductive, but I actually like that&#8217;s how I really keep up. Because if I just read the paragraph from the AI summary, which I do, it&#8217;s it&#8217;s not really covering, and might miss something in that full article that actually really interested me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So you know, I click through most of these and I&#8217;m reading. I peruse, I don&#8217;t read every single word for sure, but I peruse and just try to validate that the summary matches, and then I look for tidbits that might been missed that I&#8217;m curious about, and then drop that in the human summary element of the published final briefing. So that&#8217;s the workflow of it right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:27] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:27] <strong>Damon Cook:</strong> That&#8217;s how I&#8217;ve set it up and I enjoy just the whole, the sequential part of like gathering and then, there is an automation of it shows me everything I gathered, and then gives me an area to write my thoughts and then I click through everything. So it&#8217;s just turned into a weekly, kind of hobby project and it&#8217;s fun to do, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:48] <strong>Nathan Wrigley:</strong> Yeah, so the bit that is infuriating to me is just the dead time. And the dead time for me is not once I&#8217;ve found the link. That for me is when it actually becomes interesting. You click the link, you open it, and you do the reading and what have you. It&#8217;s finding the link and finding the interesting thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:07] <strong>Damon Cook:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:07] <strong>Nathan Wrigley:</strong> And so I think, it is totally credible to get AI to do that. And I have this, I&#8217;m not a great user of AI. That is to say I&#8217;m not somebody that uses AI an awful lot. But it&#8217;s becoming pretty clear to me that one of the areas which it genuinely is good at is curating like a silo of information. You give it a body of information, a corpus of information, and say, &#8220;summarise that,&#8221; or, &#8220;Draw out of that the bits that might be of interest.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, it&#8217;s not perfect, but it seems to be exceedingly good at that. The creative side, maybe less so, and we don&#8217;t really need to get too much into that. But this bit of drop the corpus of information in, summarise that, publish your results. That seems like a really credible way of using AI in the year 2026, and that is indeed what you&#8217;ve done.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now that you&#8217;ve got this built, and I will link to a report so you can see Damon&#8217;s previous, I think you&#8217;ve got seven or six or something like that, previous ones from previous weeks up, and you can see them all. It basically ends up in a bullet-pointed, numbered list of titles with links, and then maybe one sentence of about 20 words following on from that. And then that will obviously either lead to a click or not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How have you found those summaries to be? The 20 or so that you&#8217;ve got in each of your little editions. How have you found them to be? Do they seemingly accurately represent what&#8217;s contained within, or does it tend to go off the rails a bit?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:39] <strong>Damon Cook:</strong> No, they&#8217;re accurate.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:41] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:42] <strong>Damon Cook:</strong> The key kind of component there is when the summaries happen, it&#8217;s using, I set it up because I wanted to use local models. It&#8217;s all prompt-based, so essentially, it&#8217;s going to these RSS feeds, getting the latest articles and links, then parsing that through AI and saying, and passing a prompt along saying, &#8220;summarise this for developers and agency owners with a critical eye on, X, Y, Z.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so that&#8217;s where things do actually come, they come back pretty accurate. And the inference of what the summary shows, it&#8217;s fascinating. But yeah, it&#8217;s pretty accurate, and the fun part is trying to prove it, to see like, &#8220;okay wow,&#8221; that sounds like it would interest me as a developer and agency owner. I&#8217;m going to click and read through and make sure that&#8217;s an actual thing, and not a hallucination. So it&#8217;s like a game of just fact-checking in a way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:46] <strong>Nathan Wrigley:</strong> I&#8217;m curious to know what it doesn&#8217;t include. So for example the addition, I&#8217;m going to call it an addition. I don&#8217;t know. Oh, summary. There we go. Weekly summary is what you&#8217;ve called it. This particular one has 19 items listed, and I don&#8217;t know if it produced 19 different things and all of them got written to the page, or if, I don&#8217;t know if you can see in the background, 34 just didn&#8217;t cut the mustard. Can you inspect what didn&#8217;t get included and thereby start to have intuition to say &#8220;okay, I wonder why that one didn&#8217;t cut the mustard?&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:20] <strong>Damon Cook:</strong> Yeah, there is a built-in, for the AI to, when it does a review, it checks sources and it looks for duplicate, two kind of posts on two different sites about the same exact topic. It&#8217;s going to try to not do a summary on both of those.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:39] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:40] <strong>Damon Cook:</strong> So it does check for duplicates, weak language, missing sections. So it does do some of that to cut out the duplicate work. But also, yeah, it&#8217;s not looking, like part of the prompt and part of the exercise for AI is to not look for superfluous, just like really fact-based deterministic stuff and not just you know. It&#8217;s funny because trend is in the title, right? WP Trend Watcher.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:06] <strong>Nathan Wrigley:</strong> Which is maybe the exact opposite of what you&#8217;re after.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:09] <strong>Damon Cook:</strong> It&#8217;s kind of like it&#8217;s not really looking for what&#8217;s popular, but what is factual coming out of a lot of these sources.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:17] <strong>Nathan Wrigley:</strong> Okay. When you are looking at this, this is a strange question, and I don&#8217;t know how you&#8217;re going to react to this. How does it make you feel? Do you have the intention that you&#8217;re cheating on the Damon from five years ago would&#8217;ve thought, &#8220;Oh, this is horrific, somebody did all this with a computer. This should be done by, a human being should be corralling this.&#8221; How does it make you feel on that level?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:41] <strong>Damon Cook:</strong> Yeah, it does make me feel cheap.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:43] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:45] <strong>Damon Cook:</strong> And I think that&#8217;s kind of why I publish these. It&#8217;s trying to be transparent. So if anybody&#8217;s going to go and read this, they know that I even put at the bottom how much time I spent trying to look through everything. So you can take all those facts and base whether you want to read this or not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:08] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:09] <strong>Damon Cook:</strong> Did he spend enough to? You can pass your own judgment. Did he spend enough time? Maybe he should have spent more time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:14] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:16] <strong>Damon Cook:</strong> But yeah, that&#8217;s part of the exercise for me is making this open source, and just having this public, and so if folks do find it fascinating and helpful, they could even fork it and try to do something else. Or I even have, possibility to submit sources because I&#8217;m always thinking &#8220;Should I have another source in here?&#8221; or.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:39] <strong>Nathan Wrigley:</strong> Yes, yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:41] <strong>Damon Cook:</strong> There&#8217;s room for improvement too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:43] <strong>Nathan Wrigley:</strong> The issue there is you end up with scope creep, don&#8217;t you? And before you know it, you&#8217;ve got 5,000 RSS feeds that you&#8217;re pummeling everywhere, and then you really are in a maze of trying to figure out what&#8217;s relevant and what&#8217;s useful.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The report that you get on the front end, obviously, you&#8217;ve got these AI generated the numbered list, in this case 19, the one that I&#8217;m looking at. Again, links will be in the show notes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then the interface that you built provides the option then to add sort of human notes, for want of a better word, at the end. So it&#8217;s not just a case of, okay, that&#8217;s where it ends. The idea is then that you would go in, contribute for yourself what it is that you feel is important here, free form writing like we always used to do, and so on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:24] <strong>Damon Cook:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:24] <strong>Nathan Wrigley:</strong> Why did you include that bit? Why, what was the purpose in having that? Was it just a more human curated portion at the end, so you wanted to remember what you actually thought?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:33] <strong>Damon Cook:</strong> Yeah. It&#8217;s twofold. I wanted the human in the loop. It&#8217;s a pretty popular phrase these days with AI, but I wanted that aspect there. But also selfishly, a game to fact-check a lot of these things and make sure AI isn&#8217;t hallucinating. But also it&#8217;s the exercise of memory of like going through and reading these things, because then I actually, you know, it registers in my brain. Like this is really what&#8217;s coming down the pipe. Because if I just read through the summaries, even if they were 100% accurate and I just trusted them out of the box, I feel like it doesn&#8217;t necessarily always register for me. So the actually exercise of going and clicking and reading through and comparing to what AI summarised is helpful for to sink in that data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:20] <strong>Nathan Wrigley:</strong> I think if this were something that I was looking at, and I&#8217;m definitely not ruling out doing something like this because I genuinely think there&#8217;s a lot of merit in my specific case for this. I think I&#8217;d be looking at four of those a day and just trying to, I don&#8217;t know, at 9 in the morning just before the day begins, or at 5 at night just as the day&#8217;s about to end, the workday. Just go in and look at a few of those. Because I&#8217;m like you, if I read the AI 20-word summary, there&#8217;d be no substance to that and I wouldn&#8217;t remember it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the fact that the interface is there and those articles have been surfaced, and I presume you could probably run one of these each day and adapt what was there the previous day and what have you. So technically then, how does it work? I&#8217;m fairly sure that this is a thing which you have built, and is currently sitting on a machine in your house somewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:08] <strong>Damon Cook:</strong> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:08] <strong>Nathan Wrigley:</strong> Just describe the technicalities of what you need to get, on your machine to make this occur.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:13] <strong>Damon Cook:</strong> Yeah. It&#8217;s a TypeScript code base, and it&#8217;s on GitHub, so you can fork it, contribute to it. But yeah, I run it. You can pass in kind of a flag. I run it weekly. It was just an arbitrary decision, and it felt weekly would be good. But you can, yeah, it just checks basically the last date of when it ran, and then tries to grab the sources.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then I use LM Studio application on my Mac, which allows me to kind of download models that are fit for my system. I have an 18 gigabyte memory that I can work with, so that is limiting. But, I think a lot of these models are coming down in size and the local AI movement, I don&#8217;t know if it&#8217;s a movement, but I think it&#8217;s taking off in a lot of ways.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:07] <strong>Nathan Wrigley:</strong> Yeah, I think so. Yeah. Yep</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:09] <strong>Damon Cook:</strong> We&#8217;re starting to see a lot more, yeah, local implications. That was part of the exercise for me, was exploring that. What models I could use on my system, and then what were the results of using those models with this tool for the summaries.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, I think every week at the bottom, that&#8217;s part of the report is what model I used locally to run the summaries against. And I try to switch it up. I think I used probably six of them, I used the same model. I think it was a Qwen model. Then the most recent one I used, I switched it up, and it was a, I forget the name even. It was like an LS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:49] <strong>Nathan Wrigley:</strong> Oh, these things come and go so fast. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:51] <strong>Damon Cook:</strong> Yeah, exactly. And that&#8217;s the fascinating part is just to drop in a new model and see how it does, and the softwares look like, because they do change. And even the report, I think you&#8217;ll, if you just compare this week&#8217;s with last, just the output is a little different. And I&#8217;m trying to&#8230; That&#8217;s something I plan on working more towards is deterministic, the output. The summaries are one thing, but then when it outputs into the final report, getting that more deterministic. Especially, I really want to have footnotes, so that people can see where these summaries and stuff are, what they&#8217;re exactly they&#8217;re linking to. It&#8217;s kind in there but it does&#8217;t always output exactly the same in formatting, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:35] <strong>Nathan Wrigley:</strong> So you&#8217;re doing this work on the local machine, and then obviously I&#8217;m looking at it so it&#8217;s published, by the looks of it on GitHub. Is that all automated or are you curating that process? Or have you got, you know, your local machine is bound to GitHub, your GitHub repository and so this is all automated in that sense as well?</p>\n\n\n\n<p class=\"wp-block-paragraph\">In other words, what I&#8217;m saying is if you took a break for a month and came back, would this all just be chugging along in the background and producing these weekly reports? Or is this something that you manually invoke on a weekly basis and copy and paste and what have you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:07] <strong>Damon Cook:</strong> That&#8217;s the part that, yes. I just run the report and write my judgment in it, then publish it to GitHub, and then GitHub does a little, it takes basically the artifacts and just spits them out. But there&#8217;s not much there in the automation on GitHub. It&#8217;s just publishing it to GitHub Pages.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The fact that I have a section that&#8217;s required for human in the loop kind of takes away full automation. I could make it run, but then I would have to take that component out of me reading through, clicking through, and writing my own judgment at the end of the report. And I don&#8217;t plan on getting rid of that. I actually enjoy that aspect, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:47] <strong>Nathan Wrigley:</strong> So it&#8217;s become a bit of an interface. The AI plus Damon equals the finished product. You really don&#8217;t want it to be automated. And in a way, that feels to me a bit like, I don&#8217;t know, a race to the bottom. If we automate all the things, I just don&#8217;t know where the audience for that lives, because you&#8217;ll, never really know. Because there&#8217;ll never be a moment where you look back at it and say, &#8220;Is anybody reading this?&#8221;. &#8220;Has anybody talked to me about this?&#8221; and what have you. Whereas the fact that you&#8217;re interested in it, you&#8217;re on this podcast talking about it, you&#8217;ve got an interest in the subject matter, you&#8217;ve clearly engaged with it. I don&#8217;t really have a question there, but there&#8217;s definitely something there. The fact that you&#8217;re in the weeds of it and it&#8217;s not just AI for AI sake, I think is important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:32] <strong>Damon Cook:</strong> Yeah. And it&#8217;s, yeah, that&#8217;s a great point. And I think that makes me, I don&#8217;t know, I guess go back to, where some of this started from. Yeah, I think people are creating their own knowledge bases. And you even touched on this. Just having that corpus of artifacts, a lot of that AI can do these days, and you can automate some of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But, how you take all that data and get the human in the loop and, is it even interesting if you, it&#8217;s interesting maybe to you to read, but if you want to share that, is it going to interest others? And yeah, the human aspect is critical for me there, because, especially if you&#8217;re going to share it publicly, you know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:14] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:14] <strong>Damon Cook:</strong> At least be transparent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:16] <strong>Nathan Wrigley:</strong> Yeah, so you&#8217;ve called it WP Trend Watcher. And it feels to me, if I was to rewind the clock to, I don&#8217;t know 2023, where for the first time we were all beguiled when ChatGPT came along, and we all just thought this whole interface was remarkable. But it felt, oh, it&#8217;s novel, it&#8217;s interesting, it behaves in many ways it&#8217;s a bit, I don&#8217;t know, passed the Turing test and it convinced us that it was human.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But now that we&#8217;re in the year 2026, it feels like one of AI&#8217;s central roles is just, as I said earlier, these corpses of information, but not finite in the way that a human brain is. There&#8217;s only a capacity that I have to remember so much, and it&#8217;s alarmingly little. But over time, if you were to stick with this endeavor, the name that you&#8217;ve given it, this sort of Trend Watcher, it feels like the data that you&#8217;re gathering, as it grows and grows and the AI&#8217;s capacity to manipulate, understand, I&#8217;m doing air quotes, &#8220;understand&#8221; and, create meaning from the disparate bits of data, that will grow over time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so it&#8217;d be interesting in 2027 and 2028, what happened? Why did that bit never got built? And how did we get this thing shipped into Core? Where did it come from? What were all the little bits and pieces? Where were the jigsaw pieces that led that to happen? And how did this happen? And what&#8217;s the market trend? Why have we got a 4% decrease or an 8% increase in market share? How&#8217;s all that happened?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it feels to me as if you keep pushing this out, that kind of information will be available, kind of MCP-able, by simply asking it questions, in a way that we&#8217;ve never had available to us in the past. Again, there&#8217;s no question, but do, you know what I&#8217;m saying there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:03] <strong>Damon Cook:</strong> Yeah. I think, when I set out to build this there is, and there is still a component where I do want to have kind of the trend watching part of taking these past reports and having AI review them, and come up with inference of was there a trend? Why, yeah, why did we go from report 1 to report 18 about this? Maybe there&#8217;s this feature in WordPress 7, whatever. What changed there? And come up with a separate component for that. I haven&#8217;t built that in, but that&#8217;s kind of a potential, that&#8217;s always the end goal. And keeping these receipts for now and generating these reports is just the scaffolding in a way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:48] <strong>Nathan Wrigley:</strong> So it feels to me as if it really isn&#8217;t bound to WordPress. You could run with what you&#8217;ve built and point it at just about any industry or thing. Your local tennis club or, whatever it may be. You could, over time, build up this sort of trend analysis, and see what&#8217;s going on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And dare I say it, you could even implement it upon yourself so that you can see, what&#8217;s the cadence of my writing? How have I done my fitbit data or whatever it may be? You can see that, even as I&#8217;m saying the words, I&#8217;m thinking, &#8220;Oh, this is a dystopia that I don&#8217;t want to live in.&#8221; But at the same time, I&#8217;m really curious as to what that bigger capacity to maintain state and hold data over time. What that will furnish us with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because we all forget things, our brains are very ephemeral. Things that are important to us come and go. We misremember things constantly, and it will be really interesting to see what things like you&#8217;ve built, are going to enable us in the future. And it does seem like this is baby steps. The humans in 2029 looking back on the work like you&#8217;ve just been talking about for the last half an hour will think, &#8220;Oh, that was cute, but look where we got to now, we stood on the shoulders of those giants, and here we are now.&#8221; It&#8217;s fascinating and terrifying in equal measure. Let&#8217;s say it that way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:11] <strong>Damon Cook:</strong> Yes. Yeah, absolutely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:13] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:14] <strong>Damon Cook:</strong> There&#8217;s so much data and it&#8217;s just growing, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:17] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:17] <strong>Damon Cook:</strong> It&#8217;s going to get worse before it gets better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:19] <strong>Nathan Wrigley:</strong> Yes. Well, it&#8217;ll be very interesting to see how it all lands. But, what I would encourage everybody to do, I&#8217;m going to link to at least three things. I will link to the GitHub repository, which is obviously at Damon&#8217;s GitHub account. It&#8217;s colorful-tones, and then this is called WP Trend Watcher. I&#8217;ll also link to damonacook.com, where there is a blog post about how you can get up and running and what the necessary steps are for you to do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I will also link to the sort of output, which is again, it&#8217;s a GitHub repository, but you can go and see the weekly summaries and what have you, and judge for yourself whether or not this is something that you want to install on your local machine.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think the inevitable is going to be that there&#8217;s going to be more and more of this in our lives. It remains to be seen whether we have the time to actually interact with the data that it puts out, or we&#8217;ll need another layer of AI to cope with the level of AI we&#8217;ve got, if you know what I mean. It&#8217;ll be wheels within wheels.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So there you go. Anything you want to add? Did I miss anything there before we wrap it up?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:27] <strong>Damon Cook:</strong> No, the only thing just you know I&#8217;m colorful-tones. Actually, it might not be with, it might not have the hyphen, but on X. And then on LinkedIn I try to just share the report out weekly on there just for folks keep up, but that&#8217;s about it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:47] <strong>Nathan Wrigley:</strong> Lovely, in that case, I will endeavor to find your Twitter or X handle and various other bits and pieces. And, wptavern.com, if you search for the episode with Damon Cook. It&#8217;s spelt in the way that you might imagine, D-A-M-O-N Cook, C-O-O-K. Search for that. And yeah, thank you so much for chatting to me today, and bravo for a topic which I think I&#8217;m going to be leveraging very much for my WordPress news cycle.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:14] <strong>Damon Cook:</strong> We can get that, get some RSS feeds and we can get them, get you hooked up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:18] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:18] <strong>Damon Cook:</strong> You can start generating some other reports.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:20] <strong>Nathan Wrigley:</strong> Okay, great. Yeah, let&#8217;s have a chat after we click stop in a moment. Damon Cook, thanks so much for chatting to me today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:26] <strong>Damon Cook:</strong> Thanks.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have Damon Cook.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Damon has been a developer in the WordPress ecosystem for over a decade, working with WordPress-centric agencies and, more recently, running his own freelance business, Noma Digital. He’s a long-time community member, contributor, and someone who remains keenly engaged with the latest WordPress developments, from releases like 7.1 to shifts in plugins, themes, and the broader WordPress landscape.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Damon joins us today to discuss WP Trend Watcher, an open source tool he created to help WordPress professionals keep up with the ever-increasing deluge of news, community updates, and feature releases. As the WordPress space grows more dynamic, and let’s be honest, sometimes a bit overwhelming, WP Trend Watcher is designed to sift through a fire hose of RSS feeds, summarise the trends, and inject some much-needed human curation into AI-generated content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Damon talks about the importance of staying ahead in the WordPress ecosystem, especially for freelancers, agency owners, and developers who want to anticipate changes and support their clients. He gets into the technical nuts and bolts, breaking down how the tool gathers and summarises news, the models and local AI setup he’s experimented with, and the balance between automation and critical human review.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re someone who struggles to keep up with the relentless pace of WordPress news and wants a smarter way to separate the worthwhile updates from the dross, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://nomadigital.dev\">Noma Digital</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://x.com/ColorfulTones\">Damon on X</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.linkedin.com/in/damon-c-541a9b37/\">Damon on LinkedIn</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/colorful-tones/wp-trend-watcher\">WP Trend Watcher on GitHub</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://damonacook.com/wp-trend-watcher-wordpress-trends-ai-workflow/\">You Don’t Need a Fancy AI Setup to Stay Current With WordPress</a> &#8211; Damons post about why he built WP Trend Watcher and how to install it</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://colorful-tones.github.io/wp-trend-watcher/\">Recent &#8220;editions&#8221; of WP Trend Watcher</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 26 Aug 2026 14:07:24 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"Open Channels FM: Building with AI How WordPress Standards Shape the Future of Open Source\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560194\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://openchannels.fm/building-with-ai-how-wordpress-standards-shape-the-future-of-open-source/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:164:\"In this episode, Adam and Nate discuss WordPress\'s evolution amidst AI\'s rise, emphasizing challenges like security and the need for developer intent and standards.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 26 Aug 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"Open Channels FM: Linux Foundation Proposes OpenMDW AI License as Debian and Bitcoin Tackle Open Source Security\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560229\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:119:\"https://openchannels.fm/linux-foundation-proposes-openmdw-ai-license-as-debian-and-bitcoin-tackle-open-source-security/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:183:\"Open Channels News discusses AI\'s impact on open source, highlighting the Linux Foundation\'s new license, Debian\'s debate on AI-generated code, and Bitcoin\'s security vulnerabilities.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 26 Aug 2026 08:40:55 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"Open Channels FM: Exploring AI in Security and the Workplace Perspectives from ACM, Forrester, Reuters, and European Policy\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560177\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:127:\"https://openchannels.fm/exploring-ai-in-security-and-the-workplace-perspectives-from-acm-forrester-reuters-and-european-policy/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:218:\"This news episode reports on challenges posed by AI in cybersecurity, including supply chain risks, vulnerability discovery bottlenecks, job market shifts due to layoffs, and the balance of autonomy and accountability.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 25 Aug 2026 09:23:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"Gutenberg Times: Gutenberg Changelog #134 – Gutenberg 23.7, 23.8, WordPress 7.1 and more\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://gutenbergtimes.com/?post_type=podcast&p=46979\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:74139:\"<p class=\"wp-block-paragraph\">In this 134th episode of the Gutenberg Changelog Podcast, Birgit Pauli-Haack hosts Jessica Lyschik , senior developer at Greyd, to discuss recent Gutenberg and WordPress developments. The conversation centers on the releases of Gutenberg 23.7, 23.8, and WordPress 7.1 (&#8220;Mary Lou&#8221;), highlighting user-facing enhancements and developer-oriented changes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 introduced notable features, including new styling tools, updated media flow, notes functionality for collaboration, and improved support for AI-driven workflows. Jessica Lyschik emphasized the impactful addition of pseudo states (hover, focus, active) in buttons and navigation links, though global style options for navigation states are still being developed for 7.2. The new icon API was also discussed, which currently requires plugins for full editor integration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Both speakers observed an ongoing shift: features first become available via <code>theme.json</code> for theme builders, then gradually get exposed in the UI for broader audiences. They also touched on the evolving approach to child themes, font management, and the need for clear style inheritance indicators. Specific enhancements in Gutenberg 23.7/23.8, like responsive editing toggles and improvements to dynamic galleries and block inspector controls, were covered alongside new opt-out mechanisms for block controls.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The episode closed with a look toward WordPress 7.2, highlighting efforts to address &#8220;block editor paper cuts&#8221; (small annoyances) and improved tracking of in-progress features. Birgit Pauli-Haack announced a three-month podcast hiatus for sabbatical, promising a return for the 7.2 release. Listeners were encouraged to follow GitHub tracking issues and stay current with upcoming Gutenberg releases.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/#shownotes\">Show Notes</a> / <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/#transcript\">Transcript</a></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Editor: <a href=\"https://www.linkedin.com/in/sandy-reed/\">Sandy Reed</a></li>\n\n\n\n<li>Logo: <a href=\"https://markuraine.com/\">Mark Uraine</a></li>\n\n\n\n<li>Production: <a href=\"https://icodeforapurpose.com/\">Birgit Pauli-Haack</a></li>\n</ul>\n\n\n\n<p class=\"has-larger-font-size wp-block-paragraph\" id=\"shownotes\"><strong>Show Notes</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Special Guest: Jessica Lyschik</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://x.com/jessicalyschik\">https://x.com/jessicalyschik</a></li>\n\n\n\n<li><a href=\"https://www.youtube.com/@jessicalyschik\">https://www.youtube.com/@jessicalyschik</a></li>\n\n\n\n<li><a href=\"https://www.youtube.com/redirect?event=channel_description&amp;redir_token=QUFFLUhqa2tsT25ETnVSM20xS3ZoNDhpTkhwUVhlM2J0UXxBQ3Jtc0tsY2NmeEdxT01xdEMzMlR4WWxjYll2bGoyMXlSZVZFZm82alVtS3hpdW01Y3U1R3U0RGVBT19lbEhQeXNYeTcxZ0EwaVg4YUlYV2ZGR085ZXA1U0pYYzdSelRnejR5cDBHUm1pZDRpQi1fdHRPbkw3UQ&amp;q=https%3A%2F%2Fprofiles.wordpress.org%2Fluminuu\">profiles.wordpress.org/luminuu</a></li>\n\n\n\n<li><a href=\"https://www.youtube.com/playlist?list=PLtf0_A0KILu5lspB8oXQjinPhIe87s3nJ\">Greyd Conversations, to be found on YouTube</a></li>\n\n\n\n<li><a href=\"https://www.meetup.com/wordpress-online-meetup-dach/\">DACH Online WordPress Meetup</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Announcements / Community contributions</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/08/12/wordpress-7-2-call-for-volunteers/\">WordPress 7.2 Call for Volunteers</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/14/wordpress-contributor-toolkit-1-0-a-smoother-workflow-for-your-first-core-contribution/\">WordPress Contributor Toolkit 1.0: A smoother workflow for your first Core contribution</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress 7.1 </h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/news/2026/08/mary-lou/\">WordPress 7.1 “Mary Lou”</a></li>\n\n\n\n<li><a href=\"https://www.youtube.com/watch?v=dO751c8jkn0\">WordPress 7.1 Highlights Video</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/download/releases/7-1/\">WordPress 7.1 micro site</a> </li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">WordPress 7.1 Field Guide</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/documentation/wordpress-version/version-7.1/\">WordPress 7.1 Release Notes</a></li>\n\n\n\n<li><strong>Curated </strong>\n<ul class=\"wp-block-list\">\n<li><a href=\"https://developer.wordpress.org/news/2026/08/hands-on-with-the-wordpress-7-1-icon-registration-api/\">Hands-on with the WordPress 7.1 Icon Registration API</a></li>\n\n\n\n<li><a href=\"https://developer.wordpress.org/news/2026/08/whats-new-for-developers-august-2026/\">What’s new for developers (August 2026) </a></li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/\">WordPress 7.1 Source of Truth</a> (English) </li>\n\n\n\n<li><a href=\"https://krautpress.de/2026/wordpress-7-1-source-of-truth/\">WordPress 7.1 Source of Truth – Deutsch</a></li>\n</ul>\n</li>\n\n\n\n<li><strong>Podcasts</strong>\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wpbuilds.com/2026/07/30/478-inside-wordpress-7-1-responsive-styling-new-blocks-media-modal-and-behind-the-scenes-changes/\">478 – Inside WordPress 7.1 – responsive styling, new blocks, media modal and behind-the-scenes changes</a></li>\n\n\n\n<li><a href=\"https://presswerk.net/pw075/\">WordPress 7.1 mit Birgit Pauli-Haack</a> (German) </li>\n</ul>\n</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Gutenberg releases</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">What’s new in Gutenberg 23.7? (05 August)</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">What’s new in Gutenberg 23.8? (19 August)</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s discussed or in the works</h2>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress 7.2 Tracking issues </h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Styling</strong>\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/80388\" rel=\"noopener\" target=\"_blank\">Responsive style states for blocks – 7.2 tasks</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/79283\" rel=\"noopener\" target=\"_blank\">Custom states for blocks – iteration for WP 7.2</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/34198\" rel=\"noopener\" target=\"_blank\">Form elements in Global Styles – iteration for WP 7.2</a></li>\n</ul>\n</li>\n\n\n\n<li><strong>Editor </strong>\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/81453\">Block Editor Paper Cuts</a> </li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/81558\" rel=\"noopener\" target=\"_blank\">WordPress 7.2 and beyond: Pattern Editing follow ups</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/79895\" rel=\"noopener\" target=\"_blank\">Extensible Site Editor: 7.2 Iteration Issue</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/77069\" rel=\"noopener\" target=\"_blank\">Improve Navigation Editing in the Extensible Site Editor Sidebar for 7.2</a></li>\n</ul>\n</li>\n\n\n\n<li><strong>Media</strong>\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/80389\" rel=\"noopener\" target=\"_blank\">WordPress 7.2 Iteration: Media Editor Modal</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/80159\" rel=\"noopener\" target=\"_blank\">Client Side Media iteration for WordPress 7.2 and beyond</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/81370\" rel=\"noopener\" target=\"_blank\">WordPress 7.2: Dynamic galleries and media inserter</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/79729\" rel=\"noopener\" target=\"_blank\">Discussion: How might the media inserter tab look in WP 7.2+</a></li>\n</ul>\n</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/80015\" rel=\"noopener\" target=\"_blank\">Notes iteration for WordPress 7.2</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/81228\" rel=\"noopener\" target=\"_blank\">DataViews, DataViewsPicker, DataForm, Fields in WordPress 7.2</a></li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/issues/77230\" rel=\"noopener\" target=\"_blank\">Guidelines built on Knowledge in WordPress 7.2</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Greyd Conversations</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.youtube.com/watch?v=dxpoqqtwOIg\">Greyd Conversations #19 &#8211; How Can Product Companies Grow in WordPress Right Now</a><br /></p>\n\n\n\n<p class=\"has-large-font-size wp-block-paragraph\">Stay in Touch</p>\n\n\n\n<div class=\"wp-block-group is-layout-flow wp-block-group-is-layout-flow\">\n<ul class=\"wp-block-list\">\n<li>Did you like this episode? <a href=\"https://lovethepodcast.com/gutenbergchangelog\"><strong>Please write us a review </strong></a></li>\n\n\n\n<li>Ping us on X (formerly known as Twitter) or send DMs with questions. <a href=\"https://twitter.com/gutenbergtimes\">@gutenbergtimes </a>and <a href=\"https://twitter.com/bph\">@bph</a>.</li>\n\n\n\n<li><em>If you have questions or suggestions, or news you want us to include, send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a>. </em></li>\n\n\n\n<li><em>Please write us a review on iTunes! <a href=\"https://gutenbergtimes.com/itunes/\">(Click here to learn how)</a></em></li>\n</ul>\n</div>\n\n\n\n<p class=\"has-large-font-size wp-block-paragraph\" id=\"transcript\"><strong>Transcript</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Welcome to our 134th episode of the Gutenberg Changelog podcast. In today&#8217;s episode, we will talk about Gutenberg 23.7 and 23.8, and also, of course, WordPress 7.1, which was just released, and also what&#8217;s in the pipeline. Not very detailed, but we&#8217;ll see. I&#8217;m your host, Birgit Pauli-Haack, curator at the Gutenberg Times and a full-time core contributor for the WordPress open source project sponsored by Automattic. It&#8217;s again a special treat for me to have Jessica Lyschik to join me on the show again. Jessica is a senior developer at Greyd, which is a German WordPress company that builds Greyd.Suite, an all-in-one toolkit for building and managing professional WordPress sites. Welcome to the show, Jessica. How are you today?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Thank you. I&#8217;m very good today. And thanks for having me yet again. I don&#8217;t know how often have I been here now?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> I think it&#8217;s either the 6th.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> 3rd, 4th?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Well, I think we&#8217;re coming up to 6 or 7.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Is there like an ongoing list of people how often they have been on the show?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Of course. Of course there is a list.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Probably I&#8217;m very at the top.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> It feels like. Absolutely. Yeah, you are. Top producer here.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Nice.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. So Jessica, you are not only working on Greyd, you also work co-organizer on the WordPress Germany, and you also are a co-organizer for the German-speaking DACH Online WordPress Meetup. DACH, for those who don&#8217;t know it, is Deutsch, Austrian, also Österreich and Schweiz, Länderkennung.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> And the meetup comes together every other month, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> The 3rd Wednesday in a month in odd months. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Correct. Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. So what are you doing there? What&#8217;s coming over next?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> So our next meetup is, well, it is all in German. So for those listeners who are not speaking German, it&#8217;s unfortunately not for you, but you can try and come over and practice and listen. But we mainly held a whole day meetup in German. So for the German, Austrian, and Swiss communities. And yeah, the next meetup is in September and it is, yes, on the 16th. And we are talking about WordPress 7.0 and 7.1 as the latest releases. We will have Benjamin Sekavica with us who was also the, I think, release coordinator for 7.1, if I&#8217;m not mistaken.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> So he will share a bit more because he has been fairly involved into the last past 2 releases and he will share a few insights and everyone can share their experiences. We can answer each other&#8217;s questions. And yeah, that&#8217;s what we are going to do. So we aim for more of a professional audience with the online meetup.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> You mean developers and agencies?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, or also anyone who is working professionally with WordPress. And we are not focusing too much on like beginners, but this is our area where we have our target audience, basically.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, yeah, it makes sense. Awesome.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Announcements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Well, thanks for letting us know about that. We&#8217;re coming to some announcements. I only got one that I wanted to share with you, dear listeners. Jeff Paul opened the call for volunteers for WordPress 7.2 release squad, and the release is scheduled for December 9th. So that&#8217;s kind of the timeframe that you&#8217;re looking at. December 9th means there&#8217;s 4 weeks beforehand is release candidate, and 6 weeks and 7 weeks is beta before that. So by October, you&#8217;re probably gonna be part of the— ongoing work to get this release over the finish line 2 months later.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So experience being on the release squad, you had experience with that and I had too. I don&#8217;t think that&#8217;s a job for someone who hasn&#8217;t been part of core for a while because it&#8217;s a very fast-moving process and you need to know a lot about how WordPress is actually managed, developed, and released.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: There are quite a few release squads from previous releases that could come up and volunteer again. Yeah. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Community Contributions</h3>\n\n\n\n<p class=\"wp-block-paragraph\">So speaking of first-time contributors to core, there is a new WordPress Contributor Toolkit that has been tested quite a bit, and it&#8217;s out in the first version. The first contribution does not start again with installing Git, Node.js, and Docker, and kind of takes the whole Contributor Day morning or in the afternoon when you start doing that. So this is a desktop …</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I remember this.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. And not everybody has their computer set up so it all goes smoothly. Yeah. So I have always had trouble with all the installations because my computer is not on the latest stuff. Yeah. So this desktop app handles it all. And after you run the setup wizard, Contributors can link to a track ticket and apply or test existing patches on the running site. It&#8217;s also based on Playground. And then open a pull request or attach a patch or hand their work to a mentor or— yeah, there&#8217;s quite a few features in there. And Juan Margarito is the project manager, so to speak, but he had input from quite a few core contributors. And I have not heard yet how it all went on WordCamp US, but I think the next version for WordCamp Asia is already in the works. So yeah, test it out. Then if you see something that needs to be fixed or that doesn&#8217;t work, yeah, find your way into the GitHub repo so you can leave an issue or, yeah, have some discussion there.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, that sounds actually very promising to speed up the process. As I said, I remember like being on Contributor Day and now you have to install this, now you have to install Docker. Now you have to do this. Docker doesn&#8217;t work properly. What is the issue? It was a never-ending story. And having a setup that is like ready to go, I think this is very interesting. Yeah, I have not been at WordCamp US either, so I don&#8217;t know how this worked out, but I heard only good vibes so far from Contributor Day. Right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> They published quite a few.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I think it will speed up the process.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, absolutely. Yeah. Yeah, WordCamp US was, the Contributor Day were about 400 people out of 1,000. So that&#8217;s a phenomenal ratio there. And they changed the format a little bit from what I read, that they actually were project-oriented. So they actually were able to finish a few projects. And it&#8217;s more like a hackathon rather than kind of everybody picks something up and works on things. And that&#8217;s what I heard from a lot of people that were at the contributor day.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah.</p>\n\n\n\n<h3 class=\"wp-block-heading\">What’s Released &#8211; WordPress 7.1</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> And on August 19th, WordPress 7.1 was released called Mary Lou. After the jazz musician Mary Lou Williams, who has over 100 records. So she was very prolific in producing her music. And I&#8217;m glad that we found another woman to be part of the jazz naming for a WordPress version. </p>\n\n\n\n<p class=\"wp-block-paragraph\">We talked quite a bit on this show about the various features. Just a reminder, there&#8217;s a lot packed into new styling tools. Updated media flows, added notes functionality, some changes to the new capabilities for AI, other tools and workflows. Anne McCarthy was the first-time release lead for it, and I must say she did a fantastic job, probably better than any other of the release leads because her communication style was very upfront, and it was also always kind of keeping everybody in the loop, and it was really nice to see. And for me, working on the source of truth, truth, it was really helpful that she was the release lead and I could bounce off some things like, how does it work? Or did I get this right? Or yeah, what is missing? What are your most favorite features from 7.1? Or what is it that tripped you up as a developer? Kind of, we can have both ways of talking about things.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, we can, we can do it. There&#8217;s, uh, some things that have happened. So what I&#8217;m really happy about is the pseudo states. So hover, focus, active on buttons. For when I saw that, I went in there and during the release candidate phase and was like, hmm, I read something about navigation and if in the source of truth, what is going on? So I figured out that navigation links do have on the individual navigation links, you can toggle it on. But then I thought like, hey, for navigation, it would just make so much more sense if you would do that in the global styles. But it was not there. So there was nothing in the global styles to change these states. And I was a bit confused about that. But glad we figured it out in the outreach channel. I think I posted it on Slack. And it was actually not done yet because there&#8217;s one more addition coming to it, which is the, the active state.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> So it&#8217;s not the, it&#8217;s not the pseudo state active, but when you have in WordPress, when you click on a navigation item, then this specific navigation item on the page you&#8217;re on gets the class current menu item as of now. I don&#8217;t think this is going to change in the future, but then what&#8217;s being worked on is that this also can be, this color can also be changed or this settings for when this state is actually happening.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: And now for the navigation items, you would have then 3 states. So you have the responsive styles, you would have the pseudo styles, and you would have this active style. And because these are kind of intertwined, this was the reason why it has not been coming into 7.1 yet, but it&#8217;s being worked on for 7.2. So Maggie is on it. Maggie Cabrera, who I did the Twenty Twenty-Four theme with, she&#8217;s working on that. So that&#8217;s very cool. And yeah, that&#8217;s something to look forward because I just remember like the last week been talking about it with someone and it was in Torino Twenty Twenty-Four on my talk when at Workcamp Europe where I think it was Rich Tabor who asked the question what I would like to see, and I was like, pseudo styles would be great. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> So 2 years later, we are finally here. Of course, it&#8217;s not everywhere yet, but I think it&#8217;s a very good start. We have it on buttons now, and it can only extend to other blocks as we have seen it with many features before. They start out on one very specific area and then got released to the rest of the items that are there. So yeah, I&#8217;m very much looking forward to that. The new icon API is also something that&#8217;s very interesting. And I just had an email from a client today saying, hey, there&#8217;s this new icon API. What&#8217;s, what&#8217;s the matter? So I was curious too, of course, can I just do this in the editor? Because this was probably most people are going to ask. And no, you cannot, but you technically can through a plugin. There&#8217;s also an article from Justin Tadlock on the developer blog about this, right? I saw that this week.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I have not tested it out yet. I had not had the time with this, but it definitely looks promising to— we&#8217;re getting there to like all these little changes that are kind of not just nice to have, but kind of sort of life improvements to how you would otherwise work that. I mean, there&#8217;s the icon block, of course, from Nick Diego, who is like the base for all what is in Core now, but you still can do a lot more in terms of customization with it. But yeah, we&#8217;re getting there. So yeah, we&#8217;re looking forward to that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. So when you say it&#8217;s not there yet for the navigation link, it&#8217;s also not there. Well, you can do it in the theme.json. So it&#8217;s just the UI or the interface wasn&#8217;t finished. But the feature is there for theme builders that use the theme.json to style their stuff. They don&#8217;t have to rely on the global styles interface.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, but that&#8217;s always the first route you go. So you go first in the editor. Can I see it? Is it there? And it was like, eh, disappointment. Yeah, but that&#8217;s what I forgot to mention. You can use it through theme.json, but then it&#8217;s like a bit of a, how to say, it&#8217;s, yeah, like you need to have your own theme.json. You just cannot go into any default theme or any existing theme that is from another author and then change it there because with the next theme update, your changes will be gone. So this is something you have to watch out for. And then for most people, it&#8217;s like also the feedback I often get from clients, from colleagues, it&#8217;s like, is it in the editor? No, sorry.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Not yet. Still have to code. Not yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Not yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> But that&#8217;s pretty much the cadence of any of the styling things, that they are first coming into theme.json for theme builders, because that&#8217;s the basis of it. That&#8217;s kind of the API. That&#8217;s the— yeah, how it all fits in with the rest of it. And then it&#8217;s a whole different mindset to figure out how the interface is going to work, because the interface also needs to kind of figure out not only for those that are advanced builders, but also for those that are actually beginners or don&#8217;t know what a pseudo-state is. Yeah, so you have a language issue there, and it&#8217;s a whole different mindset to get this right for the interface. And I&#8217;m really glad that we finally have it in the theme.json and people can work with it from there. But yeah, you&#8217;re right, it&#8217;s not for one of the default themes where you can change the theme.json. Yeah, but it&#8217;s your own. Yeah, like I did for the Gutenberg Times. I have my own theme and I can kind of change things there.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, it just depends how comfortable people are with using it. So if some are just, give me an existing theme that does get updates every now and then to do changes. And some just code their own because they feel comfortable with it. So It&#8217;s, it&#8217;s just that as long as we communicate, hey, that&#8217;s the current state of this. You can use it there, here and there, but here, watch out. This is the catch. Then I think it&#8217;s all fine because the more you know, the more you can adjust to your needs.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> And some who are longer in the WordPress space than just 4 years or so, so since it&#8217;s block themes, there is also the idea of a child theme that a lot of people go that route, which has its own theme.json. that is then combined with the parent theme and the global style. It gets a little bit unwieldy. Yeah, kind of figuring out where things are changed and how do you revert something and where does it go? Because you also have the additional CSS and then the block-level CSS. So yeah, there&#8217;s a lot of things that you can change and confuse everybody.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Or even yourself. So it does happen that you change something somewhere, then forget about it and come back like 6 months later and be like, Why does this not change when I change the setting here? Now I can change the setting, but nothing happens. And I&#8217;ve been there. Don&#8217;t worry. It happens to the best. So it&#8217;s a tough one, but yeah, you just have to find your way in how you approach things. And again, everyone&#8217;s different. Everyone has different knowledge, different base on it. Child themes, definitely you can use them. Some people say child themes are dead. Well, it depends.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> It depends. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: I mean, the most cases are slowly like, for example, if you wanted to use fonts, special fonts, then a child theme was always the best option to just have the files there, implement them and queue them correctly and so on. Well, now we have the font library. So. With a little exception, if you cannot upload certain fonts or do not want to use Google Fonts, for example, like there&#8217;s Adobe and like Adobe Fonts and another font places. where we, where you can get fonts from, you still need to implement them in a sort of hacky way. It does work. It&#8217;s not perfect, but it&#8217;s one of those things where a child theme would, or is still useful in my opinion.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And yeah, there&#8217;s just so much variety around it. So yeah, everyone will find its way or their way too.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> I made the decision to not go with child theme, although the Gutenberg Times theme is based on Twenty Twenty-Five. Okay. I don&#8217;t, I don&#8217;t wanna kind of have this whole mental load, like figuring out where my patterns live or what are the theme.json settings that I need to override. And so I said, okay, I will make a copy and delete everything else that I need— don&#8217;t need, and then take it from there. It&#8217;s so robust that I don&#8217;t think I&#8217;m running into any problems that I didn&#8217;t make myself. Yeah. </p>\n\n\n\n<p class=\"wp-block-paragraph\">What else? 7.1, I wanted to interject that with— so 7.2 is of course coming. We talked about it on December 9th. There is not a roadmap out yet, but what&#8217;s already in the works is what you mentioned is that we get ourselves confused when we don&#8217;t know where things are in styling. There&#8217;s actually an effort to have in the inheritance of styles be marked in the interface. There is a discussion on how to make that, and the designers are still kind of figuring it out. But you get an indicator in either the global styles or in the block settings in the sidebar if that&#8217;s a changed style. So it&#8217;s not the global style, but it&#8217;s kind of an individual style. So you can at least manage that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Or at least recognize it. How far it goes, we don&#8217;t know, but the discussions are there. And I will link that particular issue in the show notes so you can kind of check it out if you want to and kind of see how that&#8217;s gonna come out. So anything else you wanna kind of say what you like about 7.1? What about the responsive styles? Do you like them?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: They look promising. I have not tried them out yet. I mean, it&#8217;s been just 2 days. I have been very busy with keeping up and, well, not having things break for great customers. We did have a little release. I was doing a little release yesterday for a little fix. No fatal errors or anything. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, you are on your tippy toes when a new release is out. And of course, I have had it running on my local environment for quite some time, the release candidate, just to make sure that if I work or test things that I do not run into any issues. No, no deep dive yet, but what I noticed is that quite a few things moved around. For example, I was just made aware of yesterday that at the group block, you now have these settings that were usually the first thing. It&#8217;s like the blocks should inherit the site width or content width or something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Oh yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> This, this, the layout. Yeah. The layout part, it has now been moved from the settings to the styles. And I think this was because of the responsiveness, because then you have everything together in one go and do not have to switch the tabs back and forth for this.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I mean, there is some refinement in the, in the UI of how things look. I think the notices got quite an update. They are looking different now. And it&#8217;s just like the little details from what I noticed in working on it, but I did not do yet, unfortunately, but I hope I can. Yeah. Dive a bit more deeper in this weekend. What&#8217;s new? I&#8217;ve been just reading on, just checking technically if there&#8217;s anything. I mean, one big thing is definitely the enforced iframe in the editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. I was about to ask you about that, if you had any issues there with your—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> We actually prepared for 7.0 already because it was first said, hey, we are doing this for 7.0, and then it was rolled back. It&#8217;s like, okay, we are not doing this for 7.0, but we are doing this for 7.1. So we were kind of prepared.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: We just had to catch up with, I think, 2 blocks that we offer, but all, all works fine. So we are, we are good now there. And we did this ahead of time. So we were aware of these changes. And this is what I&#8217;m looking out specifically. Sometimes the fancy details as well, because I have to know, because most people come to me in my company saying, hey, why is that? What, what, what have, what has changed here? Tell me. And then I have to go to deep dive. I did it. I did this yesterday to say, why did things move? Ah, things move because of the responsive styles. Okay. So then you have the train of thought and know what&#8217;s happening, like kind of reverse engineering it, if you will.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> But yeah, I will have a deeper dive into 7.1 and testing out a few things because I&#8217;m curious myself. I mean, of course we still work in, in and with WordPress, so we need to be aware of what&#8217;s happening.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Gutenberg 23.7</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> All right. Yeah. So Gutenberg 23.7 was released and it has a few enhancements that we can talk about. Some of them actually made it into 7.1, which is actually a little bit unusual because normally after beta there are no enhancements. But if that&#8217;s a blessed, so to speak, feature, then still enhancement can make it into beta. And even if a release candidate, if it&#8217;s important and it needs to be fixed. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Enhancements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">So there were not a whole lot of things that I would point out, but the first one was the responsive editing enabled setting.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> With that, you can actually turn off the responsive styles option, and that made it into 7.1. It&#8217;s just a setting in your, in your block.json file, there, I think there&#8217;s also a filter where you can do that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Yeah, you can use a filter in the functions.php of your theme or child theme, preferably child theme in this case.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Just where we had it. So you can, but then it&#8217;s, I think it removes it completely if I&#8217;m not mistaken, because the way the filter looks to me looks like it would disable it for everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: When you use it on the block itself in the block.json, then it&#8217;s just for that one block.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Right, right. The filters goes for everything. And it could be custom blocks, yeah, that you don&#8217;t want the responsive editing to come in, or you want them enabled. You know, it&#8217;s kind of the other thing. What is not turned off is the styling that you already put in. Yeah. So those are not affected by that filter. So if you come from a theme that already has them in the global styles or in the theme.json, they&#8217;re not turned off. It only turns off.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah. So it&#8217;s just basically in the user interface that you do not have this option anymore. You cannot access it anymore. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So it, it came out of the feedback loop from a lot of agencies that kind of said, okay, can I have my user not use that? So, which is pretty common for WordPress. Yeah. If you have a new feature that you also need to implement a turnoff thing for a lot of people. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The next one. is to extract— well, I&#8217;m reading that— to extract the preset management from shadows and font sizes. To implement those presets for shadows, so you have your own shadow configuration or your own font size configuration in the global styles or in the theme.json, those are actually handled pretty similar. And the developers said, okay, we don&#8217;t want to have too many same-looking files in our codebase. So let&#8217;s unify things and make it available so we can actually add additional presets with the same management kind of system. It&#8217;s a codebase and it&#8217;s on Gutenberg behind the scenes, but I think it will actually change a little bit how you code that for your custom blocks if you want to also have preset management enabled with that. So I wanted to point that out. I don&#8217;t know if that makes any sense to you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I have to deep— deeper dive into it because I actually don&#8217;t— it was not on my radar, to be honest, but it sounds fairly interesting. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Do you wanna take the next one?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Reflect inherited global styles values and block inspector controls. This was what you were just talking about, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So it is already in 23.7. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Yeah. I think when you scroll down further, I think this is with the kind of, how do you say, flipped squares or diamond sort of shape. I wonder if this is maybe not too— it&#8217;s not too visible. It&#8217;s like very hidden and kind of very much blends in. I would be curious to see what that actually looks like. So, okay, I do not have only 7.1 tasks for me for this weekend, but also Gutenberg tasks. Coming from the, what you just described before, that you don&#8217;t know where things are coming from, if things have changed locally, I think this is a very interesting user interface change that I assume will be kind of helpful for people to figure out, okay, apparently this is not the global style. Something has changed here. The question is then where?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> It will be interesting to see how good this particular style or sort of indication will be, will be kind of recognized because I find it very, it blends in too much from, in my opinion.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I think there needs to be a pop of color because we have this purple color as well for certain things in editor. And I think because if it&#8217;s just black and white, it&#8217;s kind of, it blends in too much because you have the, there&#8217;s screenshots from the typography panel when you choose the font size, when it&#8217;s You have only 5 options, S, M, L, XL, and XXL. And then it&#8217;s just a little dot or an outlined dot sort of, because it&#8217;s fairly small and it kind of blends in with the toggle next to it where you can toggle the Preset selection. Yeah, the sizes. So yeah, you&#8217;re right to see what other people will think about this.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, it will come with a tooltip definitely for that. And it also will open a modal or will open the same modal that you have where you can reset a setting. So if somebody says, okay, we changed the theme update and you didn&#8217;t see— that&#8217;s the case where it really makes sense is, oh, and you don&#8217;t see the new styles or new things is because you have an override in the database and you can reset that to theme style and then you get the new new stuff in there. So that&#8217;s kind of the use case that I can think of. And I think it makes fairly sense. And once you know what that little diamond or whatever does, but you&#8217;re right, it&#8217;s not in your face and it&#8217;s not very …</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: I mean, it shouldn&#8217;t be like in your face, like kind of be like a giant billboard, you have made a change here, but it should be like a bit more coming out a bit more because right now I think it blends in too much. And I would probably be wondering if this is maybe a bug or if that neighboring icon may be having some sort of display issue or something because it&#8217;s too— not distinct enough, I think is the right term.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> It&#8217;s very subtle. Subtle, yeah. Yeah, I— when I first looked at it, was it a scratch on my screen or something like that?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, exactly, exactly. So I was like, It looks a bit small, so I have to check it out on, on like on an actual installation and see what happens. If I notice it or if I just wonder where I did the change and it did not happen for whatever reason.</p>\n\n\n\n<h3 class=\"wp-block-heading\">But Fixes</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, the next item is, it&#8217;s one of those quality of life things that you mentioned. It&#8217;s that the COVID and accordion blocks have now an exit on enter. So you hit enter once, you get to the next one, and then enter twice and you&#8217;re out of that whole container block. I only want to mention it because it&#8217;s— I found it missing on quite a few ones, except especially one of the cover and accordions. But it&#8217;s also when you— if you&#8217;re a developer and you want to learn how to do this, this is also a PR where you can actually check out how that&#8217;s going to work because it&#8217;s actually just a block support, yeah, that you need to put in there. It&#8217;s an experimental API, but it has been around for I think about 2 years now. And as long as Core is using it, it&#8217;s probably gonna stay there. So it could be also a good way for the block developers to kind of learn that little quality of life feature that you give the user out on the, on the block without having to do after and before kind of thing. Yeah. That I have to refer to once in a while.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, but I didn&#8217;t know about it. I learned something today.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Mission accomplished.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, but it&#8217;s actually, yeah, I can totally get it for the COVID block because like what I am, I&#8217;m hon— I wanna be honest here. I am very much, I click away. I click somewhere outside because it does not work in, quote, in air quotes that, uh, you can exit a block and go up the next level outside of the block. So yeah, that&#8217;s good to know.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> All right, great. Yeah. Do you want to take the next one?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jessica Lyschik: Yeah. Dynamic gallery. Rename toolbar button to detach and add a modal explaining what will happen.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> The dynamic gallery is the one where you can have a gallery automatically created from your attached images. And that&#8217;s especially interesting for those that have been blogging for a long time and have been there. Photos all over the place. And now they can, you can, you don&#8217;t have to take one image at a time. You can do it all in one swoop. But the problem is when you want to add an image that&#8217;s not attached to it, or if you want to delete one, you need to break that dynamic thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Oh yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. So you can do singular image things with a gallery. So you need to detach it. And then the modal explains that particular context. Kind of comes up and say, you say okay, and then be done with it. That detached image also comes, and we see it probably in 23.8 when we talk about it later. That&#8217;s also the same method how you can, for the page list in the navigation, that&#8217;s at first a dynamic one, but once you change things and add another link in there, it&#8217;s kind of not dynamic anymore. So it will, new things will not be added is also a downside of that. And it&#8217;s the same thing for the table of content block has instead of the, it had a long time convert to a static list. So it&#8217;s also not dynamic anymore. It&#8217;s now also called detach. I don&#8217;t know if it&#8217;s the same modal. I haven&#8217;t tested that yet, but it&#8217;s kind of a switch in. How, how we teach people about the attach and detach kind of thing, kind of the, the context of this is a dynamic block that you can actually free from the, from that automation.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Yeah, we actually have the similar wording in the Grid plugin. So it&#8217;s, it&#8217;s very familiar to see here, detach this. Because we also have sort of like these dynamic features and you can detach stuff from these dynamic features to make them static. Basically what you just explained. It&#8217;s interesting to see that even though I don&#8217;t think anyone has ever, like I was not involved in this, but seeing this basically turning out exactly what we&#8217;ve been doing in a product already, it&#8217;s kind of interesting. So it&#8217;s, I guess, not the worst idea to do.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. But like, especially when it&#8217;s kind of already done by you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, yeah, yeah. But like, it&#8217;s like to have a— not really consenting, but like to have a general understanding of that, this wording of detaching stuff and like having it dynamic is like universal, sort of. So, and this is kind of the language where we are going to. Yeah, it&#8217;s just great to see that there is not much that you have to reteach people because plugins have it done this way, but now core is like kind of catching up and you can use that knowledge that, okay, if I detach this, it&#8217;s no longer connected to it. And if it&#8217;s kind of dynamic, then okay, maybe there is some sort of connection. I mean, in a very broad sense now.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. Yeah. Glad we can kind of continue in the consistency that you brought to your product in core.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> It&#8217;s really, it&#8217;s my, And I was not involved. I just want to say that I was not involved in this one.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Don&#8217;t blame me. Yeah. So, so what&#8217;s next? I don&#8217;t know why I looked at that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Dynamic mode conversion, a single undo level. I think this was also part of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah, I tested this dynamic gallery quite a bit because I couldn&#8217;t get my head around why that was important because I don&#8217;t— every time I&#8217;m in my block editor on a post, I upload images and I know they&#8217;re automatically attached, but I wouldn&#8217;t upload images in bulk in my editor. And then I kind of, it flipped for me that, okay, in the media library I can upload images in bulk and I can also in bulk attach it to a post. There&#8217;s a column there where you can attach it. And I said, okay, when you do that, then you really appreciate that you can have a gallery with that. So It took me a while to kind of get that because it&#8217;s a, it wasn&#8217;t a workflow that I wasn&#8217;t familiar with and I wouldn&#8217;t, wouldn&#8217;t have used. So what&#8217;s the dynamic mode conversion thingy? Undo?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I think it&#8217;s just a sort of small life improvement that you, when you undo, so you have a dynamic gallery, then you kind of make it detached to stay with the, with the wording here. And then when I go back and said I made a mistake, Then you only have to press undo once instead of 15 times, twice, or multiple times for every image. Now the entire gallery gets basically back to the state it was in.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Pretty neat. Yes, I like it. So there were quite a few changes to the background image and to the global styles, but they are also minor. Yeah, there&#8217;s one thing that theme builders that use theme.json probably need to know about that is that the level block level preset class specificity has been changed through the :where command. So that is certainly something when you— that you might come across when you have a custom theme and you have some custom CSS and try to work with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, I think we had this kind of big thing last year when things got changed with the :where selector, and then you had to redo stuff because things were not applying or Again, applying to things depending on what it was. So yeah, that&#8217;s something we have to look out for to see. Because every time core is like changing something like this, you just need to double check that your stuff still works. Because I think, I wouldn&#8217;t say a lot, but I know it from the Greyd WP theme. We do use quite some extra styles to make the theme happen and have the blocks styled the way we would, we imagine it in our theme. And yeah, it&#8217;s just like revisiting your theme again to make sure things still work. To-do for the theme developers, definitely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Right, right. Absolutely. And that is actually in 7.1. This was patched back to core during the release. Yeah. So that&#8217;s why I&#8217;m pointing that out. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Experiments</h3>\n\n\n\n<p class=\"wp-block-paragraph\">And then the last thing I think is in the experiment section that the inheritance UI that we talked about quite a bit in this show is actually now only visible through the Gutenberg experiment screen. Yeah. So you need to switch it on to actually test it for yourself.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Good to know because, and I would&#8217;ve been very confused again if I just went, oh, let&#8217;s update to Gutenberg plugin. Why does this not show? Okay, let&#8217;s do a deep dive once again.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Right. Yeah. So now you know.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> But that&#8217;s why it&#8217;s so helpful to have all these What&#8217;s New in Gutenberg blog posts, I have to say. Because they highlight everything and then you can go back and just like yesterday I was searching for something, why did this thing change? And that&#8217;s how I got back into like, okay, this was the change. Then obviously whatever is in the pull request is quite a kind of technical. And if you do not have technical people asking you the question, you kind of need to translate, okay, this happened because of that. And this is the reason for it because you just cannot send them a link to the pull request and here is it. And then they go back, what is it about?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So yeah, well, it&#8217;s always— There&#8217;s one step that I use now is I share that URL with Claude and say, explain it to me like an 8-year-old or something like that. And then it kind of tells me what&#8217;s this about. I mean, and that&#8217;s when I know.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> It does work. But if the person is already with you and like, Jessica, what is—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: No, no, of course.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> What is going on here? Then you&#8217;re like, Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: That&#8217;s how I get smarter.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, it&#8217;s definitely, it, it helps me also. So I&#8217;m not just saying that this is, I did not use it in that case. I probably should have done this yesterday, but I like to search for things and find, figure things out, why, why things change and how they work. AI is like the shortcut to it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And I do use it sometimes. Yeah, definitely. And, but I still like to. tinker and figure things out myself because that&#8217;s what I enjoy.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, that&#8217;s one thing. That&#8217;s also when you learn, you know, if an AI kind of gets you something back, you have it for the moment, but it&#8217;s harder to retain that information for a longer period of time. You know, that&#8217;s how our brains work.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: That&#8217;s true.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. If we, we need the challenges to overcome to actually learn something. Yeah. All right. That was our fast go through 23.7. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Gutenberg 23.8</h3>\n\n\n\n<p class=\"wp-block-paragraph\">23.8 came out just this week. This week was the whole release week. Yeah. With, or last week with 7.0.4, 7.1, Gutenberg released 23.8.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jessica Lyschik: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: It&#8217;s kind of a lot of information to disseminate. And I have found that the Gutenberg releases have more PRs in them than previous. Last year or something like that. So there are a lot of, a lot more people or the same people pushing more PRs into the release. It&#8217;s really interesting to go through all the changelogs and all that. So we might miss something. So in terms of collaboration, the notes feature got a new method, that is the email— that it emails users now that are mentioned in a note. So you have now— you can now mention people that are on the blog with an @ sign. And then once you save the note, it emails those users that they were mentioned and that there was a note for them to do or to look at, which is quite nice because not everybody goes to every site every time.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> So, yeah, or this specific blog post, because if you do not, are not working on that because you don&#8217;t know that your attention is needed there, then this is definitely a way that you can actually get to know that people are waiting for a reply for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Of you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. I&#8217;m still looking for that place where I can see all my comments on posts in one swoosh and not have to go into the post. I don&#8217;t know if it&#8217;s coming, but it&#8217;s definitely plugin territory. So if you want to have a good plugin, that&#8217;s definitely a feature request for me. Let me know if you start it out. Do you want to do the next one?</p>\n\n\n\n<h3 class=\"wp-block-heading\">Enhancements</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Visual revisions, add shareable URLs. Ooh, this is interesting. Yeah, I have been quite a fan of the visual revisions so far. I mean, I have not used them too much yet, but—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Me too.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> It&#8217;s like, it&#8217;s just a whole new experience. And now you can actually get a shareable URL of that. So you can basically say, hey, here&#8217;s the URL to that specific change set. Here&#8217;s what I&#8217;m having trouble with, dealing with, whatever it is. This is actually kind of cool.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> That&#8217;s the one thing. And what I also can see is that you say, okay, this was the version before and this is it now. Yeah. So people say, what changed? Or wasn&#8217;t it better before kind of thing? Yeah. And then you can actually see it side by side or you say, okay, I have 2 versions of it. This is one version, this is the other one version. Which do you like? Yeah, kind of. So you don&#8217;t have to do the staging site just for little changes. You can actually put it on site, but you always have a main version there. So a live version. So yeah, be careful with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And that&#8217;s why you have revisions. So whenever you do something wrong, you can go back if you have revisions. So it&#8217;s that custom post types sometimes do not have revisions.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And you have to turn that on when you register the post type. I think most plugins let you do that. And if you do not do it and you have no revisions.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And it&#8217;s a bad thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. I also learned that some of the shared hosting providers actually turn revisions off or just limit them to 3 revisions or 10 revisions. And then, yeah, I would be doomed because some of my posts have 100 revisions. For especially the source of truth. Yeah. So. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah. You need to be aware of that sometimes. So there are different ways, not different ways. The way to limit the post revisions is through the, a constant in the wp-config file.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And yeah, it&#8217;s true that shared hosts, they limit it probably because they do not want the data, the databases to blow up because every time a new revision is added, it is basically like a post in a database. You just do not see it, but it&#8217;s connected to the post. I think it&#8217;s, the post type should be revision or something. It&#8217;s not post. Yeah, it&#8217;s post type revision. So that&#8217;s why it&#8217;s filterable. And yeah, so yeah, if you have 100 revisions, you have like this blog post 100 times essentially in your database. If you just have a few blog posts, no one cares. But if you have a very huge site with a lot of posts and a lot of pages and maybe even WooCommerce running, for example, then your database goes whoosh and everything is huge. And yeah, so there is a good reason for it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Oh yeah, absolutely. Yeah, yeah, yeah. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And the next thing we actually talked about it, that the rename of the edit action to detach for page list and table of contents, that&#8217;s now in 23.8. So you can see that in your interface. Oh, and here it is also the opt-out for block style state controls. We talked about the opting out of the responsive styles. And in 23.8, you also find an opt-out method from the state controls, which is, I think, going through the same— no, it says block states enabled opt-out. So there is another variable filter for that on the block editor settings.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, it basically follows the other one for the responsive styles. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. So it&#8217;s responsive styles editing enabled is the variable. And the other one is block states enabled. And setting that to false. What else is next?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Oh, more revisions. Add a code diff view inside the editor. Ooh, is it what it is? I think. Yeah, it is. It is actually what I think it is. So it&#8217;s kind of bringing back the old view that we had for revisions where it was just like this, like you know it from, if you&#8217;re a developer, you know how diffs look like. And now that we have the new visual revisions, now we can actually go back to that specific thing and maybe see if, I don&#8217;t know, any HTML tags have changed or any settings in there have changed, which is true that these are not as visible. With the visual revisions. So the visual revisions are great for like scanning the content and making sure like the content is as you wish or wanna go back or whatever. But yeah, I think this is actually a very good change to bring this kind of view back. Because if you need to go a bit more technical and see, okay, have block settings changed, for example, it&#8217;s not easy to see on the, on the visual.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Right. And they have tried to make this also available in this, in the inspector controls in the sidebar, if there are any block attributes changed. But I think it&#8217;s helpful to see it in a, in a code edit view better than just to name the block attribute how that changed. So it&#8217;s, yeah, I think it&#8217;s a good, good feature set to bring back. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Oh, and there was, I didn&#8217;t highlight that, but it&#8217;s, we talked about Presets management in 23.7. Now the— in 23.8, there&#8217;s also that font size presets and the shadow presets actually use this new preset management layer. So that&#8217;s actually already implemented and is now— it&#8217;s a code change in the background, but it&#8217;s actually streamlining the whole thing and makes it available for extensibility later on. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, that was 23.8, and we are also almost coming up on the end of the show. It&#8217;s not the end of the changelog. This changelog was also really huge.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: The lists are endless for both 23.7 and 23.8. It&#8217;s probably also because of AI, I guess, has accelerated it quite a bit to get the pull requests done and finding things, fixing things, doing things. So it&#8217;s a lot. There&#8217;s a lot to go through, definitely.</p>\n\n\n\n<h3 class=\"wp-block-heading\"><strong>What’s in Active Development or Discussed</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah, definitely. Yeah. So I have 2 things that are for active development and what&#8217;s discussed, and they&#8217;re both for 7.2. So Ella van Durpe has a tracking issue of block editor paper cuts, which means to, to list all the small annoyances that she could find that people have issues with and put them all in a list to be fixed. </p>\n\n\n\n<p class=\"wp-block-paragraph\">So it might be big tasks like rethinking the appenders and inserters, how they actually behave, or writing flow, writing flow improvements, or even longstanding bugs that have been passing Excel to in the block editor, or selection quirks with Safari, or multi-block selections on iOS, or yeah, these kind of things. She found 48 issues to be fixed. If you have one that is not listed, feel free to put it in the issue and have it also on the list. She already fixed 9 items when I was putting this together. There might be even more now. So she definitely needs help with testing and commenting on those issues. So yeah, it&#8217;s a nice little literature for you if you have been working with the block editor for years and years and years, what you see that comes up. So I will share, of course, the link in the show notes. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And then, Anne McCarthy for 7.1 had actually said, the release lead, that it would be great to have, because it&#8217;s hard to follow which feature comes in and what are the plans and all that. And she needs it for roadmap. And other people like Jessica and I, we need to kind of see what&#8217;s going up, ongoing issues or features that are in the works so we can test them and we can kind of figure out things. So she asked the teams that are working on features to actually put tracking issues together for the certain versions. </p>\n\n\n\n<p class=\"wp-block-paragraph\">So quite a few actually have already put in the tracking issues for 7.2, and I will share the search link. I haven&#8217;t gone through them yet to study them, but there&#8217;s an iteration issue for the notes features, for the dynamic galleries, for the media editor modal, for the pattern editing. Also how to extend the site editor. I&#8217;m really very happy to see that. Then of course for the responsive styles. And so all the ongoing things. Or Maggie&#8217;s custom states for blocks tracking issue. So you can follow along on the things because then they have sub-issues and you see which ones have already been merged and which ones are already in the works and are in review or these kinds of things. So it&#8217;s really good to follow along. It&#8217;s not for everybody because GitHub is not for everybody, but it&#8217;s definitely something to go there. And if you want, I haven&#8217;t mentioned it yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dear listeners, this will be the last episode on the Gutenberg changelog until December. There will be a break. And I&#8217;m very grateful for the break because Automattic, after a 5-year anniversary, allows you to go on sabbatical for 3 months. And I&#8217;m starting mine next week. So this is the last episode of the Gutenberg changelog. </p>\n\n\n\n<p class=\"wp-block-paragraph\">There will be a Gutenberg Weekend Edition, certainly not every weekend, but Justin Tadlock is going to take that on and he will do it either biweekly or monthly. It&#8217;s not quite sure yet because he has other duties, but he&#8217;s definitely looking forward to writing those weekend editions. </p>\n\n\n\n<p class=\"wp-block-paragraph\">So, dear listeners, take the link to the tracking issue as your homework for the next 3 months on my break. And of course, study every Gutenberg release in the meantime. I think I checked it out. So this was 23.8. And in November, when I get back, we will already beony 24.4 Gutenberg releases. So there are quite a few releases in there. 6 exactly. I will not catch up on those, but I will catch up on the 7.1— 7.2 again, 7.2 release, because it&#8217;s only about 10 days away when I get back. So that&#8217;s definitely the first episode that we are going to do in December. Yeah. Anything that you wanna talk about here that we haven&#8217;t covered yet?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: No, I think, I think you made a very good thing. I didn&#8217;t know about editor paper cuts PR. Well, my homework is getting longer and longer for the weekend. Definitely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I mean, it will be sad to not have a Gutenberg changelog for the next couple weeks, but I guess it&#8217;s well deserved that you go on a sabbatical.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Well, thank you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> And I feel very honored that I have been on the last show for now. And yeah, let&#8217;s see. If we can catch up.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yes, absolutely. Absolutely. Just to make sure it&#8217;s not a couple of weeks, it&#8217;s 12 weeks. So a long couple weeks, 6 couple of weeks. So, and yeah, I will share how you can reach Jessica on all the interwebs with the show notes so she doesn&#8217;t have to repeat it here. But I want to also point out she&#8217;s sometimes on the Greyd podcast with the Greyd conversations. And there are quite a few interesting episodes there. I&#8217;ll send, put also the link into the— is there one that you wanna point out about block editor or block themes or so that you had?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Oh, I have not been on the show in quite a while.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> I have been very busy in the background. So, but we do have very interesting shows. I think the latest ones were with Katie Keith and Matt Cromwell about products and, and stuff. I think there was one more person on there. I know this is horribly bad for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: No, no worries. No, I put you on the spot there, so don&#8217;t worry about it. But I mean, I can— I was trying to look it up. It&#8217;s about product companies and—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yeah, it&#8217;s about a product business. And maybe just— I think we redo that and I would just like to correctly say it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. It&#8217;s How Can Product Companies Grow in WordPress Space Right Now? And it was with Katie Keith, as you said, and Aurelio Volle. He&#8217;s the founder.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Oh, Aurelio. Yeah. WP Umbrella.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> WP Umbrella and Matt Crumbrall, founder of Roots and Fruits. Roots and Fruits.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: And they are, they&#8217;re talking about product companies and how they can be successful in the WordPress space, especially now. With or without AI and with the abundance of plugins now. So it&#8217;s gonna be interesting to see how you can build a business there. All right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik:</em> Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> As always, the show notes will be published on <a href=\"http://gutenberg-times.com/podcast\">gutenberg-times.com/podcast</a>. This is episode 134. And if you have questions, suggestions that can wait until December, send me an email to <a href=\"mailto:changelog@gutenberg-times.com\">changelog@gutenberg-times.com</a>. That&#8217;s <a href=\"mailto:changelog@gutenberg-times.com\">changelog@gutenberg-times.com</a>. Caveat there, I&#8217;m not gonna pick up email during sabbatical on the Gutenbergtimes.com or on Automattic and very, very sporadically on my Gmail account. But yeah, send me things and you will see what happens. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks, Jessica, for being with me on the show. Thank you all for listening. And this is goodbye.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Jessica Lyschik</em>: Bye.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 23 Aug 2026 08:46:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:120:\"Gutenberg Times: Icons, Tabs, and responsive styles: the community gets to work on WordPress 7.1 — Weekend Edition 374\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46888\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"https://gutenbergtimes.com/icons-tabs-and-responsive-styles-the-community-gets-to-work-on-wordpress-7-1-weekend-edition-374/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:21976:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">It has been another evenful week for sure! WordCamp US came to an end and WordPress 7.1 was released. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your WordPress profile now has a shortcut w.org/@[yourusername]. If you want to check out mine <a href=\"https://w.org/@bph\">w.org/@bph</a> (don&#8217;t forget the @ sign) . Mullenweg mentioned in his closing fire side chat that this could actually work without the redirect in the future. Now that would be cool, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Another cool and rather weird thing Mullenweg mentioned are Piplets. One self-contained PHP-file for your notes, no database, no hosting needed, for tinkerers who live in the Terminal window. If that&#8217;s you, grab the file from the <a href=\"https://github.com/wordpress/piplets\">GitHub repo</a> and try it out. (64-bit PHP 8.1 or newer is required.) There will be <img alt=\"🐲\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f432.png\" style=\"height: 1em;\" />. To be honest, it&#8217;s not my idea of simplicity, though. I am firm in the Obsidian camp. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Apropo <strong>WordCamp US</strong>: All Talks are already available in the <strong><a href=\"https://www.youtube.com/playlist?list=PLLoEEVBDa-ik\">Playlist on YouTube </a></strong> for your on-demand viewing pleasure. Or you organize a viewing party with your local WordPress Meetup. Just a thought. <img alt=\"😉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f609.png\" style=\"height: 1em;\" />  </p>\n\n\n\n<p class=\"wp-block-paragraph\">Have a great weekend! </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\"><div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">WordPress 7.1 is out!<img alt=\"🎉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f389.png\" style=\"height: 1em;\" /></a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#gutenberg-23-8-released\">Gutenberg 23.8 released</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li></ul></nav></div>\n</div></div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nicholas Garofalo&#8217;</strong>s recap of <a href=\"https://wordpress.org/news/2026/08/wcus-2026-recap/\"><strong>WordCamp US 2026 in Phoenix</strong></a> covers four days, 1,100 attendees, 111°F, and a Contributor Day where 425 people formed 26 teams around goals they could finish by evening. You&#8217;ll get the Showcase Day migrations of The Ankler and Daily Kos, keynotes from Bo English-Wiczling and Loyal Pyczynski on judgment in the age of AI, and Matt Mullenweg&#8217;s closing pitch for simplicity, including Piplets, a single self-modifying PHP file with no database.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">WordPress 7.1 is out!<img alt=\"🎉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f389.png\" style=\"height: 1em;\" /> </h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><a href=\"https://wordpress.org/news/2026/08/mary-lou/\">WordPress 7.1 “Mary Lou”</a>,</strong> names after Mary Lou Williams an American jazz pianist, arranger, and composer who recorded hundreds of records. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The release video is fabulous. <strong><a href=\"https://www.youtube.com/watch?v=dO751c8jkn0\">WordPress 7.1 Highlights Video</a></strong></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://wordpress.org/download/releases/7-1/\"><strong>WordPress 7.1 micro site</strong></a> with the featurettes, tiny videos highlighting the main features is definitely a beauty! What a pleasure to read and experience the most important updates!</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://wordpress.org/download/releases/7-1/\"><img alt=\"Screenshot of the WordPress 7.1 release site. \" class=\"wp-image-46926\" height=\"587\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-08-22-at-12.44.43.png?resize=1024%2C587&#038;ssl=1\" style=\"border-width: 1px;\" width=\"1024\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Release lead <strong>Anne McCarthy</strong> kept a <a href=\"https://nomad.blog/2026/08/21/wordpress-7-1-release-lead-decision-log/\"><strong>WordPress 7.1 release lead decision log</strong></a>, and it reads like the other half of the release notes. You&#8217;ll see why real-time collaboration, React 19, inherited-style display, and the Classic block removal were punted, why responsive styling got an opt-out rather than a pause, and how she decided to publish the announcement when auto-updates had already reached 300K sites while Matt Mullenweg was on the WordCamp US stage. Each entry links to the thread where the call was made. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the WordPress Developer Blog, <strong>Justin Tadlock</strong> goes <a href=\"https://developer.wordpress.org/news/2026/08/hands-on-with-the-wordpress-7-1-icon-registration-api/\"><strong>hands-on with the WordPress 7.1 Icon Registration API</strong></a> and builds a restaurant icon collection from scratch. You&#8217;ll register a collection with wp_register_icon_collection(), add 13 food icons via wp_register_icon(), and see why he prefers a string-backed PHP enum over arrays for naming them. He also lists what 7.1 still strips: only svg, path, and polygon elements survive, and stroke attributes are removed, so stick with fill-based icons for now.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">If Justin Tadlock&#8217;s walkthrough is more than you need right now, <strong>Ryan Welcher</strong> covers the same API in five minutes in his video on <a href=\"https://www.youtube.com/watch?v=Hx8-nHQeoLc\"><strong>custom icons in WordPress 7.1</strong></a>. He registers a collection and a single icon in PHP, loads a folder of SVGs from disk the way core does, and renders one in a template with wp_get_icon(). The gotchas matter most: the sanitizer strips <code>fill=\"currentColor\"</code>, and a function_exists() check keeps 7.0 sites from fatal-erroring.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The block editor&#8217;s single biggest frustration is finally addressed, <strong>Jackson</strong> argues in his tour of <strong><a href=\"https://www.youtube.com/watch?v=x_2MC0i3FMA\">the new features in WordPress 7.1</a>, </strong>and he means responsive block styles. Over twenty minutes you&#8217;ll see thirteen features in action: hover and active states for buttons and navigation, the Tabs block, the Icon block with Aki Hamano&#8217;s custom icon plugin, the Playlist block&#8217;s waveform, the in-browser media editor, and a Query Loop checkbox that stops your related posts from recommending the post you&#8217;re reading. </p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"gutenberg-23-8-released\">Gutenberg 23.8 released</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Selecting all blocks in a 1,000-paragraph post used to take 16.8 seconds; in Gutenberg 23.8 it takes 0.4. Release lead <strong>Jon Surrell&#8217;</strong>s post on <strong><a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">what&#8217;s new in Gutenberg 23.8</a> </strong>covers that List View speed-up alongside the shareable revision URLs and in-editor code diff, and email notifications when someone @-mentions you in a note. You also get a real default block on the empty canvas, Audio-to-Playlist transforms, and, for developers, inner block templates declared in registerBlockType() and public Calendar components in @wordpress/ui.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\"><img alt=\"\" class=\"wp-image-46953\" height=\"697\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/gb-23-8-shareable-revisions.jpg?resize=1024%2C697&#038;ssl=1\" width=\"1024\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">For the <strong>Gutenberg Changelog 134</strong> episode, Jessica Lyschik, senior developer at <em>Greyd,</em>  joined me to discuss Gutenberg versions 23.7 and 23.8. We also chatted about WordPress 7.1 and what comes next for the December release of WordPress 7.2  As always the episode with its show notes will come to your favorite podcast app over the weekend. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-972a13da wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-134-gutenberg-23-7-23-8-wordpress-7-1/\">Gutenberg Changelog #134 – Gutenberg 23.7, 23.8, WordPress 7.1 and more</a> with special guest <strong>Jessica Lyschik</strong>, Greyd. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46955\" height=\"367\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-08-22-at-17.29.52.png?resize=1279%2C367&#038;ssl=1\" width=\"1279\" /></figure>\n\n\n\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n</div>\n\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you build with the Ollie block theme, <strong>Gina Lucia</strong>&#8216;s <a href=\"https://olliewp.com/wordpress-7-1-walkthrough/\"><strong>WordPress 7.1 walkthrough</strong></a> shows where the new core features meet Ollie&#8217;s tools. Responsive styling now lives in core, so Ollie Pro&#8217;s Responsive Controls shift to handling column and grid stacking, while its Class Manager picks up where the new hover and focus states for Button and Navigation Link leave off. You&#8217;ll also see how the Tabs and Playlist blocks, gradient-over-image backgrounds, and the persistent admin bar fit your Ollie site.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Merging cells is still missing from the core Table block, and <strong>Aki Hamano</strong>&#8216;s <a href=\"https://wordpress.org/plugins/flexible-table-block/\"><strong>Flexible Table Block</strong></a> plugin fills that gap on 40,000+ sites. Version 3.9.0 adds WordPress 7.1 support and announces row and column selection to screen readers. You can merge and split cells, style the table, cells, and caption separately, and set your own breakpoint for horizontal scrolling or stacking cells on mobile. It also converts to and from the core Table block with rowspan and colspan intact. <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> is a major contributor to the Gutenberg project from Japan and co-tech lead for WordPress 7.1.  There is a lot of crediblity attached to this plugin.<em>  And hat tip to Daniel Kossmann, editor of the Portuguese WordPress newsletter <a href=\"https://www.painelwp.com.br/newsletter-sobre-wordpress-edicao-374/\">PainelWP 374</a></em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The new Tabs block in WordPress 7.1 swaps panels abruptly, since the Interactivity API toggles the hidden attribute. <strong>Elliott Richmond</strong>&#8216;s <strong><a href=\"https://wordpress.org/plugins/elliott-richmond-tabs-animation/\">Tabs Animation</a> </strong>plugin softens that with a fade or a slide from any of four directions, plus a duration up to 3000ms and five easing options under <code>Settings → Tabs Animation</code>. It&#8217;s one small inline stylesheet with no JavaScript and no theme changes, and it switches itself off for visitors who prefer reduced motion. One setting applies site-wide for now.</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-3155bc6e18c1b55e wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">On his livestream, Ryan Welcher got back on <a href=\"https://www.youtube.com/watch?v=K6oxl98M0Pg\"><strong>his son&#8217;s hockey team site with WordPress Studio Code</strong></a>, this time handing over the single post template. The first pass got close, then navigation broke, the header came in too tall, and the content width wouldn&#8217;t match the homepage, so you&#8217;ll watch him go several rounds with Annotate, clicking and describing what&#8217;s wrong. Two hours used 2.5 percent of his monthly limit. He also covers the 7.1 iframe change and a twenty-minute custom fields tangent. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.wordpress.com/studio/\"><strong>WordPress Studio the agentic local development app</strong></a> is still in beta. Help make it perfect! </p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-eeeaba396107aec3 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--3\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-fa195b41a53e84dc wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--4\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 22 Aug 2026 16:43:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"Open Channels FM: AI Insights, Open Source Guidance and Commentaries.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558769\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://openchannels.fm/signal-ai-insights-open-source-guidance-and-commentaries/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:109:\"A focus on guiding new contributors in open source, discussing AI\'s impact, and adding insightful commentary.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 21 Aug 2026 09:39:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"Matt: Homework from WordCamp\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154259\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://ma.tt/2026/08/homework-from-wordcamp/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3973:\"<p class=\"wp-block-paragraph\">A few times during the <a href=\"https://us.wordcamp.org/2026/\">WordCamp US</a> keynote, I asked for a show of hands and got mostly blank stares back, especially on the AI questions. That&#8217;s not a criticism — it&#8217;s a reading list. If the future is going to be built on this stuff, the WordPress community should be fluent in it. Here&#8217;s the homework.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How models are actually trained</h2>\n\n\n\n<p class=\"wp-block-paragraph\">When I asked who knew about the reinforcement learning models go through, Robert looked out and said &#8220;I see no yeses.&#8221; Base models are trained to predict the next word across huge amounts of text; the friendly, helpful behavior comes after, in post-training, where human/AI feedback reinforces some responses over others. If you use these tools every day, understanding that pipeline changes how you prompt them and what you expect from them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Start with Hugging Face&#8217;s <a href=\"https://huggingface.co/blog/rlhf\">Illustrating RLHF</a>, a visual explainer. Chip Huyen&#8217;s <a href=\"https://huyenchip.com/2023/05/02/rlhf.html\">RLHF deep dive</a> is the best longer read, and Anthropic&#8217;s <a href=\"https://arxiv.org/abs/2212.08073\">Constitutional AI paper</a> shows where post-training went next. If you only have time for one thing, watch Andrej Karpathy&#8217;s <a href=\"https://www.youtube.com/watch?v=7xTGNNLPyMI\">Deep Dive into LLMs</a> — pretraining, fine-tuning, reinforcement learning, and why models behave the way they do, all in one sitting.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Uncensored models</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Almost nobody had tried an <a href=\"https://huggingface.co/OBLITERATUS/Qwen3.8-27B-OBLITERATED\">OBLITERATED</a> model. Since refusal behavior is added in post-training, researchers found it can also be removed — it turns out to be, roughly, a single direction inside the model that you can subtract out. Maxime Labonne&#8217;s <a href=\"https://huggingface.co/blog/mlabonne/abliteration\">Uncensor any LLM with abliteration</a> explains the technique, and the paper behind it, <a href=\"https://arxiv.org/abs/2406.11717\">Refusal in Language Models Is Mediated by a Single Direction</a>, is short and genuinely fascinating. Whatever you think of the applications, it&#8217;s worth understanding that open weights mean the community can modify these models, the same way the GPL means you can modify WordPress.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The open-weight wave</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Only a few hands went up for Qwen 3.8. The open-weight models coming out of Chinese labs — <a href=\"https://huggingface.co/Qwen\">Qwen</a>, <a href=\"https://huggingface.co/deepseek-ai\">DeepSeek</a>, <a href=\"https://huggingface.co/moonshotai\">Kimi</a>, <a href=\"https://huggingface.co/zai-org\">GLM</a> — are at or near the frontier at a fraction of the cost, and the smaller ones run on a laptop. I demoed one from this MacBook on stage. Token costs have dropped about 20x, and that curve isn&#8217;t slowing down.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The easiest way to feel this for yourself is to run one locally tonight: install <a href=\"https://ollama.com\">Ollama</a> or <a href=\"https://lmstudio.ai\">LM Studio</a>, pull a small Qwen model, and talk to an intelligence that lives entirely on your own machine, no cloud required. For a community built on the four freedoms, that should feel familiar — and exciting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Read one, watch one, run one. Then bring what you learned to your next meetup.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It is really important to me that WordPress community members ride this AI wave.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Errata: I said Automattic has 32 or 33 data centers; <a href=\"https://automattic.com/automattic-data-centers/\">the actual number is 29</a>, all co-located.<br /></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 20 Aug 2026 23:39:17 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"Open Channels FM: AI for the Rest of Us\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2559615\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"https://openchannels.fm/ai-for-the-rest-of-us/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:156:\"An update on Open Channels News, new fall series (including \"AI for the Rest of Us\"), and a preview of the Open Channels FM 5.0 release coming in September.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 20 Aug 2026 10:54:28 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"WordPress.org blog: AI Creates Opportunity While Artists Ship at WordCamp US 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21264\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"https://wordpress.org/news/2026/08/wcus-2026-recap/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:54284:\"<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-21551\" height=\"730\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00367.png?resize=1943%2C730&#038;ssl=1\" width=\"1943\" /></figure>\n\n\n\n<div class=\"wp-block-columns is-not-stacked-on-mobile is-layout-flex wp-container-core-columns-is-layout-3eb8a5ac wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-medium wp-container-content-73b9422f\"><img alt=\"\" class=\"wp-image-21418\" height=\"300\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/route-66-traveller-boy-right.png?resize=242%2C300&#038;ssl=1\" width=\"242\" /></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-container-content-08efa294 wp-block-paragraph\">WordCamp US (WCUS) 2026 just wrapped up after 4 days at the Phoenix Convention Center in Phoenix, Arizona. Over 1,100 people from around the world registered to attend, and thousands more watched online through livestreams. Contributor Day and Showcase Day opened the week before two main conference days, featuring over 50 speaker-led sessions across 4 tracks, including multiple workshops.</p>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">The temperature reached 111°F (44°C), but golf carts ferried travelers between the Sheraton Phoenix Downtown and the convention center. Inside, attendees moved between session rooms, the Sponsor Hall, and the Happiness Bar.</p>\n\n\n\n<div class=\"wp-block-columns is-not-stacked-on-mobile is-layout-flex wp-container-core-columns-is-layout-3eb8a5ac wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<blockquote class=\"wp-block-quote wp-container-content-08efa294 is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">It&#8217;s hot, but it&#8217;s not Florida hot.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8211; Loyal Pyczynski</em></p>\n</blockquote>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-medium wp-container-content-73b9422f\" style=\"margin-top: 0; margin-bottom: 0;\"><img alt=\"\" class=\"wp-image-21413\" height=\"300\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/route-66-traveller.png?resize=285%2C300&#038;ssl=1\" width=\"285\" /></figure>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Sessions covered artificial intelligence (AI), accessibility, publishing, business, site ownership, and the open web. Speakers in different rooms often found common ground, noting the importance of good judgment and trust-building in the age of AI.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped has-black-background-color has-background wp-block-gallery-1 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21473\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-1611.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21553\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/JQ300102.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21476\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-2244.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21474\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-2078.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21480\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260817_WCUS_EC_00786.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21472\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_EC_00467.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21550\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Copy-of-JQ300341.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21479\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260817_WCUS_EC_00431.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21475\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-2095.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<h2 class=\"wp-block-heading\">Real Artists Ship</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/real-artists-ship-contributor-day-at-wcus-2026/\">Contributor Day</a> followed the motto &#8220;Real artists ship,&#8221; and a new format to match. The 425 participants, including 29 first-time contributors, formed 26 teams around goals they could complete that day. Experienced contributors moved between groups and helped newer participants shape goals. Then, goal owners gave 30-second pitches, and contributors could move between teams when that work caught their interest.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-2 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21468\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-1152.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21470\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-1274.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21549\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/JQ301171.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21469\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-1266.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">By day’s end, contributors had closed tickets, opened and shipped pull requests, and reviewed themes for accessibility. One team created description-list blocks for glossaries and product details, and another added email settings, a test tool, and checks for account, password-reset, and recovery messages.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Other teams built a <a href=\"https://wordpress.org/photos/\">Photo Directory</a> importer and updated Notes in the WordPress dashboard and Multisite documentation. More work covered PHP, PHPUnit testing, and guidelines for AI work within the project. New contribution pathways became a course on <a href=\"https://learn.wordpress.org/\">Learn WordPress</a>, open to people who could not be in Phoenix.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Every team ended the day with a 30-second presentation of what it had made, tested, fixed, or moved closer to release.</p>\n\n\n\n<figure class=\"wp-block-image size-large wp-duotone-grayscale wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21524\" height=\"568\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/IMG_0246.png?resize=1024%2C568&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Showcase Day Put Real Sites First</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If Contributor Day was about shipping in a day, Monday’s Showcase Day was about what happens after the shipping. Sites have to keep working smoothly for the people who publish, maintain, and depend on them. The case studies came from public services, independent publishers, community platforms, training systems, and large content operations.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/speaker/manny-costa/\">Manny Costa</a> covered the first of those: civic websites where residents find services, apply for programs, read emergency information, and report problems. In that work, accessibility, governance, and editor workflows are part of the service rather than a final check box.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Two of the case studies were about publishers taking back ownership of their content. Both sites now appear in the WordPress Showcase.</p>\n\n\n\n<div class=\"wp-block-columns is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large is-style-default\"><img alt=\"\" class=\"wp-image-21499\" height=\"403\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/wordpress.org_showcase_the-ankler_WordPress-Showcase-Desktop.png?resize=1024%2C403&#038;ssl=1\" width=\"1024\" /><figcaption class=\"wp-element-caption\">See <a href=\"https://wordpress.org/showcase/the-ankler/\">The Ankler</a> in the WordPress Showcase</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/session/own-your-audience-how-the-ankler-escaped-substack-and-took-back-control/\">Nicola Catton’s session</a> described how The Ankler moved 15 newsletters to WordPress and took direct control of its content, subscriber data, revenue rules, and reader experience. Nicola detailed the massive migration, the thousands of rebuilt paywall boundaries, and the site&#8217;s brand-new block theme.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21500\" height=\"403\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/wordpress.org_showcase_daily-kos_WordPress-Showcase-Desktop.png?resize=1024%2C403&#038;ssl=1\" width=\"1024\" /><figcaption class=\"wp-element-caption\">See <a href=\"https://wordpress.org/showcase/daily-kos/\">Daily Kos</a> in the WordPress Showcase</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The Daily Kos migration was a similarly large-scale move. <a href=\"https://us.wordcamp.org/2026/session/when-the-platform-belongs-to-its-users-migrating-daily-kos-at-scale/\">Ben Greeley and Allison McHenry</a> centered their session on a community that writes as well as reads: 1.5 million posts, 88 million comments, and 2.7 million users, with a public beta that involved more than 500 community members.</p>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Other sessions dealt with the people who do the publishing once a site is live. In <a href=\"https://us.wordcamp.org/2026/session/agents-need-good-tools-too-designing-an-editorial-experience-for-humans-and-ai-alike/\">Aviral Mittal’s session</a>, an AI agent built a page from a Google Doc using patterns the team had already defined. <a href=\"https://us.wordcamp.org/2026/speaker/andrew-adam/\">Andrew Adam</a> described a library of about 100 written and video guides, with accessibility guidance included. Shared foundations covered repeat questions, while project-specific help and tips inside the editor handled the rest.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Human Judgment in the Loop</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Early on, Bo English-Wiczling had opened Showcase Day by addressing the gap between rapid AI adoption and trust. Her <a href=\"https://us.wordcamp.org/2026/session/keynote/\">keynote</a> covered the move in developer work toward setting intent and supplying context.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">AI doesn’t remove your work. It moves it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8211; Bo English-Wiczling</em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">A first draft can now arrive in seconds, but an almost-right block of code may still miss keyboard navigation, use the wrong theme styles, or bring an unsafe dependency into a project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The importance of good judgment is familiar to the WordPress community. Bo tied it to habits WordPress contributors already have: reading other people’s code, submitting small changes, reviewing pull requests, and accepting critique in the open.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-3 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Bo English-Wiczling speaking on stage\" class=\"wp-image-21484\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-2187.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Loyal Pyczynski speaking on stage\" class=\"wp-image-21485\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3168.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">The next morning, Loyal Pyczynski drew on his work at Disney and Meta for a keynote about tests, time, and creative confidence. His <a href=\"https://www.youtube.com/watch?v=7vE1fS1sLpQ\">talk</a> returned to a phrase from an Imagineering colleague.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">We need to make sure that we make better mistakes tomorrow. Success is an iterative endeavor, and time is our most precious resource.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8211; Loyal Pyczynski</em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Loyal described Disney teams that paired creative and technical leads early, then brought in experts for work another team could do better or faster. The goal was not to know everything but to know what the team should own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Design and publishing sessions drew similar conclusions as the keynotes. <a href=\"https://us.wordcamp.org/2026/speaker/michelle-hunt/\">Michelle Hunt</a> framed design systems as living feedback systems that need to preserve intent as production gets faster.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/speaker/k-adam-white/\">K Adam White</a>’s session centered on moving large stores of content into block patterns, with editors staying involved where automatic conversion still needed judgment. <a href=\"https://us.wordcamp.org/2026/session/abilities-api-for-humans/\">Nik McLaughlin’s Abilities API session</a> looked beyond AI integrations to the broader structure the API gives WordPress developers. <a href=\"https://us.wordcamp.org/2026/session/the-site-is-the-source-of-truth-block-themes-ai-and-agency-workflows/\">Brian Coords</a> made a related case through block themes: approved patterns, templates, and real content offer a starting point, and design tokens add guidance that a blank-page prompt cannot provide.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Machine translation got the same treatment. In a <a href=\"https://us.wordcamp.org/2026/session/lost-in-machine-translation-ai-wordpress-and-the-translations-nobody-saw-coming/\">multilingual WordPress multisite case study</a> of AI translation for technical content, native-speaking colleagues found output that was correct word by word and could still miss the intended meaning. Human review covered the gap between translating language and translating intent.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The judgment question even reached hiring. <a href=\"https://us.wordcamp.org/2026/session/the-making-of-a-wordpress-certification/\">The Making of a WordPress Certification</a> introduced a standards-based certification and covered how the credential was created, checked, governed, and delivered.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Trust Becomes a Product Practice</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Wednesday morning took the trust question outside the WordPress world. The day opened with a <a href=\"https://us.wordcamp.org/2026/session/keynote-2-2/\">fireside chat</a> between Amanda Ventura of Waymo and David Levine on what it takes for people to trust technology that moves through their streets.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-4 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Amanda Ventura speaking on stage\" class=\"wp-image-21528\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4116.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"View of WCUS stage with Amanda Ventura and David Levine\" class=\"wp-image-21554\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4111.jpg?resize=1024%2C1024&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">Ventura described trust as repeated work. Teams can publish safety data and listen before arriving in a new city, and they need a path for product teams to act on feedback. Her example came from accessibility testing. Screen-reader support helped blind and low-vision riders use the Waymo app, but it did not solve the physical problem of finding the right car. Feedback led to step-by-step directions and a horn control with a distinct musical tone that was easier to identify on busy city streets.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Other sessions applied that standard to WordPress sites. WordPress Core committer <a href=\"https://us.wordcamp.org/2026/speaker/jonathan-desrosiers/\">Jonathan Desrosiers</a> focused on supply-chain safety while <a href=\"https://www.youtube.com/watch?v=z5_hxy2ET8Y\">Robert Abela’s session</a> explored login security. AI tools can find security flaws faster than ever. That speed raises the need for careful checks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The rest of Wednesday’s schedule included sessions on security, accessibility, design, AI tools, and work for site owners.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://us.wordcamp.org/2026/session/is-your-wordpress-site-legally-ready-for-ai/\">Kathy Zant’s session</a> proposed an audit for AI use, covering plugins, themes, content pipelines, and client sites, and it named consent, data location, disclosure, and legal review as questions teams should settle before launch.</li>\n\n\n\n<li>Another <a href=\"https://us.wordcamp.org/2026/session/your-client-wants-ai-their-lawyer-just-said-no/\">case-based session</a> compared two responses to navigation problems: one client received an AI search tool, and another received a predictable interface that editors could control. The planned lesson was simple. AI can be the right choice without being the automatic choice.</li>\n\n\n\n<li><a href=\"https://us.wordcamp.org/2026/session/beyond-plugins-real-accessibility-for-wordpress-websites/\">Joseph LoPreste’s session</a> explored accessibility work no single plugin can complete: navigation, forms, headings, images, content, and interactive elements.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Learning With Your Laptop Open</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress beginner workshops ran throughout the event for first-time builders, with no hosting account or prior WordPress experience required. Participants made pages, posts, logos, and menus, and each person left with a WordPress site, a year of hosting, and a domain. These sessions laid groundwork to work with plugins, styles, and additional features. The beginner program, office hours, and Happiness Bar gave people several places to ask questions and get hands-on experience.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-5 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21487\" height=\"678\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3374.png?resize=1017%2C678&#038;ssl=1\" width=\"1017\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21488\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_01145.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21489\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00680.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21490\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260817_WCUS_EC_00319.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">More advanced technical workshops offered even experts the chance to hone their skills.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://us.wordcamp.org/2026/speaker/lukasz-wilczak-2/\">Łukasz Wilczak</a> focused on reusable WP-CLI commands. They handled bulk content changes, block and shortcode migrations, link cleanup, and safe batch processing.</li>\n\n\n\n<li><a href=\"https://us.wordcamp.org/2026/speaker/vedanshu-jain/\">Vedanshu Jain</a> designed a workshop around roles and review paths for AI-only teams. The planned outputs included a plugin stub, publishable content, or another real result.</li>\n\n\n\n<li><a href=\"https://us.wordcamp.org/2026/speaker/rob-ruiz/\">Rob Ruiz</a> built his workshop around WP Rig and automatic checks for preparing block-ready themes for the Theme Directory.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Like all WordCamps, these sessions gave attendees skills and tools to bring home to their own projects.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Simplicity Gets the Last Word</h2>\n\n\n\n<div class=\"wp-block-group has-black-background-color has-background is-layout-constrained wp-container-core-group-is-layout-9c97b5da wp-block-group-is-layout-constrained\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">The closing session started with city business. Michael Hammett, Phoenix&#8217;s first Chief Innovation Officer, read a proclamation from Mayor Kate Gallego declaring August 19 Phoenix WordPress Day, and then presented the signed document to WordPress Cofounder, Matt Mullenweg. The proclamation credited WordPress with supporting the small businesses, developers, designers, educators, and creators in the city&#8217;s growing digital and creative economy.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-6 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Michael Hammett reading the Phoenix WordPress Day proclamation\" class=\"wp-image-21515\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4434.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Michael Hammett presenting the WordPress Day proclamation to Matt Mullenweg\" class=\"wp-image-21514\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4458.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">What followed was a dynamic presentation and conversation between Mullenweg and <a href=\"https://us.wordcamp.org/2026/speaker/robert-jacobi/\">Robert Jacobi</a>, ending with a traditional Q&amp;A. Matt&#8217;s thesis was simple: Tech needs to be simpler.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">I want WordPress to be known for simplicity, not just complexity.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>&#8211; Matt Mullenweg</em></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">After a detour through why AI models now prefer simple, self-contained HTML files, the argument became tangible with WordPress Piplets, a 2007 idea built around a single self-modifying PHP file that stores its own data, with no database and no third-party packages. One file can hold up to 25 megabytes, about four million words, and load in about 50 milliseconds. For Mullenweg, it extends the experiments that took WordPress from MySQL to SQLite to <a href=\"https://wordpress.org/playground/\">Playground</a>, and he floated the idea of a WordPress.org directory where people could publish, fork, and remix.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Speaking of WordPress.org, it was announced that profile links are getting shorter, with w.org/username redirects like <a href=\"https://w.org/@matt\">w.org/@matt</a> already live, with full support just a few days away.</p>\n\n\n\n<div class=\"wp-block-columns are-vertically-aligned-center is-layout-flex wp-container-core-columns-is-layout-7387b849 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<figure class=\"wp-block-image size-large\" style=\"margin-top: 0; margin-right: 0; margin-bottom: 0; margin-left: 0;\"><a href=\"https://wordpress.org/download/releases/7-1/\"><img alt=\"\" class=\"wp-image-21520\" height=\"535\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/image-3.png?resize=1024%2C535&#038;ssl=1\" width=\"1024\" /></a></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Midway through, release leads were called up to press the button on the WordPress 7.1 release, and were awarded with applause as <a href=\"https://wordpress.org/download/releases/7-1/\">“Mary Lou”</a> received hundreds of thousands of downloads.</p>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">On contribution, Mullenweg expressed his desire to reward impact instead of pledges. The <a href=\"https://wordpress.org/five-for-the-future/\">Five for the Future</a> directory shows two million self-sponsored hours pledged each week from 150,000 contributors, and he questioned whether that reflects reality. The project already records what actually happened (commits, posts, tickets closed, WordCamps organized), and he wants recognition built on that record. He asked the same of the plugin directory, suggesting a focus on fewer better-working things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Audience questions covered AI licensing, data centers, and why open source communities compete more than they collaborate. On that last one, Mullenweg invited other open source leaders to speak at WordCamp, and encouraged working together. Copying good code between projects, he said, is the entire point of open source.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-4 is-cropped has-black-background-color has-background wp-block-gallery-7 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21513\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4485.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21516\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4575.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21517\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260819_WCUS_WL-4588.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">Jacobi closed by asking who was at their first WordCamp; he had met more first-timers here, he said, than in the past ten years. One of them found the event by asking an AI chatbot for the coolest thing happening in Phoenix, came to Contributor Day, and left with one of its awards.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Beyond the Session Rooms</h2>\n\n\n\n<p class=\"wp-block-paragraph\">So much happens outside the session rooms. At the WCUS <a href=\"https://us.wordcamp.org/2026/29-days-out-phoenix-in-august-is-actually-kind-of-perfect-heres-why/\">Happiness Bar</a>, volunteers sat with attendees and worked through plugin questions, CSS problems, ecommerce setup, and new-site questions. An AFK (Away From Keyboard) room offered a quiet place away from the crowds. In the Sponsor Hall, people painted Wapuus with a local Phoenix artist, watched screen-printing, and talked between product demonstrations.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-5 is-cropped has-black-background-color has-background wp-block-gallery-8 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-width: 20px; border-radius: 2px;\">\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21534\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3467.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21548\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Copy-of-JQ301331.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\"