ight=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21542\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3292.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21541\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00415.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21547\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260817_WCUS_EC_00779.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21546\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260817_WCUS_EC_00786-1.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21537\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3323.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21545\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00330.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21544\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00310.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21543\" height=\"1024\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00376.jpg?resize=683%2C1024&#038;ssl=1\" width=\"683\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21540\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260818_WCUS_EC_00344.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"\" class=\"wp-image-21535\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3456.jpg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">The Connect art installation used photographs from the <a href=\"https://wordpress.org/photos/\">WordPress Photo Directory</a>. Forty postcards paired images by contributors who may never have met. Color, composition, or subject linked each pair. Attendees could take several cards and a blank one, then add a connection of their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Lunch did something simpler. People changed tables, picked up open seats, and started conversations with one question: &#8220;What do you do with WordPress?&#8221;</p>\n\n\n\n<figure class=\"wp-block-image size-large wp-lightbox-container\"><img alt=\"Group photo of WCUS 2026 attendees\" class=\"wp-image-21493\" height=\"595\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/260816_WCUS_WL-3743.jpg?resize=1024%2C595&#038;ssl=1\" width=\"1024\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/organizers/\">Organizers</a> and volunteers kept four days of rooms, shuttles, meals, and livestreams moving. Thank you to them, and to the <a href=\"https://us.wordcamp.org/2026/speakers/\">speakers</a>, <a href=\"https://us.wordcamp.org/2026/sponsors/\">sponsors</a>, contributors, attendees in Phoenix, and everyone watching online.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What Comes Next</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you missed this year&#8217;s WordCamp US, you can find recordings of sessions on <a href=\"https://us.wordcamp.org/2026/schedule/\">us.WordCamp.org/2026/</a>. Be sure to sign up for email notifications, so you don&#8217;t miss out next year. Next stop, <a href=\"https://wordpress.org/state-of-the-word/\">State of the Word</a>, followed by <a href=\"https://asia.wordcamp.org/2027/\">WordCamp Asia 2027</a> in Penang, Malaysia, and <a href=\"https://europe.wordcamp.org/2027/\">WordCamp Europe 2027</a> in Málaga, Spain.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img alt=\"\" class=\"wp-image-21504\" height=\"230\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/wordpress.org_state-of-the-word_WordPress-Showcase-Desktop.png?resize=1024%2C230&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-dots\" />\n\n\n\n<p class=\"wp-block-paragraph\"><em>Photo credits: Jaron Quach, Emily Chan, Wini Lao, Kendra Stowe, and <br />Jennifer Swisher</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 20 Aug 2026 05:51:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Nicholas Garofalo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"WordPress.org blog: WordPress 7.1 “Mary Lou”\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21420\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"https://wordpress.org/news/2026/08/mary-lou/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:79536:\"<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-21456\" height=\"1337\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/release-edition-featured-image-7-1-scaled.webp?resize=2560%2C1337&#038;ssl=1\" width=\"2560\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Each WordPress release celebrates an artist who has made an indelible mark on the world of music. <a href=\"https://wordpress.org/download/releases/7-1/\">WordPress 7.1</a>, code-named “Mary Lou,” honors pioneering jazz pianist, arranger, and composer Mary Lou Williams.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A child prodigy who began playing publicly at six, her influence and work cut across nearly every major era of jazz, moving through swing, bebop, and sacred jazz. Through all of it, she kept reinventing her own sound. In the 1940s, she turned her Harlem apartment into a nightly workshop where Thelonious Monk, Dizzy Gillespie, and Bud Powell came to trade ideas and shape bebop itself. That combination of reinvention and collaboration inspired WordPress 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Let the range of <a href=\"https://www.youtube.com/channel/UCha4zVvYM9Tv8Hx0Q9lN_jQ\" rel=\"noopener\" target=\"_blank\">Mary Lou’s music</a> carry you through everything 7.1 offers.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Welcome to WordPress 7.1!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 is built around how you work: navigating the admin, controlling your designs, collaborating with others, and building what you want. The admin bar now follows you across the entire admin experience, putting the tools you need within reach, whether you&#8217;re writing a post or editing your site&#8217;s design. Built-in responsive styling, added to the current show/hide options for blocks, means you can ensure your site looks exactly how you want across screen sizes, without custom CSS. A new media editor keeps the familiar Crop button entry point, and brings freeform and aspect-ratio cropping, horizontal and vertical flipping, fine-grained and snap rotation, and metadata editing into one dedicated workflow. Leave Notes anywhere in your content—no longer limited to the block level. Rich text support and @mentions make it easier to collaborate with others as you write. Two new blocks, Playlist and Tabs, as well as a new API to register your own set of icons for the Icon block, give you even more flexibility to build what you want without additional plugins. These are just the highlights! Read on to see everything WordPress 7.1 has to offer.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/wordpress-7.1.zip\">Download WordPress 7.1</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s inside</h2>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a lot packed into WordPress 7.1 across new styling tools, updated media flows, added Notes functionality, and more. Some changes add new capabilities, while others refine existing tools and workflows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Here&#8217;s a closer look at what&#8217;s new in this release, starting with the release video:</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Apply responsive styles</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Style your content your way, on every screen.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 brings more responsive controls directly into the Site Editor. Style how a block looks at different screen sizes from Global Styles or in individual block settings, without custom CSS. You can also preview your changes at different viewport sizes as you work, making it straightforward to build layouts that adapt to the way people browse the web.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21424\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Apply-responsive-styles.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Admin bar, now in every editor</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Consistent navigation, from dashboard to editor.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The WordPress admin bar now stays with you as you move across all editors, so you always know where you are and have easy access to familiar tools. The admin bar also features some small visual updates to more fully polish the experience. </p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21428\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Admin-bar-now-in-every-editor-1024x632.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">A new way to crop</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>One dedicated workflow for editing your images.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A new media editor modal replaces the previous inline cropping tool, bringing together freeform and aspect-ratio cropping, horizontal and vertical flipping, precise rotation control, and metadata editing together in one place. The familiar Crop button still gets you there.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21430\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/A-new-way-to-crop.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Inline notes with mentions and rich text</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>More ways to leave feedback.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Notes now support rich text and mentions, making it easier to leave clear feedback and loop in the right people. Format your Notes with bold, italic, and code, add links, or type <code>@</code> to mention a collaborator and notify them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can also leave a note on a specific piece of text instead of just an entire block, keep multiple conversations going on the same block, and collapse longer notes to keep the margin tidy. It&#8217;s built for the back-and-forth that happens when people review content together.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21434\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Inline-notes-with-mentions-and-rich-text.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Improved media handling</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Faster, more flexible image processing.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Image compression, resizing, and thumbnail generation now happen in the browser, reducing server load and producing smaller files — without hitting PHP memory limits or upload timeouts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Media handling in 7.1 also includes native support for AVIF, HEIC, and HDR gain maps, adding native support for the image formats modern cameras and phones already produce.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21437\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/More-image-formats-with-faster-uploads.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">Enhanced details and new blocks</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 also adds two new blocks, along with more ways to customize how content looks and behaves.</p>\n\n\n\n<h4 class=\"wp-block-heading\">Create playlists</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Bring multiple audio tracks together in one playlist, with an optional waveform that gives listeners a visual sense of each track as it plays.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21439\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Create-playlists.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Customize responsive breakpoints</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Block themes can now define their own mobile and tablet breakpoints in theme.json, overriding the defaults for responsive styles and block visibility.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21441\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Customize-responsive-breakpoints.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Organize with tabs</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Organize content into tabbed panels instead of showing everything at once—a cleaner way to present related information without crowding your content.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-full\"><img alt=\"\" class=\"wp-image-21443\" height=\"1581\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Organize-with-tabs-scaled.webp?resize=2560%2C1581&#038;ssl=1\" width=\"2560\" /></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Add custom icons</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Developers can extend WordPress&#8217;s icon library with their own collections, making custom icons available throughout the editor alongside the built-in library.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21444\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Add-custom-icons.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h4 class=\"wp-block-heading\">Set interactive styles</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Give Button blocks distinct styles for hover, focus, and active states directly in the editor&#8217;s style controls. Set the styles for just one button or all buttons.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-large\"><img alt=\"\" class=\"wp-image-21446\" height=\"632\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/08/Set-interactive-styles.webp?resize=1024%2C632&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\">A more consistent editing experience</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The post editor is now fully iframed for all themes, matching the Site Editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The editing canvas runs separately from the WordPress admin interface, so admin styles don’t interfere with your content. Viewport-relative units and media queries now target the editing canvas directly, so responsive layouts behave more predictably as you build. The change is mostly invisible, but the result is a more reliable and consistent editor.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Developer&#8217;s toolbox</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Advanced tools for building your way.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 expands several of the APIs and tools developers use to build on WordPress, with new options for icons, automation, admin interfaces, and responsive styling.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The SVG Icon API is now a public API, allowing developers to register their own icon collections and icons and use them throughout the editor with functions such as <code>wp_register_icon_collection(), wp_register_icon(), and wp_get_icon().</code></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Abilities API builds on the infrastructure introduced in WordPress 6.9 with a filterable execution lifecycle, custom validation, and shared discovery. These additions make it easier to build integrations and automation on top of WordPress, including AI-powered tooling.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A new Design System provides foundational support for theming WordPress admin interfaces, including color, roundness, and cursor styles. Developers can use semantic design tokens and the <code>ThemeProvider</code> React component to bring more consistency to custom admin interfaces while still feeling at home in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Theme authors also get responsive styling and pseudo-state styling for hover, focus, focus-visible, and active states through <code>theme.json</code>, along with new filters for configuring the DataViews and DataForm screens that power Pages, Templates, Parts, and Patterns in the Site Editor.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Accessibility</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 continues to improve accessibility across WordPress Core and the editor. New <code>wp_get_tooltip()</code> and <code>wp_get_toggletip()</code> functions bring accessible tooltips to more areas of the WordPress admin, including post meta boxes and the login screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Screen reader support also improves across admin interfaces, with clearer labeling and more predictable navigation in post list tables. The new Tab and Playlist blocks, along with improvements to editor navigation and interaction, add to the broader accessibility work included in this release.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Together, these changes continue to make WordPress easier to navigate and use for more people.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Performance improvements</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Image compression, resizing, and thumbnail generation now run in the browser (via a WebAssembly build of libvips), reducing the processing load on your server and helping avoid memory limits and timeouts with larger uploads.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Opt-in GIF-to-video conversion produces typically smaller files, while upload progress indicators and automatic retries make uploads more resilient when connections drop.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Media Library now uses infinite scrolling by default, with a per-user option to return to pagination. Speculative loading defaults can now be set through environment variables or constants, so hosts and site owners can configure how WordPress prefetches pages without writing a plugin.</p>\n\n\n\n<h2 class=\"wp-block-heading\">And much more!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">For a comprehensive overview of everything new and improved in WordPress 7.1, visit the feature showcase website.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://wordpress.org/download/releases/7-1/\">Check out what&#8217;s new in 7.1</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Learn more about WordPress 7.1</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://learn.wordpress.org/\">Learn WordPress</a> is a free resource for new and experienced WordPress users.  Learn is stocked with how-to videos on using various features in WordPress, <a href=\"https://learn.wordpress.org/social-learning/\">interactive workshops</a> for exploring topics in-depth, and lesson plans for diving deep into specific areas of WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Read the <a href=\"https://wordpress.org/documentation/wordpress-version/version-7.1/\">WordPress 7.1 Release Notes</a> for information on installation, enhancements, fixed issues, release contributors, learning resources, and the list of file changes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Explore the <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">WordPress 7.1 Field Guide</a>.  Learn about the changes in this release with detailed developer notes to help you build with WordPress.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The 7.1 release squad</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Every release comes to you from a dedicated team of enthusiastic contributors who help keep things on track and moving smoothly. The team that has led 7.1 is a cross-functional group of contributors who are always ready to champion ideas, remove blockers, and resolve issues.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Release Lead: <a href=\"https://profiles.wordpress.org/annezazu/\">Anne McCarthy</a></li>\n\n\n\n<li>Release Coordination: <a href=\"https://profiles.wordpress.org/benjamin_zekavica/\">Benjamin Zekavica</a>, <a href=\"https://profiles.wordpress.org/krupajnanda/\">Krupa Nanda</a></li>\n\n\n\n<li>Tech Leads: <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/joedolson/\">Joe Dolson</a></li>\n\n\n\n<li>Triage Leads: <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/sajjad67/\">Sajjad Hossain Sagor</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a></li>\n\n\n\n<li>Test Leads: <a href=\"https://profiles.wordpress.org/huzaifaalmesbah/\">Huzaifa Al Mesbah</a>, <a href=\"https://profiles.wordpress.org/nikunj8866/\">Nikunj Hatkar</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you, contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The mission of WordPress is to <a href=\"https://wordpress.org/about/\">democratize</a> publishing and <a href=\"https://opensource.org/osd-annotated\">embody the freedoms that come with open source</a>.  A global and diverse community of people collaborating to strengthen the software supports this effort.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 reflects the tireless efforts and passion of more than 800 contributors from all over the world. This release also welcomed over 170 first-time contributors! </p>\n\n\n\n<p class=\"wp-block-paragraph\">Together, their work delivered more than 1500 enhancements and fixes, helping make WordPress 7.1 a stable and polished release for everyone. It’s another great example of what the WordPress open source community can accomplish when people come together to build, test, and improve the software</p>\n\n\n\n<p class=\"wp-block-paragraph\"><p class=\"has-small-font-size\"><a href=\"https://profiles.wordpress.org/ishihara-takashi/\">1shiharaT</a> · <a href=\"https://profiles.wordpress.org/aagam94/\">Aagam Shah</a> · <a href=\"https://profiles.wordpress.org/aakashverma1/\">Aakash Verma</a> · <a href=\"https://profiles.wordpress.org/aaroncampbell/\">Aaron D. Campbell</a> · <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> · <a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a> · <a href=\"https://profiles.wordpress.org/abdalsalaam/\">Abdalsalaam Halawa</a> · <a href=\"https://profiles.wordpress.org/abdullahramzan/\">Abdullah Ramzan</a> · <a href=\"https://profiles.wordpress.org/abduremon/\">Abdur Rahman Emon</a> · <a href=\"https://profiles.wordpress.org/abhishekfdd/\">Abhishek Kumar</a> · <a href=\"https://profiles.wordpress.org/ibachal/\">Achal Jain</a> · <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> · <a href=\"https://profiles.wordpress.org/adamwood/\">Adam Wood</a> · <a href=\"https://profiles.wordpress.org/zieladam/\">Adam Zieliński</a> · <a href=\"https://profiles.wordpress.org/adrianmoldovanwp/\">Adi Moldovan</a> · <a href=\"https://profiles.wordpress.org/adithyanaik/\">adithyanaik</a> · <a href=\"https://profiles.wordpress.org/iamadisingh/\">Aditya Singh</a> · <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a> · <a href=\"https://profiles.wordpress.org/adrmf25/\">adrmf25</a> · <a href=\"https://profiles.wordpress.org/agulbra/\">agulbra</a> · <a href=\"https://profiles.wordpress.org/elazzabi/\">Ahmed</a> · <a href=\"https://profiles.wordpress.org/chaion07/\">Ahmed Kabir Chaion</a> · <a href=\"https://profiles.wordpress.org/ahuseyn/\">ahuseyn</a> · <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a> · <a href=\"https://