INSERT INTO `wp_snippets` VALUES (1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-07-10 16:10:59',1,NULL),(2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-07-10 16:10:59',1,NULL),(3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-07-10 16:10:59',1,NULL),(4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-07-10 16:10:59',1,NULL),(5,'Tecnopremium: Tienda, Categorías, Producto Individual y ACF','Personalización visual y funcional para Tienda, Categorías y Producto Individual con ACF Pro y estilos de lujo Tecnopremium.','// ULTIMATE LUXURY DARK-MODE CSS FOR WOOCOMMERCE INTERNAL PAGES (CART, CHECKOUT, MY ACCOUNT, ORDER TRACKING)\nadd_action(\"wp_head\", function() {\n    if (!is_woocommerce() && !is_cart() && !is_checkout() && !is_account_page() && !is_wc_endpoint_url()) return;\n    ?>\n    <style id=\"tp-luxury-woo-internal-css\">\n    /* ==========================================================================\n       1. GLOBAL WOOCOMMERCE NOTICES, ALERTS & COUPON ERRORS (LUXURY GOLD)\n       ========================================================================== */\n    .woocommerce-message, \n    .woocommerce-info, \n    .woocommerce-error,\n    ul.woocommerce-error li,\n    .woocommerce-cart td.actions .coupon .coupon-error-notice,\n    form.checkout_coupon .coupon-error-notice,\n    .coupon-error-notice,\n    .checkout-inline-error-message,\n    .woocommerce-cart td.actions .woocommerce-error,\n    .woocommerce-cart .coupon + .woocommerce-error,\n    div.wc-block-components-notice-banner,\n    div[role=\"alert\"].woocommerce-error {\n        background: #222026 !important;\n        color: #EABB61 !important;\n        border: 1px solid #EABB61 !important;\n        border-left: 4px solid #EABB61 !important;\n        border-radius: 10px !important;\n        padding: 16px 22px !important;\n        box-shadow: 0 10px 30px rgba(234, 187, 97, 0.3) !important;\n        margin: 16px 0 !important;\n        font-weight: 700 !important;\n        font-size: 1.05rem !important;\n        line-height: 1.5 !important;\n        list-style: none !important;\n        box-sizing: border-box !important;\n        width: 100% !important;\n        display: block !important;\n        clear: both !important;\n        float: none !important;\n        text-align: left !important;\n    }\n    /* Prevent double box nesting on ul.woocommerce-error */\n    ul.woocommerce-error {\n        background: transparent !important;\n        border: none !important;\n        box-shadow: none !important;\n        padding: 0 !important;\n        margin: 16px 0 !important;\n        width: 100% !important;\n        list-style: none !important;\n    }\n    ul.woocommerce-error li {\n        margin: 0 0 12px 0 !important;\n        width: 100% !important;\n    }\n    ul.woocommerce-error li:last-child { margin-bottom: 0 !important; }\n    /* Specific override for WooCommerce AJAX coupon inline error inside .actions */\n    .woocommerce-cart table.shop_table.cart td.actions .coupon .coupon-error-notice,\n    .woocommerce-cart table.shop_table.cart td.actions .coupon-error-notice {\n        color: #EABB61 !important;\n        background: #222026 !important;\n        border: 1px solid #EABB61 !important;\n        border-left: 4px solid #EABB61 !important;\n        font-size: 1.05rem !important;\n        font-weight: 700 !important;\n        padding: 14px 20px !important;\n        border-radius: 8px !important;\n        margin-top: 14px !important;\n        box-shadow: 0 8px 25px rgba(234, 187, 97, 0.3) !important;\n        flex-basis: 100% !important;\n        width: 100% !important;\n        display: block !important;\n    }\n    .woocommerce-message::before, .woocommerce-info::before, .woocommerce-error::before {\n        color: #EABB61 !important;\n        position: static !important;\n        margin-right: 12px;\n    }\n    .woocommerce-message .button, .woocommerce-info .button, .woocommerce-error .button {\n        background: #EABB61 !important;\n        color: #111 !important;\n        border-radius: 6px !important;\n        font-weight: 700 !important;\n        padding: 8px 18px !important;\n        text-transform: uppercase;\n        font-size: 0.88rem !important;\n        transition: transform 0.2s, box-shadow 0.2s !important;\n    }\n    .woocommerce-message .button:hover {\n        transform: translateY(-2px);\n        box-shadow: 0 4px 12px rgba(234, 187, 97, 0.4) !important;\n    }\n\n    \n    /* ==========================================================================\n       2. WOOCOMMERCE CART PAGE (.woocommerce-cart) & 3. CHECKOUT - ULTRA LUXURY BORDERLESS\n       State-of-the-art open architectural layout with zero prison tables/boxes\n       ========================================================================== */\n\n    /* Reset: Eliminate all outer borders, vertical column lines & cell grids */\n    .woocommerce-cart table.shop_table,\n    .woocommerce-checkout table.shop_table,\n    .woocommerce-cart table.shop_table th,\n    .woocommerce-cart table.shop_table td,\n    .woocommerce-checkout table.shop_table th,\n    .woocommerce-checkout table.shop_table td,\n    .woocommerce-cart table.shop_table.cart tbody tr td,\n    .woocommerce-cart table.shop_table.cart thead tr th {\n        border-left: none !important;\n        border-right: none !important;\n        border-top: none !important;\n        background: transparent !important;\n    }\n\n    /* 1. Cart Table Container (No outer box frame!) */\n    .woocommerce-cart table.shop_table.cart {\n        background: transparent !important;\n        border: none !important;\n        border-radius: 0 !important;\n        box-shadow: none !important;\n        width: 100% !important;\n        margin: 0 0 50px 0 !important;\n        border-collapse: collapse !important;\n        border-spacing: 0 !important;\n    }\n\n    /* Header Row (thead) */\n    .woocommerce-cart table.shop_table.cart thead {\n        background: transparent !important;\n    }\n    .woocommerce-cart table.shop_table.cart thead th {\n        background: transparent !important;\n        color: #8C8B92 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 600 !important;\n        font-size: 13px !important;\n        letter-spacing: 2px !important;\n        text-transform: uppercase !important;\n        padding: 0 16px 22px 16px !important;\n        border-bottom: 1px solid rgba(234, 187, 97, 0.25) !important;\n        text-align: left !important;\n    }\n    .woocommerce-cart table.shop_table.cart thead th.product-price,\n    .woocommerce-cart table.shop_table.cart thead th.product-quantity,\n    .woocommerce-cart table.shop_table.cart thead th.product-subtotal {\n        text-align: center !important;\n    }\n\n    /* Product Rows (tbody tr) */\n    .woocommerce-cart table.shop_table.cart tbody tr.woocommerce-cart-form__cart-item {\n        border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;\n        transition: background 0.3s ease !important;\n    }\n    .woocommerce-cart table.shop_table.cart tbody tr.woocommerce-cart-form__cart-item:hover {\n        background: rgba(255, 255, 255, 0.018) !important;\n    }\n    .woocommerce-cart table.shop_table.cart tbody tr.woocommerce-cart-form__cart-item td {\n        padding: 34px 16px !important;\n        border-bottom: none !important;\n        vertical-align: middle !important;\n    }\n\n    /* Delete Button (td.product-remove) */\n    .woocommerce-cart table.shop_table.cart td.product-remove {\n        width: 48px !important;\n        text-align: center !important;\n        padding-left: 0 !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-remove a.remove {\n        display: inline-flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        width: 36px !important;\n        height: 36px !important;\n        background: rgba(255, 255, 255, 0.05) !important;\n        color: #A0A0A0 !important;\n        border-radius: 50% !important;\n        font-size: 20px !important;\n        line-height: 1 !important;\n        text-decoration: none !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-remove a.remove:hover {\n        background: #EABB61 !important;\n        color: #111014 !important;\n        transform: rotate(90deg) scale(1.1) !important;\n    }\n\n    /* Thumbnail (td.product-thumbnail) - RESOLVING SQUISHED 15PX SLIVER */\n    .woocommerce-cart table.shop_table.cart td.product-thumbnail {\n        width: 130px !important;\n        min-width: 130px !important;\n        max-width: 130px !important;\n        padding-right: 28px !important;\n        display: table-cell !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-thumbnail a {\n        display: block !important;\n        width: 96px !important;\n        height: 96px !important;\n        border-radius: 14px !important;\n        overflow: hidden !important;\n        border: 1px solid rgba(255, 255, 255, 0.12) !important;\n        background: #18171B !important;\n        box-shadow: 0 8px 20px rgba(0,0,0,0.4) !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-thumbnail img {\n        width: 100% !important;\n        height: 100% !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        display: block !important;\n        margin: 0 !important;\n    }\n\n    /* Title (td.product-name) */\n    .woocommerce-cart table.shop_table.cart td.product-name {\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 18px !important;\n        font-weight: 600 !important;\n        line-height: 1.4 !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-name a {\n        color: #FFFFFF !important;\n        text-decoration: none !important;\n        transition: color 0.3s ease !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-name a:hover {\n        color: #EABB61 !important;\n    }\n\n    /* Price & Subtotal Columns */\n    .woocommerce-cart table.shop_table.cart td.product-price,\n    .woocommerce-cart table.shop_table.cart td.product-subtotal {\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 18px !important;\n        font-weight: 700 !important;\n        color: #EABB61 !important;\n        text-align: center !important;\n    }\n\n    /* Quantity Input */\n    .woocommerce-cart table.shop_table.cart td.product-quantity {\n        text-align: center !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-quantity .quantity {\n        display: inline-flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-quantity input.qty {\n        width: 68px !important;\n        height: 46px !important;\n        background: #18171C !important;\n        border: 1px solid rgba(234, 187, 97, 0.3) !important;\n        border-radius: 12px !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 600 !important;\n        text-align: center !important;\n        padding: 0 8px !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-cart table.shop_table.cart td.product-quantity input.qty:focus {\n        border-color: #EABB61 !important;\n        box-shadow: 0 0 14px rgba(234, 187, 97, 0.28) !important;\n        outline: none !important;\n    }\n\n    /* Actions Row (Coupon & Update Button) */\n    .woocommerce-cart table.shop_table.cart td.actions {\n        background: transparent !important;\n        padding: 36px 0 0 0 !important;\n        border-top: 1px solid rgba(255, 255, 255, 0.08) !important;\n    }\n    .woocommerce-cart .coupon {\n        display: inline-flex !important;\n        align-items: center !important;\n        gap: 12px !important;\n    }\n    .woocommerce-cart .coupon input.input-text {\n        width: 240px !important;\n        height: 50px !important;\n        background: #18171C !important;\n        border: 1px solid rgba(255, 255, 255, 0.16) !important;\n        border-radius: 25px !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 14px !important;\n        padding: 0 22px !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-cart .coupon input.input-text:focus {\n        border-color: #EABB61 !important;\n        box-shadow: 0 0 12px rgba(234, 187, 97, 0.22) !important;\n        outline: none !important;\n    }\n    .woocommerce-cart .coupon button.button {\n        height: 50px !important;\n        background: rgba(234, 187, 97, 0.15) !important;\n        color: #EABB61 !important;\n        border: 1px solid rgba(234, 187, 97, 0.45) !important;\n        border-radius: 25px !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 13px !important;\n        font-weight: 700 !important;\n        letter-spacing: 1.5px !important;\n        text-transform: uppercase !important;\n        padding: 0 26px !important;\n        cursor: pointer !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-cart .coupon button.button:hover {\n        background: #EABB61 !important;\n        color: #111014 !important;\n        transform: translateY(-2px) !important;\n    }\n    .woocommerce-cart .actions > button.button {\n        float: right !important;\n        height: 50px !important;\n        background: #24222A !important;\n        color: #FFFFFF !important;\n        border: 1px solid rgba(255, 255, 255, 0.14) !important;\n        border-radius: 25px !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 13px !important;\n        font-weight: 600 !important;\n        letter-spacing: 1px !important;\n        text-transform: uppercase !important;\n        padding: 0 30px !important;\n        cursor: pointer !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-cart .actions > button.button:hover {\n        background: #EABB61 !important;\n        color: #111014 !important;\n        border-color: #EABB61 !important;\n        transform: translateY(-2px) !important;\n    }\n\n    /* 2. Cart Totals Card (Right Column) - Sleek Glassmorphism Card */\n    .woocommerce-cart .cart-collaterals .cart_totals {\n        background: linear-gradient(145deg, #1D1C23 0%, #15141A 100%) !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        border-radius: 24px !important;\n        padding: 42px 38px !important;\n        box-shadow: 0 25px 60px rgba(0,0,0,0.6) !important;\n    }\n    .woocommerce-cart .cart_totals h2 {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 700 !important;\n        font-size: 24px !important;\n        margin-top: 0 !important;\n        margin-bottom: 30px !important;\n        padding-bottom: 18px !important;\n        border-bottom: 2px solid #EABB61 !important;\n        display: inline-block !important;\n    }\n\n    /* Remove grey rectangle behind subtotal & clean rows inside totals */\n    .woocommerce-cart .cart_totals table.shop_table {\n        background: transparent !important;\n        border: none !important;\n        margin-bottom: 32px !important;\n        width: 100% !important;\n    }\n    .woocommerce-cart .cart_totals table.shop_table th,\n    .woocommerce-cart .cart_totals table.shop_table td {\n        background: transparent !important;\n        border: none !important;\n        padding: 20px 4px !important;\n        border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n    }\n    .woocommerce-cart .cart_totals table.shop_table th {\n        font-size: 15px !important;\n        font-weight: 600 !important;\n        color: #A0A0A0 !important;\n    }\n    .woocommerce-cart .cart_totals table.shop_table td {\n        font-size: 16px !important;\n        font-weight: 700 !important;\n        text-align: right !important;\n    }\n\n    /* Order Total Row */\n    .woocommerce-cart .cart_totals table.shop_table tr.order-total th,\n    .woocommerce-cart .cart_totals table.shop_table tr.order-total td {\n        border-bottom: none !important;\n        border-top: 1px solid rgba(234, 187, 97, 0.3) !important;\n        padding-top: 28px !important;\n        padding-bottom: 10px !important;\n    }\n    .woocommerce-cart .cart_totals table.shop_table tr.order-total th {\n        color: #FFFFFF !important;\n        font-size: 18px !important;\n        font-weight: 700 !important;\n    }\n    .woocommerce-cart .cart_totals table.shop_table tr.order-total td {\n        color: #EABB61 !important;\n        font-size: 28px !important;\n        font-weight: 800 !important;\n    }\n\n    /* Finalizar Compra Button */\n    .woocommerce-cart .wc-proceed-to-checkout {\n        padding: 0 !important;\n        margin-top: 12px !important;\n    }\n    .woocommerce-cart .wc-proceed-to-checkout a.checkout-button {\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        width: 100% !important;\n        height: 60px !important;\n        background: linear-gradient(135deg, #EABB61 0%, #C89442 100%) !important;\n        color: #111014 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 800 !important;\n        letter-spacing: 1.5px !important;\n        text-transform: uppercase !important;\n        border-radius: 30px !important;\n        text-decoration: none !important;\n        box-shadow: 0 12px 30px rgba(234, 187, 97, 0.35) !important;\n        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;\n    }\n    .woocommerce-cart .wc-proceed-to-checkout a.checkout-button:hover {\n        transform: translateY(-4px) scale(1.01) !important;\n        box-shadow: 0 18px 40px rgba(234, 187, 97, 0.5) !important;\n        background: linear-gradient(135deg, #F3C978 0%, #D8A350 100%) !important;\n    }\n\n    /* 3. Checkout Order Review Card (Sleek matching card) */\n    .woocommerce-checkout #order_review {\n        background: linear-gradient(145deg, #1D1C23 0%, #15141A 100%) !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        border-radius: 24px !important;\n        padding: 42px 38px !important;\n        box-shadow: 0 25px 60px rgba(0,0,0,0.6) !important;\n    }\n    .woocommerce-checkout #order_review_heading {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 700 !important;\n        font-size: 24px !important;\n        margin-top: 0 !important;\n        margin-bottom: 30px !important;\n        padding-bottom: 18px !important;\n        border-bottom: 2px solid #EABB61 !important;\n        display: inline-block !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table {\n        background: transparent !important;\n        border: none !important;\n        width: 100% !important;\n        margin-bottom: 32px !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table th,\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table td {\n        background: transparent !important;\n        border: none !important;\n        padding: 20px 4px !important;\n        border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table th {\n        font-size: 15px !important;\n        font-weight: 600 !important;\n        color: #A0A0A0 !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table td {\n        font-size: 16px !important;\n        font-weight: 700 !important;\n        text-align: right !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total th,\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total td {\n        border-bottom: none !important;\n        border-top: 1px solid rgba(234, 187, 97, 0.3) !important;\n        padding-top: 28px !important;\n        padding-bottom: 10px !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total th {\n        color: #FFFFFF !important;\n        font-size: 18px !important;\n        font-weight: 700 !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total td {\n        color: #EABB61 !important;\n        font-size: 28px !important;\n        font-weight: 800 !important;\n    }\n\n    /* Mobile Responsive Layout */\n    @media (max-width: 1023px) {\n        .woocommerce-cart table.shop_table.cart td.product-thumbnail {\n            width: 100% !important;\n            max-width: 100% !important;\n            text-align: center !important;\n            padding-right: 0 !important;\n        }\n        .woocommerce-cart table.shop_table.cart td.product-thumbnail a {\n            margin: 0 auto !important;\n            width: 120px !important;\n            height: 120px !important;\n        }\n        .woocommerce-cart .coupon {\n            flex-direction: column !important;\n            width: 100% !important;\n        }\n        .woocommerce-cart .coupon input.input-text,\n        .woocommerce-cart .coupon button.button,\n        .woocommerce-cart .actions > button.button {\n            width: 100% !important;\n            margin-bottom: 12px !important;\n        }\n    }\n    \n    /* ==========================================================================\n       4. WOOCOMMERCE MY ACCOUNT PAGE (.woocommerce-account) - SURGICAL GRID & LOGIN\n       ========================================================================== */\n    .woocommerce-account .woocommerce {\n        max-width: 1320px;\n        margin: 0 auto;\n        padding: 40px 20px;\n        box-sizing: border-box;\n    }\n    \n    /* ONLY APPLY SIDEBAR GRID WHEN LOGGED IN / NAVIGATION EXISTS */\n    @media (min-width: 1024px) {\n        body.logged-in.woocommerce-account .woocommerce,\n        .woocommerce-account .woocommerce:has(.woocommerce-MyAccount-navigation) {\n            display: grid !important;\n            grid-template-columns: 280px 1fr !important;\n            gap: 40px !important;\n            align-items: start !important;\n        }\n        body.logged-in.woocommerce-account .woocommerce > .woocommerce-notices-wrapper,\n        .woocommerce-account .woocommerce:has(.woocommerce-MyAccount-navigation) > .woocommerce-notices-wrapper {\n            grid-column: 1 / -1;\n            width: 100%;\n        }\n        body.logged-in.woocommerce-account .woocommerce > .woocommerce-MyAccount-navigation,\n        .woocommerce-account .woocommerce:has(.woocommerce-MyAccount-navigation) > .woocommerce-MyAccount-navigation {\n            grid-column: 1 / 2;\n            width: 100%;\n        }\n        body.logged-in.woocommerce-account .woocommerce > .woocommerce-MyAccount-content,\n        .woocommerce-account .woocommerce:has(.woocommerce-MyAccount-navigation) > .woocommerce-MyAccount-content {\n            grid-column: 2 / 3;\n            width: 100%;\n            float: none !important;\n        }\n    }\n\n    /* WHEN LOGGED OUT: #customer_login (ACCEDER & REGISTRARSE) SPACIOUS 2-COLUMN GRID */\n    body:not(.logged-in).woocommerce-account .woocommerce,\n    .woocommerce-account .woocommerce:has(#customer_login) {\n        display: block !important;\n        max-width: 1150px !important;\n        margin: 0 auto !important;\n    }\n    #customer_login.u-columns.col2-set,\n    .woocommerce-account #customer_login {\n        display: grid !important;\n        grid-template-columns: 1fr !important;\n        gap: 40px !important;\n        width: 100% !important;\n        max-width: 100% !important;\n        background: transparent !important;\n        border: none !important;\n        box-shadow: none !important;\n        padding: 0 !important;\n        margin: 20px 0 50px 0 !important;\n    }\n    @media (min-width: 768px) {\n        #customer_login.u-columns.col2-set,\n        .woocommerce-account #customer_login {\n            grid-template-columns: 1fr 1fr !important; /* 50% Acceder / 50% Registrarse */\n            align-items: start !important;\n        }\n    }\n    #customer_login .u-column1.col-1,\n    #customer_login .u-column2.col-2 {\n        width: 100% !important;\n        max-width: 100% !important;\n        float: none !important;\n        margin: 0 !important;\n        background: #1E1D22 !important;\n        border: 1px solid rgba(234, 187, 97, 0.3) !important;\n        border-radius: 16px !important;\n        padding: 40px !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.5) !important;\n        box-sizing: border-box !important;\n    }\n    #customer_login .u-column1.col-1 h2,\n    #customer_login .u-column2.col-2 h2 {\n        color: #EABB61 !important;\n        font-size: 1.65rem !important;\n        font-weight: 700 !important;\n        margin: 0 0 25px 0 !important;\n        padding-bottom: 14px !important;\n        border-bottom: 1px solid rgba(234, 187, 97, 0.2) !important;\n    }\n    /* Ensure inner forms have clean width without double borders/padding */\n    #customer_login .u-column1.col-1 form.login,\n    #customer_login .u-column2.col-2 form.register {\n        background: transparent !important;\n        border: none !important;\n        box-shadow: none !important;\n        padding: 0 !important;\n        margin: 0 !important;\n        max-width: 100% !important;\n        width: 100% !important;\n    }\n    #customer_login .form-row {\n        margin-bottom: 20px !important;\n        width: 100% !important;\n    }\n    #customer_login label {\n        color: #D0D0D0 !important;\n        font-weight: 600 !important;\n        font-size: 0.95rem !important;\n        margin-bottom: 8px !important;\n        display: block !important;\n    }\n    #customer_login input.input-text {\n        background: #141317 !important;\n        border: 1px solid rgba(255,255,255,0.18) !important;\n        color: #FFF !important;\n        border-radius: 8px !important;\n        padding: 14px 18px !important;\n        height: 50px !important;\n        width: 100% !important;\n        box-sizing: border-box !important;\n        font-size: 1rem !important;\n        transition: border-color 0.3s, box-shadow 0.3s !important;\n    }\n    #customer_login input.input-text:focus {\n        border-color: #EABB61 !important;\n        box-shadow: 0 0 12px rgba(234, 187, 97, 0.25) !important;\n        outline: none !important;\n    }\n    #customer_login button.button {\n        background: linear-gradient(135deg, #EABB61 0%, #C89442 100%) !important;\n        color: #111 !important;\n        font-size: 1.05rem !important;\n        font-weight: 800 !important;\n        text-transform: uppercase !important;\n        letter-spacing: 1px !important;\n        border-radius: 8px !important;\n        padding: 16px 32px !important;\n        width: 100% !important;\n        margin-top: 15px !important;\n        border: none !important;\n        cursor: pointer !important;\n        box-shadow: 0 8px 25px rgba(234, 187, 97, 0.35) !important;\n        transition: transform 0.3s, box-shadow 0.3s !important;\n    }\n    #customer_login button.button:hover {\n        transform: translateY(-2px) !important;\n        box-shadow: 0 12px 30px rgba(234, 187, 97, 0.5) !important;\n    }\n    #customer_login .woocommerce-LostPassword {\n        margin-top: 15px !important;\n        text-align: center !important;\n    }\n    #customer_login .woocommerce-LostPassword a {\n        color: #EABB61 !important;\n        text-decoration: underline !important;\n    }\n    \n    /* Account Navigation Sidebar (When logged in) */\n    .woocommerce-MyAccount-navigation {\n        background: #1E1D22 !important;\n        border: 1px solid rgba(234, 187, 97, 0.25) !important;\n        border-radius: 14px !important;\n        overflow: hidden !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.5) !important;\n        margin-bottom: 30px !important;\n    }\n    .woocommerce-MyAccount-navigation ul {\n        list-style: none !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .woocommerce-MyAccount-navigation ul li {\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        margin: 0 !important;\n    }\n    .woocommerce-MyAccount-navigation ul li:last-child { border-bottom: none !important; }\n    .woocommerce-MyAccount-navigation ul li a {\n        display: block !important;\n        padding: 16px 22px !important;\n        color: #D0D0D0 !important;\n        text-decoration: none !important;\n        font-weight: 600 !important;\n        font-size: 0.98rem !important;\n        transition: all 0.3s !important;\n    }\n    .woocommerce-MyAccount-navigation ul li.is-active a,\n    .woocommerce-MyAccount-navigation ul li a:hover {\n        background: rgba(234, 187, 97, 0.15) !important;\n        color: #EABB61 !important;\n        border-left: 4px solid #EABB61 !important;\n        padding-left: 18px !important;\n    }\n    \n    /* Account Content Area */\n    .woocommerce-MyAccount-content {\n        background: #222026 !important;\n        border: 1px solid rgba(234, 187, 97, 0.25) !important;\n        border-radius: 16px !important;\n        padding: 35px !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.5) !important;\n        color: #FFF !important;\n        line-height: 1.7 !important;\n        box-sizing: border-box !important;\n    }\n    .woocommerce-MyAccount-content h2,\n    .woocommerce-MyAccount-content h3 {\n        color: #EABB61 !important;\n        font-weight: 700 !important;\n        margin-bottom: 20px !important;\n    }\n    .woocommerce-MyAccount-content p a {\n        color: #EABB61 !important;\n        text-decoration: underline !important;\n    }\n    \n    /* Account Tables & Addresses */\n    .woocommerce-MyAccount-content table.my_account_orders,\n    .woocommerce-MyAccount-content table.woocommerce-table {\n        width: 100% !important;\n        background: #18171B !important;\n        border-radius: 10px !important;\n        overflow: hidden !important;\n        border: 1px solid rgba(255,255,255,0.1) !important;\n        margin-bottom: 25px !important;\n    }\n    .woocommerce-MyAccount-content table th {\n        background: #141317 !important;\n        color: #EABB61 !important;\n        padding: 14px 16px !important;\n        text-transform: uppercase !important;\n        font-size: 0.85rem !important;\n        text-align: left !important;\n    }\n    .woocommerce-MyAccount-content table td {\n        padding: 14px 16px !important;\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        color: #FFF !important;\n    }\n    .woocommerce-MyAccount-content .button {\n        background: #EABB61 !important;\n        color: #111 !important;\n        border-radius: 6px !important;\n        font-weight: 700 !important;\n        padding: 10px 20px !important;\n        text-transform: uppercase !important;\n        text-decoration: none !important;\n        display: inline-block !important;\n    }\n\n    /* ==========================================================================\n       5. THANK YOU / ORDER RECEIVED PAGE (.woocommerce-order)\n       ========================================================================== */\n    .woocommerce-order {\n        max-width: 900px;\n        margin: 40px auto;\n        padding: 40px 20px;\n        box-sizing: border-box;\n    }\n    .woocommerce-order .woocommerce-notice--success {\n        background: #1E1D22 !important;\n        border: 1px solid #EABB61 !important;\n        border-radius: 14px !important;\n        padding: 24px !important;\n        color: #EABB61 !important;\n        font-size: 1.25rem !important;\n        font-weight: 700 !important;\n        text-align: center !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.5) !important;\n        margin-bottom: 35px !important;\n    }\n    .woocommerce-order ul.order_details {\n        background: #222026 !important;\n        border: 1px solid rgba(234, 187, 97, 0.25) !important;\n        border-radius: 12px !important;\n        padding: 24px !important;\n        display: flex !important;\n        flex-wrap: wrap !important;\n        gap: 20px !important;\n        justify-content: space-around !important;\n        list-style: none !important;\n        margin-bottom: 35px !important;\n    }\n    .woocommerce-order ul.order_details li {\n        color: #D0D0D0 !important;\n        font-size: 0.9rem !important;\n        text-transform: uppercase !important;\n    }\n    .woocommerce-order ul.order_details li strong {\n        display: block !important;\n        color: #FFF !important;\n        font-size: 1.15rem !important;\n        margin-top: 6px !important;\n        text-transform: none !important;\n    }\n\n    /* ==========================================================================\n       6. RESPONSIVE MOBILE ADJUSTMENTS (< 1024px)\n       ========================================================================== */\n    @media (max-width: 1023px) {\n        .woocommerce-cart .woocommerce,\n        .woocommerce-checkout form.checkout,\n        .woocommerce-account .woocommerce {\n            display: flex !important;\n            flex-direction: column !important;\n            gap: 30px !important;\n        }\n        .woocommerce-cart table.shop_table_responsive thead { display: none !important; }\n        .woocommerce-cart table.shop_table_responsive tr {\n            display: block !important;\n            background: #1E1D22 !important;\n            border: 1px solid rgba(234, 187, 97, 0.25) !important;\n            border-radius: 12px !important;\n            margin-bottom: 20px !important;\n            padding: 16px !important;\n        }\n        .woocommerce-cart table.shop_table_responsive td {\n            display: flex !important;\n            justify-content: space-between !important;\n            align-items: center !important;\n            padding: 12px 0 !important;\n            border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n            text-align: right !important;\n        }\n        .woocommerce-cart table.shop_table_responsive td::before {\n            content: attr(data-title) !important;\n            font-weight: 700 !important;\n            color: #EABB61 !important;\n            text-transform: uppercase !important;\n            font-size: 0.82rem !important;\n        }\n        .woocommerce-cart .coupon { flex-direction: column !important; width: 100% !important; }\n        .woocommerce-cart .coupon input.input-text,\n        .woocommerce-cart .actions > button.button,\n        .woocommerce-cart .coupon button.button,\n        .woocommerce-cart .wc-proceed-to-checkout a.checkout-button,\n        #payment #place_order {\n            width: 100% !important;\n            float: none !important;\n        }\n    }\n/* ==========================================================================\n       7. HEADER NAVIGATION CART & LOGIN/ACCOUNT STYLING\n       ========================================================================== */\n    li.tp-nav-cart a, li.tp-nav-login a, li.tp-nav-account a, li.tp-nav-logout a {\n        display: inline-flex !important;\n        align-items: center !important;\n        gap: 8px !important;\n        font-weight: 700 !important;\n        transition: color 0.3s !important;\n    }\n    li.tp-nav-cart a { color: #EABB61 !important; }\n    li.tp-nav-login a:hover, li.tp-nav-account a:hover { color: #EABB61 !important; }\n    span.tp-cart-badge {\n        background: #EABB61 !important;\n        color: #111 !important;\n        font-size: 0.76rem !important;\n        font-weight: 800 !important;\n        padding: 2px 8px !important;\n        border-radius: 20px !important;\n        line-height: 1.2 !important;\n        display: inline-block !important;\n        box-shadow: 0 2px 8px rgba(234, 187, 97, 0.4) !important;\n    }\n    li.tp-nav-logout a { color: #CC0057 !important; }\n    li.tp-nav-logout a:hover { color: #FF1A75 !important; }\n\n    /* ==========================================================================\n       8. WOOCOMMERCE LOGIN & REGISTER FORMS (/checkout/ & /my-account/)\n       ========================================================================== */\n    .woocommerce-form-login, .woocommerce-form-register {\n        background: #1E1D22 !important;\n        border: 1px solid rgba(234, 187, 97, 0.3) !important;\n        border-radius: 14px !important;\n        padding: 30px !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.5) !important;\n        margin: 20px 0 !important;\n        color: #FFF !important;\n        max-width: 550px !important;\n        box-sizing: border-box !important;\n    }\n    .woocommerce-checkout .woocommerce-form-login {\n        max-width: 100% !important;\n    }\n    .woocommerce-form-login h2, .woocommerce-form-register h2 {\n        color: #EABB61 !important;\n        font-size: 1.5rem !important;\n        font-weight: 700 !important;\n        margin-bottom: 20px !important;\n        border-bottom: 1px solid rgba(234, 187, 97, 0.2) !important;\n        padding-bottom: 12px !important;\n    }\n    .woocommerce-form-login .form-row, .woocommerce-form-register .form-row {\n        margin-bottom: 18px !important;\n        width: 100% !important;\n    }\n    .woocommerce-form-login input.input-text, .woocommerce-form-register input.input-text {\n        background: #141317 !important;\n        border: 1px solid rgba(255,255,255,0.18) !important;\n        color: #FFF !important;\n        border-radius: 8px !important;\n        padding: 12px 16px !important;\n        height: 48px !important;\n        width: 100% !important;\n        box-sizing: border-box !important;\n    }\n    .woocommerce-form-login input.input-text:focus, .woocommerce-form-register input.input-text:focus {\n        border-color: #EABB61 !important;\n        box-shadow: 0 0 12px rgba(234, 187, 97, 0.25) !important;\n        outline: none !important;\n    }\n    .woocommerce-form-login button.button, .woocommerce-form-register button.button {\n        background: linear-gradient(135deg, #EABB61 0%, #C89442 100%) !important;\n        color: #111 !important;\n        font-weight: 800 !important;\n        padding: 14px 28px !important;\n        border-radius: 8px !important;\n        text-transform: uppercase !important;\n        border: none !important;\n        cursor: pointer !important;\n        box-shadow: 0 8px 20px rgba(234, 187, 97, 0.3) !important;\n        transition: transform 0.3s, box-shadow 0.3s !important;\n    }\n    .woocommerce-form-login button.button:hover, .woocommerce-form-register button.button:hover {\n        transform: translateY(-2px) !important;\n        box-shadow: 0 12px 28px rgba(234, 187, 97, 0.5) !important;\n    }\n    .woocommerce-form-login label.woocommerce-form__label-for-checkbox {\n        display: inline-flex !important;\n        align-items: center !important;\n        gap: 8px !important;\n        color: #D0D0D0 !important;\n        cursor: pointer !important;\n    }\n    .woocommerce-form-login .woocommerce-LostPassword a {\n        color: #EABB61 !important;\n        text-decoration: underline !important;\n    }\n/* ==========================================================================\n       9. STANDARD WORDPRESS LEGAL & INFORMATION PAGES (.page-template-default)\n       ========================================================================== */\n    body.page:not(.elementor-page) .site-content,\n    body.page:not(.elementor-page) .content-area,\n    body.page:not(.elementor-page) main,\n    body.page-template-default .entry-content,\n    body.page-template-default .post-content {\n        max-width: 1050px !important;\n        margin: 60px auto !important;\n        padding: 50px !important;\n        background: #1E1D22 !important;\n        border: 1px solid rgba(234, 187, 97, 0.25) !important;\n        border-radius: 18px !important;\n        box-shadow: 0 20px 45px rgba(0,0,0,0.5) !important;\n        color: #FFF !important;\n        line-height: 1.8 !important;\n        box-sizing: border-box !important;\n    }\n    @media (max-width: 768px) {\n        body.page:not(.elementor-page) .site-content,\n        body.page:not(.elementor-page) .content-area,\n        body.page:not(.elementor-page) main,\n        body.page-template-default .entry-content {\n            margin: 30px 15px !important;\n            padding: 25px !important;\n        }\n    }\n    body.page:not(.elementor-page) h1.wp-block-heading,\n    body.page:not(.elementor-page) h1.entry-title,\n    body.page-template-default h1 {\n        color: #EABB61 !important;\n        font-size: 2.4rem !important;\n        font-weight: 800 !important;\n        margin-bottom: 30px !important;\n        border-bottom: 1px solid rgba(234, 187, 97, 0.3) !important;\n        padding-bottom: 18px !important;\n    }\n    body.page:not(.elementor-page) h2.wp-block-heading,\n    body.page-template-default h2 {\n        color: #EABB61 !important;\n        font-size: 1.45rem !important;\n        font-weight: 700 !important;\n        margin-top: 35px !important;\n        margin-bottom: 16px !important;\n    }\n    body.page:not(.elementor-page) p,\n    body.page:not(.elementor-page) li,\n    body.page-template-default p,\n    body.page-template-default li {\n        color: #E0E0E0 !important;\n        font-size: 1.05rem !important;\n        margin-bottom: 16px !important;\n        line-height: 1.75 !important;\n    }\n    body.page:not(.elementor-page) ul,\n    body.page-template-default ul {\n        padding-left: 25px !important;\n        margin-bottom: 24px !important;\n    }\n    body.page:not(.elementor-page) strong,\n    body.page-template-default strong {\n        color: #FFF !important;\n        font-weight: 700 !important;\n    }\n    body.page:not(.elementor-page) code,\n    body.page-template-default code {\n        background: #141317 !important;\n        color: #EABB61 !important;\n        padding: 3px 8px !important;\n        border-radius: 4px !important;\n        font-family: monospace !important;\n    }\n    body.page:not(.elementor-page) a,\n    body.page-template-default a {\n        color: #EABB61 !important;\n        text-decoration: underline !important;\n        transition: color 0.3s !important;\n    }\n    body.page:not(.elementor-page) a:hover,\n    body.page-template-default a:hover {\n        color: #FFF !important;\n    }\n    \n    \n    \n    /* === LUXURY SINGLE PRODUCT & SPECIFICATIONS CSS (Fase 2) === */\n    .woocommerce div.product div.images .woocommerce-product-gallery__image {\n        border-radius: 8px !important;\n        overflow: hidden !important;\n        border: 1px solid rgba(234,187,97,0.15) !important;\n        background: #141317 !important;\n        margin-bottom: 12px !important;\n    }\n    .woocommerce div.product div.images .flex-control-thumbs li img {\n        border-radius: 6px !important;\n        border: 1px solid rgba(255,255,255,0.1) !important;\n        transition: all 0.3s ease !important;\n        opacity: 0.6 !important;\n    }\n    .woocommerce div.product div.images .flex-control-thumbs li img.flex-active,\n    .woocommerce div.product div.images .flex-control-thumbs li img:hover {\n        border-color: #EABB61 !important;\n        opacity: 1 !important;\n        transform: translateY(-2px) !important;\n    }\n    .woocommerce div.product .summary .price {\n        color: #EABB61 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 26px !important;\n        font-weight: 600 !important;\n        margin-bottom: 20px !important;\n    }\n    .woocommerce-tabs ul.tabs {\n        border-bottom: 1px solid rgba(234,187,97,0.2) !important;\n        padding-left: 0 !important;\n        margin-bottom: 30px !important;\n        display: flex !important;\n        gap: 15px !important;\n    }\n    .woocommerce-tabs ul.tabs li {\n        background: #1B1A20 !important;\n        border: 1px solid rgba(255,255,255,0.08) !important;\n        border-bottom: none !important;\n        border-radius: 6px 6px 0 0 !important;\n        margin: 0 !important;\n        padding: 12px 24px !important;\n        transition: all 0.3s !important;\n    }\n    .woocommerce-tabs ul.tabs li a {\n        color: #A0A0A5 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 15px !important;\n        font-weight: 500 !important;\n        text-decoration: none !important;\n    }\n    .woocommerce-tabs ul.tabs li.active {\n        background: #25242C !important;\n        border-color: #EABB61 !important;\n    }\n    .woocommerce-tabs ul.tabs li.active a {\n        color: #EABB61 !important;\n        font-weight: 600 !important;\n    }\n    .woocommerce-tabs .panel {\n        background: #141317 !important;\n        border: 1px solid rgba(234,187,97,0.15) !important;\n        border-radius: 8px !important;\n        padding: 30px !important;\n        color: #DDD !important;\n        line-height: 1.7 !important;\n    }\n    table.shop_attributes {\n        border: none !important;\n        background: transparent !important;\n        margin-bottom: 0 !important;\n    }\n    table.shop_attributes tr:nth-child(even) th,\n    table.shop_attributes tr:nth-child(even) td {\n        background: rgba(255,255,255,0.02) !important;\n    }\n    table.shop_attributes tr th {\n        color: #EABB61 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 600 !important;\n        padding: 14px 20px !important;\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        width: 35% !important;\n    }\n    table.shop_attributes tr td {\n        color: #FFFFFF !important;\n        padding: 14px 20px !important;\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        font-style: normal !important;\n    }\n    table.shop_attributes tr td p {\n        margin: 0 !important;\n    }\n    \n    /* === SQUARE CATEGORY CARDS MATCHING PRODUCT CARDS (Fase 1 / Shop) === */\n    .elementor-widget-wc-categories ul.products li.product-category,\n    .woocommerce ul.products li.product-category {\n        background: #141317 !important;\n        border: 1px solid rgba(234,187,97,0.15) !important;\n        border-radius: 8px !important;\n        overflow: hidden !important;\n        transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;\n        display: flex !important;\n        flex-direction: column !important;\n        margin-bottom: 24px !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category:hover,\n    .woocommerce ul.products li.product-category:hover {\n        border-color: #EABB61 !important;\n        transform: translateY(-5px) !important;\n        box-shadow: 0 10px 25px rgba(0,0,0,0.5) !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category a,\n    .woocommerce ul.products li.product-category a {\n        display: flex !important;\n        flex-direction: column !important;\n        height: 100% !important;\n        text-decoration: none !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category img,\n    .woocommerce ul.products li.product-category img {\n        width: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        height: auto !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        border-bottom: 1px solid rgba(255,255,255,0.06) !important;\n        margin: 0 !important;\n        display: block !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category .woocommerce-loop-category__title,\n    .woocommerce ul.products li.product-category .woocommerce-loop-category__title {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 600 !important;\n        padding: 16px 12px !important;\n        text-align: center !important;\n        margin: 0 !important;\n        line-height: 1.3 !important;\n        background: #141317 !important;\n        flex-grow: 1 !important;\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        flex-direction: column !important;\n        gap: 4px !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category:hover .woocommerce-loop-category__title,\n    .woocommerce ul.products li.product-category:hover .woocommerce-loop-category__title {\n        color: #EABB61 !important;\n    }\n    .elementor-widget-wc-categories ul.products li.product-category .woocommerce-loop-category__title mark.count,\n    .woocommerce ul.products li.product-category .woocommerce-loop-category__title mark.count {\n        background: transparent !important;\n        color: #888 !important;\n        font-size: 12px !important;\n        font-weight: 400 !important;\n        display: block !important;\n    }\n    \n    \n    \n    /* ==========================================================================\n       1. SECCIÓN 1: LAS 5 CATEGORÍAS DESTACADAS EN UNA SOLA LÍNEA (5 COLUMNAS)\n       Selector exacto: .elementor-element-tp_cats_grid / #tp_cats_grid\n       ========================================================================== */\n    .elementor-element-tp_cats_grid ul.products.columns-5,\n    .elementor-element-tp_cats_grid ul.products,\n    #tp_cats_grid ul.products.columns-5,\n    #tp_cats_grid ul.products {\n        display: grid !important;\n        grid-template-columns: repeat(5, minmax(0, 1fr)) !important;\n        gap: 24px !important;\n        width: 100% !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category,\n    #tp_cats_grid ul.products li.product-category {\n        width: 100% !important;\n        max-width: 100% !important;\n        margin: 0 !important;\n        float: none !important;\n        background: #141317 !important;\n        border: 1px solid rgba(234,187,97,0.18) !important;\n        border-radius: 12px !important;\n        overflow: hidden !important;\n        display: flex !important;\n        flex-direction: column !important;\n        transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category:hover,\n    #tp_cats_grid ul.products li.product-category:hover {\n        border-color: #EABB61 !important;\n        transform: translateY(-6px) !important;\n        box-shadow: 0 15px 35px rgba(234, 187, 97, 0.15) !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category a,\n    #tp_cats_grid ul.products li.product-category a {\n        display: flex !important;\n        flex-direction: column !important;\n        height: 100% !important;\n        text-decoration: none !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category img,\n    #tp_cats_grid ul.products li.product-category img {\n        width: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        height: auto !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        border-bottom: 1px solid rgba(255,255,255,0.08) !important;\n        margin: 0 !important;\n        display: block !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category .woocommerce-loop-category__title,\n    #tp_cats_grid ul.products li.product-category .woocommerce-loop-category__title {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 600 !important;\n        padding: 18px 12px !important;\n        text-align: center !important;\n        margin: 0 !important;\n        line-height: 1.35 !important;\n        background: #141317 !important;\n        flex-grow: 1 !important;\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        flex-direction: column !important;\n        gap: 6px !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category:hover .woocommerce-loop-category__title,\n    #tp_cats_grid ul.products li.product-category:hover .woocommerce-loop-category__title {\n        color: #EABB61 !important;\n    }\n    .elementor-element-tp_cats_grid ul.products li.product-category .woocommerce-loop-category__title mark.count,\n    #tp_cats_grid ul.products li.product-category .woocommerce-loop-category__title mark.count {\n        background: transparent !important;\n        color: #A0A0A0 !important;\n        font-size: 13px !important;\n        font-weight: 400 !important;\n        display: block !important;\n    }\n    @media (max-width: 1024px) {\n        .elementor-element-tp_cats_grid ul.products.columns-5,\n        .elementor-element-tp_cats_grid ul.products,\n        #tp_cats_grid ul.products {\n            grid-template-columns: repeat(3, minmax(0, 1fr)) !important;\n        }\n    }\n    @media (max-width: 768px) {\n        .elementor-element-tp_cats_grid ul.products.columns-5,\n        .elementor-element-tp_cats_grid ul.products,\n        #tp_cats_grid ul.products {\n            grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n        }\n    }\n\n    /* ==========================================================================\n       2. SECCIÓN 2: TODAS LAS CATEGORÍAS DE PRODUCTOS EN 2 COLUMNAS\n       Selector exacto: .elementor-element-7c1cf6bd / #tp_all_cats_2col\n       ========================================================================== */\n    .elementor-element-7c1cf6bd ul.products,\n    #tp_all_cats_2col ul.products {\n        display: grid !important;\n        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;\n        gap: 20px !important;\n        width: 100% !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category,\n    #tp_all_cats_2col ul.products li.product-category {\n        width: 100% !important;\n        max-width: 100% !important;\n        margin: 0 !important;\n        float: none !important;\n        background: #18171B !important;\n        border: 1px solid rgba(234,187,97,0.18) !important;\n        border-radius: 12px !important;\n        overflow: hidden !important;\n        display: flex !important;\n        flex-direction: column !important;\n        transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category:hover,\n    #tp_all_cats_2col ul.products li.product-category:hover {\n        border-color: #EABB61 !important;\n        transform: translateY(-5px) !important;\n        box-shadow: 0 12px 28px rgba(234, 187, 97, 0.12) !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category a,\n    #tp_all_cats_2col ul.products li.product-category a {\n        display: flex !important;\n        flex-direction: column !important;\n        height: 100% !important;\n        text-decoration: none !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category img,\n    #tp_all_cats_2col ul.products li.product-category img {\n        width: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        height: auto !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        border-bottom: 1px solid rgba(255,255,255,0.08) !important;\n        margin: 0 !important;\n        display: block !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category .woocommerce-loop-category__title,\n    #tp_all_cats_2col ul.products li.product-category .woocommerce-loop-category__title {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 15px !important;\n        font-weight: 600 !important;\n        padding: 16px 12px !important;\n        text-align: center !important;\n        margin: 0 !important;\n        line-height: 1.35 !important;\n        background: #18171B !important;\n        flex-grow: 1 !important;\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        flex-direction: column !important;\n        gap: 5px !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category:hover .woocommerce-loop-category__title,\n    #tp_all_cats_2col ul.products li.product-category:hover .woocommerce-loop-category__title {\n        color: #EABB61 !important;\n    }\n    .elementor-element-7c1cf6bd ul.products li.product-category .woocommerce-loop-category__title mark.count,\n    #tp_all_cats_2col ul.products li.product-category .woocommerce-loop-category__title mark.count {\n        background: transparent !important;\n        color: #A0A0A0 !important;\n        font-size: 12px !important;\n        font-weight: 400 !important;\n        display: block !important;\n    }\n    @media (max-width: 768px) {\n        .elementor-element-7c1cf6bd ul.products,\n        #tp_all_cats_2col ul.products {\n            grid-template-columns: repeat(1, minmax(0, 1fr)) !important;\n        }\n    }\n\n    \n    /* ==========================================================================\n       3. WOOCOMMERCE CHECKOUT PAGE (.woocommerce-checkout) - ULTRA LUXURY ARCHITECTURAL DESIGN\n       Matches exactly the borderless glassmorphism aesthetic of the luxury Cart\n       ========================================================================== */\n\n    /* Main Checkout Container & Grid */\n    .woocommerce-checkout form.checkout {\n        max-width: 1320px !important;\n        margin: 0 auto !important;\n        display: grid !important;\n        grid-template-columns: 1.15fr 0.85fr !important;\n        gap: 50px !important;\n        align-items: start !important;\n    }\n    .woocommerce-checkout form.checkout > .woocommerce-NoticeGroup,\n    .woocommerce-checkout form.checkout > .woocommerce-error,\n    .woocommerce-checkout form.checkout > .woocommerce-message {\n        grid-column: 1 / -1 !important;\n        width: 100% !important;\n    }\n\n    /* Left Column: Customer Details Form (#customer_details) */\n    .woocommerce-checkout #customer_details {\n        grid-column: 1 / 2 !important;\n        width: 100% !important;\n        background: linear-gradient(145deg, #1D1C23 0%, #15141A 100%) !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        border-radius: 24px !important;\n        padding: 44px 40px !important;\n        box-shadow: 0 25px 60px rgba(0,0,0,0.6) !important;\n        box-sizing: border-box !important;\n    }\n    .woocommerce-checkout #customer_details .col-1,\n    .woocommerce-checkout #customer_details .col-2 {\n        width: 100% !important;\n        float: none !important;\n        max-width: 100% !important;\n        padding: 0 !important;\n        margin-bottom: 36px !important;\n    }\n    .woocommerce-checkout #customer_details .col-2:last-child {\n        margin-bottom: 0 !important;\n    }\n\n    /* Section Headings inside Customer Details */\n    .woocommerce-checkout #customer_details h3 {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 700 !important;\n        font-size: 24px !important;\n        margin-top: 0 !important;\n        margin-bottom: 28px !important;\n        padding-bottom: 16px !important;\n        border-bottom: 2px solid #EABB61 !important;\n        display: inline-block !important;\n    }\n\n    /* Form Fields & Labels */\n    .woocommerce-checkout form.checkout .form-row {\n        margin-bottom: 22px !important;\n    }\n    .woocommerce-checkout form.checkout .form-row label {\n        color: #D0D0D0 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 14px !important;\n        font-weight: 600 !important;\n        margin-bottom: 8px !important;\n        display: block !important;\n    }\n    .woocommerce-checkout form.checkout .form-row input.input-text,\n    .woocommerce-checkout form.checkout .form-row select,\n    .woocommerce-checkout form.checkout .form-row textarea,\n    .woocommerce-checkout .select2-container .select2-selection--single {\n        width: 100% !important;\n        background: #141317 !important;\n        border: 1px solid rgba(255, 255, 255, 0.16) !important;\n        border-radius: 12px !important;\n        color: #FFFFFF !important;\n        padding: 14px 18px !important;\n        height: 52px !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 15px !important;\n        font-weight: 500 !important;\n        box-sizing: border-box !important;\n        transition: all 0.3s ease !important;\n    }\n    .woocommerce-checkout form.checkout .form-row textarea {\n        height: 120px !important;\n        padding: 16px 18px !important;\n    }\n    .woocommerce-checkout form.checkout .form-row input.input-text:focus,\n    .woocommerce-checkout form.checkout .form-row textarea:focus,\n    .woocommerce-checkout form.checkout .form-row select:focus,\n    .woocommerce-checkout .select2-container--default .select2-selection--single:focus {\n        border-color: #EABB61 !important;\n        box-shadow: 0 0 16px rgba(234, 187, 97, 0.28) !important;\n        outline: none !important;\n    }\n    .woocommerce-checkout .select2-container--default .select2-selection--single .select2-selection__rendered {\n        color: #FFFFFF !important;\n        line-height: 24px !important;\n        padding-left: 0 !important;\n    }\n    .woocommerce-checkout .select2-container--default .select2-selection--single .select2-selection__arrow {\n        height: 50px !important;\n        right: 14px !important;\n    }\n    .woocommerce-checkout .select2-dropdown {\n        background: #1D1C23 !important;\n        border: 1px solid #EABB61 !important;\n        border-radius: 12px !important;\n        color: #FFFFFF !important;\n        overflow: hidden !important;\n        z-index: 99999 !important;\n    }\n    .woocommerce-checkout .select2-container--default .select2-results__option--highlighted[aria-selected],\n    .woocommerce-checkout .select2-container--default .select2-results__option--highlighted[data-selected] {\n        background: #EABB61 !important;\n        color: #111014 !important;\n    }\n\n    /* Right Column: Order Review & Payment Card */\n    .woocommerce-checkout #order_review_heading {\n        grid-column: 2 / 3 !important;\n        grid-row: 1 / 2 !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 700 !important;\n        font-size: 24px !important;\n        margin: 0 0 -20px 0 !important;\n        padding: 0 !important;\n        z-index: 10 !important;\n        pointer-events: none !important;\n        display: none !important; /* Title merged into the box below for ultra luxury cohesion */\n    }\n    .woocommerce-checkout #order_review {\n        grid-column: 2 / 3 !important;\n        grid-row: 1 / 3 !important;\n        width: 100% !important;\n        background: linear-gradient(145deg, #1D1C23 0%, #15141A 100%) !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        border-radius: 24px !important;\n        padding: 44px 40px !important;\n        box-shadow: 0 25px 60px rgba(0,0,0,0.6) !important;\n        box-sizing: border-box !important;\n        position: sticky !important;\n        top: 130px !important;\n    }\n\n    /* Custom Heading inside review card */\n    .woocommerce-checkout #order_review::before {\n        content: \"Resumen del Pedido\" !important;\n        display: inline-block !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 700 !important;\n        font-size: 24px !important;\n        margin-bottom: 28px !important;\n        padding-bottom: 16px !important;\n        border-bottom: 2px solid #EABB61 !important;\n        width: 100% !important;\n    }\n\n    /* Review Order Table */\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table {\n        background: transparent !important;\n        border: none !important;\n        width: 100% !important;\n        margin-bottom: 36px !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table th,\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table td {\n        background: transparent !important;\n        border: none !important;\n        padding: 20px 4px !important;\n        border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table th {\n        font-size: 15px !important;\n        font-weight: 600 !important;\n        color: #A0A0A0 !important;\n        text-align: left !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table td {\n        font-size: 16px !important;\n        font-weight: 700 !important;\n        text-align: right !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total th,\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total td {\n        border-bottom: none !important;\n        border-top: 1px solid rgba(234, 187, 97, 0.3) !important;\n        padding-top: 28px !important;\n        padding-bottom: 14px !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total th {\n        color: #FFFFFF !important;\n        font-size: 18px !important;\n        font-weight: 700 !important;\n    }\n    .woocommerce-checkout table.woocommerce-checkout-review-order-table tr.order-total td {\n        color: #EABB61 !important;\n        font-size: 28px !important;\n        font-weight: 800 !important;\n    }\n\n    /* Payment Methods Box (#payment) */\n    .woocommerce-checkout #payment {\n        background: #141317 !important;\n        border: 1px solid rgba(255, 255, 255, 0.1) !important;\n        border-radius: 18px !important;\n        padding: 28px !important;\n        margin-top: 24px !important;\n    }\n    .woocommerce-checkout #payment ul.payment_methods {\n        list-style: none !important;\n        margin: 0 0 24px 0 !important;\n        padding: 0 !important;\n        border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;\n        padding-bottom: 20px !important;\n    }\n    .woocommerce-checkout #payment ul.payment_methods li {\n        margin-bottom: 16px !important;\n    }\n    .woocommerce-checkout #payment ul.payment_methods li:last-child {\n        margin-bottom: 0 !important;\n    }\n    .woocommerce-checkout #payment ul.payment_methods li label {\n        color: #FFFFFF !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-weight: 600 !important;\n        font-size: 16px !important;\n        margin-left: 10px !important;\n        cursor: pointer !important;\n    }\n    .woocommerce-checkout #payment div.payment_box {\n        background: #1D1C23 !important;\n        color: #B0B0B0 !important;\n        border-radius: 12px !important;\n        padding: 18px !important;\n        margin-top: 14px !important;\n        font-size: 14px !important;\n        line-height: 1.5 !important;\n        border-left: 3px solid #EABB61 !important;\n    }\n    .woocommerce-checkout #payment div.payment_box::before {\n        display: none !important;\n    }\n\n    /* Terms & Conditions Checkbox */\n    .woocommerce-checkout #payment .form-row.terms {\n        margin: 20px 0 !important;\n        padding: 0 !important;\n    }\n    .woocommerce-checkout #payment .form-row.terms label.woocommerce-form__label-for-checkbox {\n        color: #D0D0D0 !important;\n        font-size: 14px !important;\n        line-height: 1.5 !important;\n    }\n    .woocommerce-checkout #payment .form-row.terms label a {\n        color: #EABB61 !important;\n        text-decoration: underline !important;\n    }\n\n    /* Place Order CTA Button (#place_order) */\n    .woocommerce-checkout #payment #place_order {\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        width: 100% !important;\n        height: 62px !important;\n        background: linear-gradient(135deg, #EABB61 0%, #C89442 100%) !important;\n        color: #111014 !important;\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 800 !important;\n        letter-spacing: 1.5px !important;\n        text-transform: uppercase !important;\n        border-radius: 31px !important;\n        border: none !important;\n        cursor: pointer !important;\n        box-shadow: 0 12px 30px rgba(234, 187, 97, 0.35) !important;\n        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;\n        margin-top: 12px !important;\n    }\n    .woocommerce-checkout #payment #place_order:hover {\n        transform: translateY(-4px) scale(1.01) !important;\n        box-shadow: 0 18px 40px rgba(234, 187, 97, 0.5) !important;\n        background: linear-gradient(135deg, #F3C978 0%, #D8A350 100%) !important;\n    }\n\n    /* Responsive Mobile & Tablet Checkout */\n    @media (max-width: 1023px) {\n        .woocommerce-checkout form.checkout {\n            grid-template-columns: 1fr !important;\n            gap: 36px !important;\n        }\n        .woocommerce-checkout #customer_details,\n        .woocommerce-checkout #order_review {\n            grid-column: 1 / 2 !important;\n            padding: 30px 24px !important;\n        }\n        .woocommerce-checkout #order_review {\n            position: relative !important;\n            top: 0 !important;\n        }\n    }\n\n    \n    /* === SINGLE PRODUCT & SPECIFICATIONS CSS (Fase 2) === */\n    /* 1. SINGLE PRODUCT SQUARE GALLERY & THUMBNAILS (UNIFORM 1:1 ASPECT RATIO FOR ALL SIZES) */\n    .woocommerce div.product div.images .woocommerce-product-gallery__wrapper,\n    .woocommerce div.product div.images .woocommerce-product-gallery__image {\n        width: 100% !important;\n        max-width: 100% !important;\n    }\n    .woocommerce div.product div.images .woocommerce-product-gallery__image a {\n        display: block !important;\n        width: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        border-radius: 20px !important;\n        overflow: hidden !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        background: #141317 !important;\n        box-shadow: 0 20px 50px rgba(0,0,0,0.55) !important;\n    }\n    .woocommerce div.product div.images .woocommerce-product-gallery__image a img,\n    .woocommerce div.product div.images .woocommerce-product-gallery__image img {\n        width: 100% !important;\n        height: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        display: block !important;\n        margin: 0 !important;\n        border-radius: 20px !important;\n        transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1) !important;\n    }\n    .woocommerce div.product div.images .woocommerce-product-gallery__image a:hover img {\n        transform: scale(1.04) !important;\n    }\n\n    /* Gallery Thumbnails List (Uniform 1:1 Squares) */\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs {\n        display: flex !important;\n        flex-wrap: wrap !important;\n        gap: 14px !important;\n        margin-top: 18px !important;\n        padding: 0 !important;\n        list-style: none !important;\n    }\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li {\n        width: 90px !important;\n        height: 90px !important;\n        margin: 0 !important;\n        border-radius: 14px !important;\n        overflow: hidden !important;\n        border: 1px solid rgba(255, 255, 255, 0.14) !important;\n        background: #18171C !important;\n        cursor: pointer !important;\n        transition: all 0.35s ease !important;\n        flex: 0 0 90px !important;\n    }\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li img {\n        width: 100% !important;\n        height: 100% !important;\n        aspect-ratio: 1 / 1 !important;\n        object-fit: cover !important;\n        object-position: center !important;\n        display: block !important;\n        margin: 0 !important;\n        opacity: 0.55 !important;\n        border: none !important;\n        border-radius: 0 !important;\n        transition: all 0.35s ease !important;\n    }\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li img.flex-active,\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li:hover img {\n        opacity: 1 !important;\n        transform: scale(1.06) !important;\n    }\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li:has(img.flex-active),\n    .woocommerce div.product div.images ol.flex-control-nav.flex-control-thumbs li:hover {\n        border-color: #EABB61 !important;\n        box-shadow: 0 6px 18px rgba(234, 187, 97, 0.35) !important;\n    }\n\n    /* 2. SINGLE PRODUCT SHARE BLOCK (`Compartir Ficha Técnica & Proyecto`) - SLEEK HORIZONTAL PILL CARD */\n    .elementor-element.elementor-element-47e498a8,\n    .elementor-element.elementor-element-1546e2a4 {\n        border-top: none !important;\n        border-bottom: none !important;\n        padding: 0 !important;\n    }\n    /* Parent container wrapping both share columns */\n    .elementor-element:has(> .elementor-element-47e498a8):has(> .elementor-element-1546e2a4),\n    .elementor-section:has(.elementor-element-2edc6b38):has(.elementor-element-74e0dd5) {\n        background: linear-gradient(145deg, #1D1C23 0%, #15141A 100%) !important;\n        border: 1px solid rgba(234, 187, 97, 0.28) !important;\n        border-radius: 18px !important;\n        padding: 24px 30px !important;\n        margin-top: 36px !important;\n        display: flex !important;\n        flex-direction: row !important;\n        align-items: center !important;\n        justify-content: space-between !important;\n        flex-wrap: wrap !important;\n        gap: 20px !important;\n        box-shadow: 0 15px 35px rgba(0,0,0,0.45) !important;\n    }\n    /* Force columns inside share row to auto flex side by side */\n    .elementor-element:has(> .elementor-element-47e498a8):has(> .elementor-element-1546e2a4) > .elementor-column {\n        width: auto !important;\n        max-width: 100% !important;\n        flex: 0 1 auto !important;\n    }\n    /* Title heading (`Compartir Ficha...`) on one clean horizontal line */\n    .elementor-element-2edc6b38 .elementor-heading-title,\n    .elementor-element-2edc6b38 h1, .elementor-element-2edc6b38 h2, .elementor-element-2edc6b38 h3, .elementor-element-2edc6b38 h4, .elementor-element-2edc6b38 h5, .elementor-element-2edc6b38 h6 {\n        font-family: \"Outfit\", sans-serif !important;\n        font-size: 16px !important;\n        font-weight: 700 !important;\n        color: #FFFFFF !important;\n        letter-spacing: 0.5px !important;\n        margin: 0 !important;\n        white-space: normal !important;\n        line-height: 1.4 !important;\n        display: flex !important;\n        align-items: center !important;\n        gap: 10px !important;\n    }\n    .elementor-element-2edc6b38 .elementor-heading-title::before {\n        content: \"⚡\";\n        font-size: 18px;\n    }\n    /* Share buttons alignment & luxury gold styling */\n    .elementor-element-74e0dd5 .elementor-widget-container {\n        display: flex !important;\n        align-items: center !important;\n        gap: 12px !important;\n    }\n    .elementor-element-74e0dd5 .elementor-share-buttons--skin-flat .elementor-share-btn,\n    .elementor-element-74e0dd5 .elementor-share-btn {\n        width: 44px !important;\n        height: 44px !important;\n        border-radius: 50% !important;\n        background: rgba(255, 255, 255, 0.06) !important;\n        border: 1px solid rgba(255, 255, 255, 0.14) !important;\n        display: inline-flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        color: #FFFFFF !important;\n        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;\n        padding: 0 !important;\n        margin: 0 !important;\n    }\n    .elementor-element-74e0dd5 .elementor-share-btn:hover {\n        background: #EABB61 !important;\n        color: #111014 !important;\n        border-color: #EABB61 !important;\n        transform: translateY(-3px) scale(1.08) !important;\n        box-shadow: 0 8px 20px rgba(234, 187, 97, 0.4) !important;\n    }\n    .elementor-element-74e0dd5 .elementor-share-btn .elementor-share-btn__icon {\n        font-size: 18px !important;\n        margin: 0 !important;\n        padding: 0 !important;\n        color: inherit !important;\n    }\n\n    </style>\n    <?php\n}, 999);','','global',0,10,1,'2026-07-10 12:10:59',1,NULL),(6,'Tecnopremium: Sistema Dinámico de Proyectos Realizados + CPT + Shortcode','','// 1. REGISTRAR CUSTOM POST TYPE \"tp_project\" PARA PROYECTOS REALIZADOS\nadd_action(\"init\", function() {\n    register_post_type(\"tp_project\", [\n        \"labels\" => [\n            \"name\"          => \"Proyectos Realizados\",\n            \"singular_name\" => \"Proyecto Realizado\",\n            \"add_new\"       => \"Añadir Nuevo Proyecto\",\n            \"add_new_item\"  => \"Añadir Proyecto Realizado\",\n            \"edit_item\"     => \"Editar Proyecto\",\n            \"menu_name\"     => \"🏛️ Proyectos Realizados\"\n        ],\n        \"public\"             => true,\n        \"has_archive\"        => true,\n        \"rewrite\"            => [\"slug\" => \"portafolio-proyectos\"],\n        \"supports\"           => [\"title\", \"editor\", \"thumbnail\", \"excerpt\", \"custom-fields\"],\n        \"show_in_rest\"       => true,\n        \"menu_position\"      => 5\n    ]);\n});\n\n// 2. FUNCIÓN DE RENDERIZADO PARA SHORTCODE DINÁMICO\nfunction tp_render_proyectos($atts = []) {\n    $q = new WP_Query([\n        \"post_type\"      => \"tp_project\",\n        \"posts_per_page\" => -1,\n        \"post_status\"    => \"publish\",\n        \"orderby\"        => \"date\",\n        \"order\"          => \"DESC\"\n    ]);\n    \n    if (!$q->have_posts()) {\n        return \"<p style=\'color: #B5B5B5; text-align: center; padding: 40px;\'>Actualmente no hay proyectos publicados.</p>\";\n    }\n    \n    $html = \'\n    <style>\n    .tp-projects-grid {\n        display: grid;\n        grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));\n        gap: 30px;\n        margin: 40px 0;\n    }\n    .tp-project-card {\n        background: #18171B;\n        border: 1px solid rgba(234, 187, 97, 0.22);\n        border-radius: 12px;\n        overflow: hidden;\n        display: flex;\n        flex-direction: column;\n        transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;\n    }\n    .tp-project-card:hover {\n        transform: translateY(-7px);\n        border-color: #EABB61;\n        box-shadow: 0 15px 35px rgba(234, 187, 97, 0.15);\n    }\n    .tp-project-thumb {\n        position: relative;\n        height: 240px;\n        overflow: hidden;\n        background: #111;\n    }\n    .tp-project-thumb img {\n        width: 100%;\n        height: 100%;\n        object-fit: cover;\n        transition: transform 0.5s ease;\n    }\n    .tp-project-card:hover .tp-project-thumb img {\n        transform: scale(1.06);\n    }\n    .tp-project-badge {\n        position: absolute;\n        top: 15px;\n        right: 15px;\n        background: rgba(24, 23, 27, 0.9);\n        color: #EABB61;\n        border: 1px solid #EABB61;\n        font-size: 0.78rem;\n        font-weight: 700;\n        padding: 6px 12px;\n        border-radius: 20px;\n        text-transform: uppercase;\n        letter-spacing: 0.5px;\n    }\n    .tp-project-content {\n        padding: 26px;\n        display: flex;\n        flex-direction: column;\n        flex-grow: 1;\n        justify-content: space-between;\n    }\n    .tp-project-meta {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 12px;\n        margin-bottom: 14px;\n        font-size: 0.85rem;\n        color: #A0A0A0;\n    }\n    .tp-project-meta span {\n        display: inline-flex;\n        align-items: center;\n        gap: 5px;\n    }\n    .tp-project-title {\n        font-size: 1.3rem;\n        color: #FFFFFF;\n        font-weight: 700;\n        margin-bottom: 12px;\n        line-height: 1.35;\n    }\n    .tp-project-desc {\n        color: #B5B5B5;\n        font-size: 0.95rem;\n        line-height: 1.55;\n        margin-bottom: 22px;\n    }\n    .tp-project-brands {\n        padding-top: 15px;\n        border-top: 1px solid rgba(255,255,255,0.08);\n        font-size: 0.85rem;\n        color: #EABB61;\n        font-weight: 600;\n    }\n    </style>\n    <div class=\"tp-projects-grid\">\';\n    \n    while ($q->have_posts()) {\n        $q->the_post();\n        $pid = get_the_ID();\n        $thumb_url = get_the_post_thumbnail_url($pid, \"large\");\n        if (!$thumb_url) {\n            $img_meta = get_post_meta($pid, \"tp_project_image_url\", true);\n            $thumb_url = $img_meta ?: site_url(\"/wp-content/uploads/2026/07/Elton_Foto-Home.jpg\");\n        }\n        \n        $location = get_post_meta($pid, \"tp_project_location\", true) ?: (get_post_meta($pid, \"tp_proj_location\", true) ?: \"España\");\n        $year     = get_post_meta($pid, \"tp_proj_year\", true) ?: \"2026\";\n        $brands   = get_post_meta($pid, \"tp_project_category\", true) ?: (get_post_meta($pid, \"tp_proj_brands\", true) ?: \"Tecnopremium Wellness\");\n        $scope    = get_post_meta($pid, \"tp_proj_scope\", true) ?: \"Llave en Mano\";\n        \n        $html .= \'\n        <div class=\"tp-project-card\">\n            <div class=\"tp-project-thumb\">\n                <img src=\"\' . esc_url($thumb_url) . \'\" alt=\"\' . esc_attr(get_the_title()) . \'\">\n                <span class=\"tp-project-badge\">\' . esc_html($scope) . \'</span>\n            </div>\n            <div class=\"tp-project-content\">\n                <div>\n                    <div class=\"tp-project-meta\">\n                        <span>📍 \' . esc_html($location) . \'</span>\n                        <span>📅 \' . esc_html($year) . \'</span>\n                    </div>\n                    <h3 class=\"tp-project-title\">\' . esc_html(get_the_title()) . \'</h3>\n                    <div class=\"tp-project-desc\">\' . get_the_excerpt() . \'</div>\n                </div>\n                <div class=\"tp-project-brands\">\n                    ⚡ Categoría / Marcas: \' . esc_html($brands) . \'\n                </div>\n            </div>\n        </div>\';\n    }\n    wp_reset_postdata();\n    \n    $html .= \'</div>\';\n    return $html;\n}\n\nadd_shortcode(\"teknopremium_proyectos\", \"tp_render_proyectos\");\nadd_shortcode(\"tp_proyectos_realizados\", \"tp_render_proyectos\");','','global',0,10,1,'2026-07-13 10:27:19',1,NULL),(7,'Tecnopremium: Shortcodes de Cabecera (Iconos de Usuario y Carrito para Lupa)','Shortcodes para iconos limpios en la cabecera (junto a la lupa): [tp_header_icons], [tp_user_icon], [tp_cart_icon]','function tp_get_svg_user($logged_in = false) {\n    if ($logged_in) {\n        return \'<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"></path><circle cx=\"8.5\" cy=\"7\" r=\"4\"></circle><polyline points=\"17 11 19 13 23 9\"></polyline></svg>\';\n    }\n    return \'<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"></path><circle cx=\"12\" cy=\"7\" r=\"4\"></circle></svg>\';\n}\n\nfunction tp_get_svg_cart() {\n    return \'<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\"></path><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><path d=\"M16 10a4 4 0 0 1-8 0\"></path></svg>\';\n}\n\nadd_shortcode(\"tp_header_icons\", function($atts) {\n    $cart_count = function_exists(\"WC\") && WC()->cart ? WC()->cart->get_cart_contents_count() : 0;\n    $cart_url = function_exists(\"wc_get_cart_url\") ? wc_get_cart_url() : home_url(\"/cart/\");\n    $account_url = function_exists(\"wc_get_page_permalink\") ? wc_get_page_permalink(\"myaccount\") : home_url(\"/my-account/\");\n    $user_title = is_user_logged_in() ? \"Mi Cuenta Profesional\" : \"Iniciar Sesión\";\n    \n    ob_start();\n    ?>\n    <div class=\"tp-header-icons-wrap\">\n        <a href=\"<?php echo esc_url($account_url); ?>\" class=\"tp-header-icon tp-user-icon\" title=\"<?php echo esc_attr($user_title); ?>\" aria-label=\"<?php echo esc_attr($user_title); ?>\">\n            <?php echo tp_get_svg_user(is_user_logged_in()); ?>\n        </a>\n        <a href=\"<?php echo esc_url($cart_url); ?>\" class=\"tp-header-icon tp-cart-icon\" title=\"Carrito de compra\" aria-label=\"Carrito de compra\">\n            <?php echo tp_get_svg_cart(); ?>\n            <span class=\"tp-cart-badge\"><?php echo intval($cart_count); ?></span>\n        </a>\n    </div>\n    <?php\n    return ob_get_clean();\n});\n\nadd_shortcode(\"tp_user_icon\", function() {\n    $account_url = function_exists(\"wc_get_page_permalink\") ? wc_get_page_permalink(\"myaccount\") : home_url(\"/my-account/\");\n    $user_title = is_user_logged_in() ? \"Mi Cuenta Profesional\" : \"Iniciar Sesión\";\n    return \'<a href=\"\' . esc_url($account_url) . \'\" class=\"tp-header-icon tp-user-icon\" title=\"\' . esc_attr($user_title) . \'\" aria-label=\"\' . esc_attr($user_title) . \'\">\' . tp_get_svg_user(is_user_logged_in()) . \'</a>\';\n});\n\nadd_shortcode(\"tp_cart_icon\", function() {\n    $cart_count = function_exists(\"WC\") && WC()->cart ? WC()->cart->get_cart_contents_count() : 0;\n    $cart_url = function_exists(\"wc_get_cart_url\") ? wc_get_cart_url() : home_url(\"/cart/\");\n    return \'<a href=\"\' . esc_url($cart_url) . \'\" class=\"tp-header-icon tp-cart-icon\" title=\"Carrito de compra\" aria-label=\"Carrito de compra\">\' . tp_get_svg_cart() . \'<span class=\"tp-cart-badge\">\' . intval($cart_count) . \'</span></a>\';\n});\n\nadd_filter(\"woocommerce_add_to_cart_fragments\", function($fragments) {\n    $count = function_exists(\"WC\") && WC()->cart ? WC()->cart->get_cart_contents_count() : 0;\n    $fragments[\"span.tp-cart-badge\"] = \'<span class=\"tp-cart-badge\">\' . intval($count) . \'</span>\';\n    return $fragments;\n});\n\nadd_action(\"wp_head\", function() {\n    ?>\n    <style id=\"tp-header-icons-css\">\n    .tp-header-icons-wrap {\n        display: inline-flex !important;\n        align-items: center !important;\n        gap: 22px !important;\n        vertical-align: middle !important;\n    }\n    a.tp-header-icon {\n        display: inline-flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        color: #FFF !important;\n        text-decoration: none !important;\n        position: relative !important;\n        transition: color 0.3s, transform 0.2s !important;\n        line-height: 1 !important;\n        padding: 4px !important;\n        cursor: pointer !important;\n    }\n    a.tp-header-icon svg {\n        width: 25px !important;\n        height: 25px !important;\n        display: block !important;\n        stroke: currentColor !important;\n        transition: stroke 0.3s !important;\n    }\n    a.tp-header-icon:hover {\n        color: #EABB61 !important;\n        transform: scale(1.1) !important;\n    }\n    a.tp-cart-icon span.tp-cart-badge {\n        position: absolute !important;\n        top: -4px !important;\n        right: -8px !important;\n        background: #EABB61 !important;\n        color: #111 !important;\n        font-size: 0.72rem !important;\n        font-weight: 800 !important;\n        padding: 2px 5px !important;\n        border-radius: 20px !important;\n        line-height: 1 !important;\n        min-width: 17px !important;\n        height: 17px !important;\n        display: flex !important;\n        align-items: center !important;\n        justify-content: center !important;\n        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.6) !important;\n        transition: transform 0.2s !important;\n    }\n    a.tp-cart-icon:hover span.tp-cart-badge {\n        transform: scale(1.08) !important;\n    }\n    </style>\n    <?php\n});','','global',0,10,1,'2026-07-14 13:42:55',1,NULL),(8,'Tecnopremium: Sistema B2B de Roles Profesionales, Descuentos Automáticos y Tracking de Prescriptores','Gestiona los roles B2B (interiorista, prescriptor, distribuidor), aplica descuentos automáticos según rol al conectar sesión y registra cupones de prescriptores (Fase 3 Reunión Tecnoterrazas).','<?php\n/**\n * TECNOPREMIUM · SISTEMA B2B DE ROLES PROFESIONALES, DESCUENTOS AUTOMÁTICOS Y TRACKING\n * Fase 3 - Plan de Acción (Reunión Tecnoterrazas)\n * \n * 1. Registro de Roles Profesionales (Interiorista, Prescriptor, Distribuidor)\n * 2. Aplicación Automática de Descuentos en Catálogo, Ficha, Carrito y Checkout al hacer Login\n * 3. Etiquetado y Tracking Comercial de Cupones de Prescriptor (ej. ESTUDIO27)\n */\n\nif (!defined(\"ABSPATH\")) exit;\n\n// 1. REGISTRAR ROLES PROFESIONALES EN WORDPRESS\nadd_action(\"init\", function() {\n    if (!get_role(\"interiorista\")) {\n        add_role(\"interiorista\", \"Interiorista / Arquitecto (B2B 15%)\", get_role(\"customer\")->capabilities);\n    }\n    if (!get_role(\"prescriptor\")) {\n        add_role(\"prescriptor\", \"Prescriptor VIP / Estudio (B2B 10%)\", get_role(\"customer\")->capabilities);\n    }\n    if (!get_role(\"distribuidor\")) {\n        add_role(\"distribuidor\", \"Distribuidor Oficial (B2B 30%)\", get_role(\"customer\")->capabilities);\n    }\n});\n\n// 2. OBTENER EL PORCENTAJE DE DESCUENTO SEGÚN EL ROL DEL USUARIO CONECTADO\nfunction tp_get_user_role_discount() {\n    if (!is_user_logged_in()) return 0;\n     = wp_get_current_user();\n     = (array) ;\n    \n    if (in_array(\"distribuidor\", )) return 30; // 30% descuento\n    if (in_array(\"interiorista\", )) return 15; // 15% descuento\n    if (in_array(\"prescriptor\", )) return 10;  // 10% descuento\n    \n    return 0; // Estándar customer sin descuento automático por rol\n}\n\n// 3. APLICAR DESCUENTO AUTOMÁTICO AL PRECIO DEL PRODUCTO EN CARRITO Y CHECKOUT\nadd_action(\"woocommerce_cart_calculate_fees\", function() {\n    if (is_admin() && !defined(\"DOING_AJAX\")) return;\n    \n     = tp_get_user_role_discount();\n    if ( <= 0) return;\n    \n     = ();\n     = -1 * ( * ( / 100));\n    \n     = \"Descuento Profesional\";\n     = wp_get_current_user();\n    if (in_array(\"distribuidor\", (array)))  = \"Tarifa Distribuidor Oficial (-\" .  . \"%)\";\n    elseif (in_array(\"interiorista\", (array)))  = \"Tarifa Interiorista/Arquitecto (-\" .  . \"%)\";\n    elseif (in_array(\"prescriptor\", (array)))  = \"Tarifa Prescriptor VIP (-\" .  . \"%)\";\n    \n    (, , true, \"\");\n});\n\n// 4. MOSTRAR ETIQUETA VISUAL DE TARIFA B2B EN LA FICHA DE PRODUCTO Y CATÁLOGO PARA USUARIOS LOGUEADOS\nadd_filter(\"woocommerce_get_price_html\", function(, ) {\n    if (is_admin()) return ;\n     = tp_get_user_role_discount();\n    if ( <= 0) return ;\n    \n     = (float) ();\n    if ( <= 0)  = (float) ();\n    if ( <= 0) return ;\n    \n     =  * (1 - ( / 100));\n    \n     = \"<div style=\\\"background: #EABB61; color: #141317; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px; display: inline-block; margin-bottom: 4px; text-transform: uppercase; letter-spacing: 0.5px;\\\">Tarifa B2B -\" .  . \"%</div><br>\";\n     = wc_format_price_range(, );\n     = \"<del style=\\\"color: #888; font-size: 16px; margin-right: 8px;\\\">\" . wc_price() . \"</del> <ins style=\\\"color: #EABB61; font-weight: 700; text-decoration: none;\\\">\" . wc_price() . \"</ins>\";\n    \n    return  . ;\n}, 10, 2);\n\n// 5. TRACKING COMERCIAL Y REGISTRO DE PRESCRIPTORES POR CUPÓN (Ej. ESTUDIO27)\nadd_action(\"woocommerce_checkout_order_processed\", function() {\n     = wc_get_order();\n    if (!) return;\n    \n     = ();\n    foreach ( as ) {\n        if (stripos(, \"estudio\") !== false || stripos(, \"prescriptor\") !== false || stripos(, \"arq\") !== false) {\n            // Guardar en metadatos del pedido para informes comerciales\n            (\"_prescriptor_referral_code\", strtoupper());\n            (\"_prescriptor_order_date\", current_time(\"mysql\"));\n            ();\n            break;\n        }\n    }\n}, 10, 1);','woocommerce, b2b, roles, descuentos, prescriptores','global',0,10,1,'2026-07-17 13:37:29',1,NULL),(9,'Tecnopremium: Estilos Globales, Copywriting SEO y Pulido Arquitectónico Elementor','Estilos arquitectónicos y de copywriting de lujo para mejorar legibilidad, tipografía, acordiones FAQ con esquema SEO y formularios en todas las páginas creadas con widgets de Elementor.','add_action(\"wp_head\", function() {\n    ?>\n    <style id=\"tecnopremium-global-copy-css\">\n    /* ==========================================================================\n       TECNOPREMIUM GLOBAL ARCHITECTURAL & COPYWRITING STYLING\n       ========================================================================== */\n    \n    /* 1. Global Typography Polish & Readability */\n    .elementor-heading-title {\n        line-height: 1.25 !important;\n        letter-spacing: -0.3px;\n    }\n    .elementor-widget-heading h1.elementor-heading-title {\n        font-weight: 800 !important;\n        letter-spacing: -0.8px !important;\n    }\n    .elementor-widget-heading h2.elementor-heading-title {\n        font-weight: 700 !important;\n        letter-spacing: -0.5px !important;\n    }\n    .elementor-widget-text-editor p {\n        line-height: 1.75 !important;\n        font-size: 16px !important;\n        color: rgba(255, 255, 255, 0.88) !important;\n        margin-bottom: 1.2rem !important;\n    }\n    .elementor-widget-text-editor strong {\n        color: #EABB61 !important;\n        font-weight: 700 !important;\n    }\n\n    /* 2. FAQ Accordion Luxury Glassmorphism & SEO Polish */\n    .elementor-widget-accordion .elementor-accordion-item {\n        background: rgba(255, 255, 255, 0.03) !important;\n        border: 1px solid rgba(255, 255, 255, 0.08) !important;\n        border-radius: 14px !important;\n        margin-bottom: 16px !important;\n        overflow: hidden !important;\n        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;\n    }\n    .elementor-widget-accordion .elementor-accordion-item:hover {\n        background: rgba(255, 255, 255, 0.06) !important;\n        border-color: rgba(234, 187, 97, 0.35) !important;\n        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3) !important;\n    }\n    .elementor-widget-accordion .elementor-accordion-title {\n        padding: 22px 26px !important;\n        font-size: 17px !important;\n        font-weight: 600 !important;\n        color: #FFFFFF !important;\n        transition: color 0.3s ease !important;\n    }\n    .elementor-widget-accordion .elementor-active .elementor-accordion-title {\n        color: #EABB61 !important;\n        background: rgba(234, 187, 97, 0.08) !important;\n        border-bottom: 1px solid rgba(234, 187, 97, 0.2) !important;\n    }\n    .elementor-widget-accordion .elementor-accordion-content {\n        padding: 24px 26px !important;\n        color: rgba(255, 255, 255, 0.85) !important;\n        line-height: 1.8 !important;\n        font-size: 15.5px !important;\n        background: rgba(20, 19, 23, 0.6) !important;\n    }\n\n    /* 3. Global CTA Button Architectural Hover State */\n    .elementor-widget-button .elementor-button {\n        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;\n    }\n    .elementor-widget-button .elementor-button:hover {\n        transform: translateY(-3px) !important;\n        box-shadow: 0 12px 28px rgba(234, 187, 97, 0.3) !important;\n    }\n\n    /* 4. Contact & Forms Luxury Styling */\n    .elementor-field-group .elementor-field {\n        background: rgba(255, 255, 255, 0.04) !important;\n        border: 1px solid rgba(255, 255, 255, 0.12) !important;\n        border-radius: 10px !important;\n        color: #FFFFFF !important;\n        padding: 14px 18px !important;\n        transition: all 0.3s ease !important;\n    }\n    .elementor-field-group .elementor-field:focus {\n        border-color: #EABB61 !important;\n        background: rgba(255, 255, 255, 0.07) !important;\n        box-shadow: 0 0 0 3px rgba(234, 187, 97, 0.15) !important;\n        outline: none !important;\n    }\n\n    /* 5. Mobile Responsive Adjustments */\n    @media (max-width: 768px) {\n        .elementor-widget-heading h1.elementor-heading-title {\n            font-size: 32px !important;\n        }\n        .elementor-widget-heading h2.elementor-heading-title {\n            font-size: 26px !important;\n        }\n        .elementor-widget-accordion .elementor-accordion-title {\n            padding: 16px 18px !important;\n            font-size: 15px !important;\n        }\n        .elementor-widget-accordion .elementor-accordion-content {\n            padding: 18px !important;\n        }\n    }\n    </style>\n    <?php\n}, 100);','elementor,seo,copywriting,luxury,css','global',0,10,1,'2026-07-20 16:36:51',1,NULL);
